    select('customer_segment', 'Customer segment', [['new', 'New'], ['repeat', 'Repeat'], ['vip', 'VIP']]),
    select('data_quality_status', 'Data quality status', [['ok', 'OK'], ['needs_review', 'Needs review']]),
