  products: [text('woo_product_id', 'Woo product ID')],
  line_items: [text('woo_line_item_id', 'Woo line item ID')],
  // One ticket per distinct sync problem, so re-running the backfill never duplicates tickets.
  tickets: [uniqueId('sync_error_key', 'Sync error key')],
};

const stage = (key, label, displayOrder, metadata) => ({ key, label, displayOrder, metadata });

const DEAL_PIPELINE = {
  label: 'WooCommerce',
  displayOrder: 1,
  stages: [
    stage('pending_payment', 'Pending payment', 0, { probability: '0.2' }),
    stage('paid', 'Paid', 1, { probability: '0.9' }),
    stage('closedwon', 'Closed won', 2, { probability: '1.0' }),
    stage('closedlost', 'Closed lost', 3, { probability: '0.0' }),
    stage('refunded', 'Refunded', 4, { probability: '0.0' }),
  ],
};

const TICKET_PIPELINE = {
  label: 'Integration errors',
  displayOrder: 1,
  stages: [
    stage('new', 'New', 0, { ticketState: 'OPEN' }),
    stage('resolved', 'Resolved', 1, { ticketState: 'CLOSED' }),
  ],
};

// ---- src/lib/retry.js ----
// Retry policy for HubSpot calls (flow F4). Ceiling: 100 requests / 10 s, batches of ≤100.

const MAX_ATTEMPTS = 3;

// 429 = rate limit, 423 = HubSpot's "Locked" during high sync volume, 5xx = transient server errors.
function shouldRetry(status) {
  return status === 429 || status === 423 || (status >= 500 && status <= 599);
}

// Exponential (1 s, 2 s, 4 s…), but never shorter than what the error needs: a 429 without Retry-After
// waits out the whole 10 s rate window; a 423 waits at least 2 s (HubSpot's guidance).
function backoffDelayMs(attempt, retryAfterHeader, status) {
  const retryAfter = Number(retryAfterHeader);
  if (retryAfterHeader != null && Number.isFinite(retryAfter) && retryAfter > 0) return retryAfter * 1000;
  const exponential = 1000 * 2 ** (attempt - 1);
  if (status === 429) return Math.max(exponential, 10000);
  if (status === 423) return Math.max(exponential, 2000);
  return exponential;
}

function chunk(items, size) {
  const out = [];
  for (let i = 0; i < items.length; i += size) out.push(items.slice(i, i + size));
  return out;
}

// ---- src/lib/mapping.js ----
// WooCommerce order → HubSpot CRM inputs. Pure functions, inlined into n8n Code nodes.

// Woo status → internal stage key. Real HubSpot stage ids come from hubspot-setup (.hubspot-ids.json).
const STAGE_BY_STATUS = {
  pending: 'pending_payment',
  'on-hold': 'pending_payment',
  processing: 'paid',
  completed: 'closedwon',
  cancelled: 'closedlost',
  failed: 'closedlost',
  refunded: 'refunded',
};

const PAID_STATUSES = new Set(['processing', 'completed']);

const FREE_EMAIL_DOMAINS = new Set([
  'gmail.com', 'googlemail.com', 'hotmail.com', 'outlook.com', 'live.com', 'yahoo.com', 'yahoo.com.ar',
  'icloud.com', 'aol.com', 'proton.me', 'protonmail.com',
]);

const money = (n) => (Math.round(n * 100) / 100).toFixed(2);

function refundTotal(order) {
  return (order.refunds ?? []).reduce((sum, r) => sum + Math.abs(Number(r.total) || 0), 0);
}

function netTotal(order) {
  return Math.max(0, Number(order.total) - refundTotal(order));
}

const isoUtc = (wooGmtDate) => new Date(`${wooGmtDate}Z`).toISOString();

function companyDomain(email) {
  const { value } = validateEmail(email);
  if (!value) return null;
  const domain = value.split('@')[1];
  return FREE_EMAIL_DOMAINS.has(domain) ? null : domain;
}

function planCompanies(orders) {
  const byDomain = new Map();
  for (const order of orders) {
    const domain = companyDomain(order.billing?.email);
    if (!domain) continue;
    const name = String(order.billing?.company ?? '').trim();
    const existing = byDomain.get(domain);
    if (!existing || (existing.name === domain && name)) byDomain.set(domain, { domain, name: name || domain });
  }
  return [...byDomain.values()];
}

function buildContactInput(order) {
  const { clean, issues } = validateCustomer(order.billing);
  const properties = {};
  for (const [key, value] of Object.entries(clean)) if (value) properties[key] = value;
  if (Number(order.customer_id) > 0) properties.woo_customer_id = String(order.customer_id);
  properties.data_quality_status = issues.length ? 'needs_review' : 'ok';
  properties.data_quality_issues = issues.join('; ');
  return { email: clean.email, properties, issues };
}

function buildProductInputs(orders) {
  const byId = new Map();
  for (const order of orders) {
    for (const item of order.line_items ?? []) {
      const id = String(item.product_id);
      if (byId.has(id)) continue;
      byId.set(id, {
        idProperty: 'woo_product_id',
        id,
        properties: { woo_product_id: id, name: item.name, price: money(Number(item.price)), hs_sku: item.sku || undefined },
      });
    }
  }
  return [...byId.values()];
}

function buildDealInput(order, { pipelineId, stageIds }) {
  const stageKey = STAGE_BY_STATUS[order.status];
  if (!stageKey) throw new Error(`Unknown Woo status "${order.status}" on order ${order.id}`);
  const id = String(order.id);
  const name = [order.billing?.first_name, order.billing?.last_name].filter(Boolean).join(' ').trim();
  return {
    idProperty: 'woo_order_id',
    id,
    properties: {
      woo_order_id: id,
      dealname: `Woo #${order.number ?? id}${name ? ` — ${name}` : ''}`,
      pipeline: pipelineId,
      dealstage: stageIds[stageKey],
      amount: order.status === 'refunded' ? money(0) : money(netTotal(order)),
      refund_amount: money(refundTotal(order)),
      closedate: isoUtc(order.date_created_gmt),
      woo_status: order.status,
      deal_currency_code: order.currency,
    },
  };
}

function buildLineItemInputs(order) {
  return (order.line_items ?? []).map((item) => {
    const id = String(item.id);
    return {
      idProperty: 'woo_line_item_id',
      id,
      wooProductId: String(item.product_id),
      properties: {
        woo_line_item_id: id,
        name: item.name,
        quantity: String(item.quantity),
        price: money(Number(item.price)),
        hs_sku: item.sku || undefined,
      },
    };
  });
}

function aggregateCustomer(orders) {
  const paid = orders.filter((o) => PAID_STATUSES.has(o.status));
  const dates = paid.map((o) => o.date_created_gmt.slice(0, 10)).sort();
  return {
    total_orders: paid.length,
    total_revenue: Math.round(paid.reduce((s, o) => s + netTotal(o), 0) * 100) / 100,
    first_order_date: dates[0] ?? null,
    last_order_date: dates.at(-1) ?? null,
  };
}

// ---- src/lib/sync-plan.js ----
// Turns a batch of Woo orders into the ordered list of HubSpot requests the sync-orders workflow makes.
// Every function returns plain request objects { method, path, body, label } — or { skip: true, label }
// when there is nothing to send — so the n8n flow stays linear and every step is unit-tested here.



const BATCH = 100;
const skip = (label) => ({ skip: true, label });
const post = (path, body, label) => ({ method: 'POST', path, body, label });
// Batch writes tolerate 4xx: HubSpot rejects a whole batch for one bad record, and that must become a
// ticket naming the records, not abort the other 99 orders. `ids` lets the ticket say which records.
const batches = (path, inputs, label, idOf = (i) => i.id) =>
  (inputs.length
    ? chunk(inputs, BATCH).map((part, i) => ({
      ...post(path, { inputs: part }, `${label} ${i + 1}`), tolerateClientError: true, ids: part.map(idOf).map(String),
    }))
    : [skip(label)]);
const lower = (s) => String(s ?? '').trim().toLowerCase();

/** Searches `objectType` for records whose `property` is any of `values` (≤100 values per search). */
function searchIn(objectType, property, values, label) {
  const unique = [...new Set(values.map(String))];
  if (!unique.length) return [skip(label)];
  return chunk(unique, BATCH).map((part, i) => post(`/crm/v3/objects/${objectType}/search`, {
    filterGroups: [{ filters: [{ propertyName: property, operator: 'IN', values: part }] }],
    properties: [property],
    limit: BATCH,
  }, `${label} ${i + 1}`));
}

/** For objects HubSpot cannot upsert by our key: update what the search found, create the rest. */
function updateOrCreate(objectType, key, items, found, label) {
  const updates = [];
  const creates = [];
  for (const properties of items) {
    const id = found.get(lower(properties[key]));
    if (id) updates.push({ id, properties });
    else creates.push({ properties });
  }
  const idOf = (i) => i.properties[key];
  const requests = [
    ...(updates.length ? batches(`/crm/v3/objects/${objectType}/batch/update`, updates, `${label} update`, idOf) : []),
    ...(creates.length ? batches(`/crm/v3/objects/${objectType}/batch/create`, creates, `${label} create`, idOf) : []),
  ];
  return requests.length ? requests : [skip(label)];
}

function pipelineContext(dealPipelines, ticketPipelines) {
  const find = (list, def) => {
    const p = (list?.results ?? []).find((x) => x.label === def.label);
    if (!p) throw new Error(`HubSpot pipeline "${def.label}" not found — run scripts/hubspot-setup.mjs first`);
    const ids = {};
    for (const s of def.stages) {
      const stage = p.stages.find((x) => x.label === s.label);
      if (!stage) throw new Error(`Stage "${s.label}" missing in pipeline "${def.label}" — run scripts/hubspot-setup.mjs`);
      ids[s.key] = stage.id;
    }
    return { id: p.id, ids };
  };
  const deals = find(dealPipelines, DEAL_PIPELINE);
  const tickets = find(ticketPipelines, TICKET_PIPELINE);
  return { pipelineId: deals.id, stageIds: deals.ids, ticketPipelineId: tickets.id, ticketStageNewId: tickets.ids.new };
}

function contactRequests(orders, history) {
  const byEmail = new Map();
  for (const order of orders) {
    const contact = buildContactInput(order);
    if (contact.email) byEmail.set(contact.email, contact);
  }
  const inputs = [...byEmail.values()].map(({ email, properties }) => {
    const agg = aggregateCustomer(history.filter((o) => lower(o.billing?.email) === email));
    const extra = Object.fromEntries(Object.entries(agg).filter(([, v]) => v !== null));
    return { idProperty: 'email', id: email, properties: { ...properties, ...extra } };
  });
  return batches('/crm/v3/objects/contacts/batch/upsert', inputs, 'contacts');
}

function companySearchRequest(orders) {
  const domains = planCompanies(orders).map((c) => c.domain);
  if (!domains.length) return skip('company search');
  return post('/crm/v3/objects/companies/search', {
    filterGroups: [{ filters: [{ propertyName: 'domain', operator: 'IN', values: domains }] }],
    properties: ['domain', 'name'],
    limit: BATCH,
  }, 'company search');
}

function companyCreateRequest(orders, searchResponse) {
  const found = idMap([searchResponse], 'domain');
  const inputs = planCompanies(orders)
    .filter((c) => !found.has(c.domain))
    .map((c) => ({ properties: { domain: c.domain, name: c.name } }));
  return inputs.length
    ? batches('/crm/v3/objects/companies/batch/create', inputs, 'company create', (i) => i.properties.domain)[0]
    : skip('company create');
}

const productSearchRequests = (orders) =>
  searchIn('products', 'woo_product_id', buildProductInputs(orders).map((p) => p.id), 'product search');

const productWriteRequests = (orders, searchResponses) => updateOrCreate(
  'products', 'woo_product_id', buildProductInputs(orders).map((p) => p.properties),
  idMap(searchResponses, 'woo_product_id'), 'products',
);

function dealRequests(orders, ctx) {
  const inputs = [];
  const problems = [];
  for (const order of orders) {
    try {
      inputs.push(buildDealInput(order, ctx));
    } catch (err) {
      problems.push({
        key: `unknown-status:${order.id}`,
        subject: `Woo order #${order.number ?? order.id} not synced: unknown status`,
        content: err.message,
        priority: 'HIGH',
      });
    }
  }
  return { requests: batches('/crm/v3/objects/deals/batch/upsert', inputs, 'deals'), problems };
}

const lineItemSearchRequests = (orders) =>
  searchIn('line_items', 'woo_line_item_id', orders.flatMap(buildLineItemInputs).map((li) => li.id), 'line item search');

function lineItemWriteRequests(orders, productIds, searchResponses) {
  const items = orders.flatMap(buildLineItemInputs).map(({ wooProductId, properties }) => {
    const hsProductId = productIds.get(wooProductId);
    return hsProductId ? { ...properties, hs_product_id: hsProductId } : properties;
  });
  return updateOrCreate('line_items', 'woo_line_item_id', items, idMap(searchResponses, 'woo_line_item_id'), 'line items');
}

/** value of `property` (lowercased) → HubSpot record id, from any number of batch/search responses. */
function idMap(responses, property) {
  const map = new Map();
  for (const r of responses) {
    for (const rec of r?.body?.results ?? []) {
      const value = rec.properties?.[property];
      if (value != null) map.set(lower(value), String(rec.id));
    }
  }
  return map;
}

function associationRequests({ orders, contactIds, companyIds, dealIds, lineItemIds }) {
  const pairs = { 'contacts/companies': new Map(), 'deals/contacts': new Map(), 'deals/companies': new Map(), 'line_items/deals': new Map() };
  const add = (kind, from, to) => { if (from && to) pairs[kind].set(`${from}>${to}`, { from: { id: from }, to: { id: to } }); };
  for (const order of orders) {
    const email = lower(order.billing?.email);
    const contactId = contactIds.get(email);
    const companyId = companyIds.get(companyDomain(email) ?? '');
    const dealId = dealIds.get(String(order.id));
    add('contacts/companies', contactId, companyId);
    add('deals/contacts', dealId, contactId);
    add('deals/companies', dealId, companyId);
    for (const item of order.line_items ?? []) add('line_items/deals', lineItemIds.get(String(item.id)), dealId);
  }
  return Object.entries(pairs).map(([kind, map]) => (map.size
    ? { ...post(`/crm/v4/associations/${kind}/batch/associate/default`, { inputs: [...map.values()] }, `associate ${kind}`),
      tolerateClientError: true, ids: [...map.keys()] }
    : skip(`associate ${kind}`)));
}

function syncProblems(orders, responses, extra = []) {
  const problems = [];
  for (const order of orders) {
    const contact = buildContactInput(order);
    if (!contact.email) {
      problems.push({
        key: `no-contact:${order.id}`,
        subject: `Woo order #${order.number ?? order.id} synced without a contact`,
        content: `Billing email "${order.billing?.email ?? ''}" was rejected (${contact.issues.join('; ')}). `
          + 'The deal was synced; fix the email in WooCommerce and save the order to link a contact.',
        priority: 'MEDIUM',
      });
    }
  }
  for (const r of responses) {
    if (r && r.ok === false) {
      const ids = r.ids ?? [];
      problems.push({
        key: `batch-failed:${String(r.label).replace(/ \d+$/, '')}:${ids[0] ?? 'none'}..${ids.at(-1) ?? 'none'}`,
        subject: `HubSpot rejected a whole ${r.label} batch (${ids.length} records)`,
        content: `HTTP ${r.status} ${r.body?.category ?? ''}: ${r.body?.message ?? JSON.stringify(r.body ?? '')}
`
          + `Records: ${ids.join(', ')}`.slice(0, 1800),
        priority: 'HIGH',
      });
      continue;
    }
    for (const e of r?.body?.errors ?? []) {
      for (const id of e.context?.ids ?? ['unknown']) {
        problems.push({
          key: `batch:${String(r.label).replace(/ \d+$/, '')}:${id}`,
          subject: `HubSpot rejected ${r.label} record ${id}`,
          content: `${e.category ?? 'ERROR'}: ${e.message ?? ''}`.slice(0, 2000),
          priority: 'HIGH',
        });
      }
    }
  }
  return [...problems, ...extra];
}

function ticketReadRequest(problems) {
  if (!problems.length) return skip('ticket lookup');
  return searchIn('tickets', 'sync_error_key', problems.slice(0, BATCH).map((p) => p.key), 'ticket lookup')[0];
}

function ticketCreateRequest(problems, readResponse, ctx) {
  const existing = idMap([readResponse], 'sync_error_key');
  const inputs = problems.slice(0, BATCH)
    .filter((p) => !existing.has(lower(p.key)))
    .map((p) => ({
      properties: {
        sync_error_key: p.key,
        subject: p.subject,
        content: p.content,
        hs_pipeline: ctx.ticketPipelineId,
        hs_pipeline_stage: ctx.ticketStageNewId,
        hs_ticket_priority: p.priority,
      },
    }));
  return inputs.length
    ? batches('/crm/v3/objects/tickets/batch/create', inputs, 'tickets', (i) => i.properties.sync_error_key)[0]
    : skip('tickets');
}

// ---- step ----
const input = $('Sync in').first().json;
const orders = input.orders;
const history = input.history ?? orders;
const responses = (node) => $(node).all().map((item) => item.json);
const ctx = () => { const [deals, tickets] = responses('Get pipelines'); return pipelineContext(deals.body, tickets.body); };
const out = (requests) => [].concat(requests).map((json) => ({ json }));
return out(productSearchRequests(orders));

// ---- src/lib/validate.js ----
// Data-quality checks (flow F3). Pure functions: inlined into n8n Code nodes by build-workflows.
// Rule: never block the sync. Invalid values become null and are reported as issues.

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[a-z]{2,}$/;

const DISPOSABLE_DOMAINS = new Set([
  'mailinator.com', '10minutemail.com', 'guerrillamail.com', 'yopmail.com', 'tempmail.com',
]);

// Common typos of webmail domains → correct domain.
const DOMAIN_TYPOS = {
  'gmial.com': 'gmail.com', 'gmal.com': 'gmail.com', 'gnail.com': 'gmail.com', 'gmail.con': 'gmail.com',
  'gmial.con': 'gmail.com', 'gmail.cmo': 'gmail.com',
  'hotmial.com': 'hotmail.com', 'hotmal.com': 'hotmail.com', 'hotmail.con': 'hotmail.com',
  'yaho.com': 'yahoo.com', 'yahoo.con': 'yahoo.com', 'outlok.com': 'outlook.com',
};

const DIAL_CODES = {
  AR: '54', US: '1', MX: '52', ES: '34', CL: '56', UY: '598', BR: '55', CO: '57', PE: '51', GB: '44', DE: '49',
};

const COUNTRY_NAMES = {
  argentina: 'AR',
  'united states': 'US', usa: 'US', 'estados unidos': 'US', eeuu: 'US',
  mexico: 'MX', 'méxico': 'MX',
  spain: 'ES', 'españa': 'ES', espana: 'ES',
  chile: 'CL', uruguay: 'UY',
  brazil: 'BR', brasil: 'BR',
  colombia: 'CO', peru: 'PE', 'perú': 'PE',
  'united kingdom': 'GB', uk: 'GB', 'reino unido': 'GB',
  germany: 'DE', alemania: 'DE',
};

function validateEmail(raw) {
  const email = String(raw ?? '').trim().toLowerCase();
  if (!EMAIL_RE.test(email)) return { value: null, issue: 'email_invalid_format' };
  const [local, domain] = email.split('@');
  // Dot errors pass the simple pattern but HubSpot rejects them (and one bad email would fail a whole batch).
  if (/^\.|\.$|\.\./.test(local) || domain.split('.').some((label) => !label)) {
    return { value: null, issue: 'email_invalid_format' };
  }
  if (DOMAIN_TYPOS[domain]) return { value: null, issue: `email_typo_domain:${domain}→${DOMAIN_TYPOS[domain]}` };
  if (DISPOSABLE_DOMAINS.has(domain)) return { value: null, issue: 'email_disposable' };
  return { value: email, issue: null };
}

function normalizePhone(raw, countryIso2) {
  const text = String(raw ?? '').trim();
  if (!text) return { value: null, issue: null };
  const invalid = { value: null, issue: 'phone_invalid' };
  const digits = text.replace(/\D/g, '');
  if (/[a-z]/i.test(text) || !digits) return invalid;

  let e164;
  if (text.startsWith('+')) {
    e164 = digits;
  } else {
    const dial = DIAL_CODES[countryIso2] ?? DIAL_CODES.AR;
    let national = digits;
    if (national.startsWith(dial) && national.length > 10) national = national.slice(dial.length);
    national = national.replace(/^0/, ''); // trunk prefix (AR, ES, GB, DE…)
    if (national.length < 6) return invalid;
    e164 = dial + national;
  }
  if (e164.length < 8 || e164.length > 15) return invalid;
  return { value: `+${e164}`, issue: null };
}

function normalizeCountry(raw) {
  const text = String(raw ?? '').trim();
  if (!text) return { value: null, issue: null };
  const upper = text.toUpperCase();
  if (DIAL_CODES[upper]) return { value: upper, issue: null };
  const byName = COUNTRY_NAMES[text.toLowerCase()];
  return byName ? { value: byName, issue: null } : { value: null, issue: 'country_unknown' };
}

function validateCustomer(billing = {}) {
  const issues = [];
  const take = (result) => {
    if (result.issue) issues.push(result.issue);
    return result.value;
  };
  const email = take(validateEmail(billing.email));
  const country = take(normalizeCountry(billing.country));
  const phone = take(normalizePhone(billing.phone, country));
  const clean = {
    email,
    phone,
    country,
    firstname: String(billing.first_name ?? '').trim() || null,
    lastname: String(billing.last_name ?? '').trim() || null,
    company: String(billing.company ?? '').trim() || null,
  };
  return { clean, issues };
}

// ---- src/lib/hubspot-schema.js ----
// HubSpot schema the sync needs. Created idempotently by scripts/hubspot-setup.mjs.

const PROPERTY_GROUP = { name: 'woocommerce', label: 'WooCommerce', displayOrder: -1 };

const base = { groupName: PROPERTY_GROUP.name };
const text = (name, label, extra = {}) => ({ ...base, name, label, type: 'string', fieldType: 'text', ...extra });
const number = (name, label) => ({ ...base, name, label, type: 'number', fieldType: 'number' });
const date = (name, label) => ({ ...base, name, label, type: 'date', fieldType: 'date' });
const select = (name, label, values) => ({
  ...base, name, label, type: 'enumeration', fieldType: 'select',
  options: values.map(([value, optionLabel], displayOrder) => ({ value, label: optionLabel, displayOrder })),
});
const uniqueId = (name, label) => text(name, label, { hasUniqueValue: true });

const PROPERTIES = {
  contacts: [
    text('woo_customer_id', 'Woo customer ID'),
    number('total_orders', 'Total orders (paid)'),
    number('total_revenue', 'Total revenue (net of refunds)'),
    date('first_order_date', 'First order date'),
    date('last_order_date', 'Last order date'),
    select('customer_segment', 'Customer segment', [['new', 'New'], ['repeat', 'Repeat'], ['vip', 'VIP']]),
    select('data_quality_status', 'Data quality status', [['ok', 'OK'], ['needs_review', 'Needs review']]),
    text('data_quality_issues', 'Data quality issues', { type: 'string', fieldType: 'textarea' }),
  ],
  deals: [
    uniqueId('woo_order_id', 'Woo order ID'),
    number('refund_amount', 'Refund amount'),
    text('woo_status', 'Woo order status'),
  ],
  // HubSpot does not support unique-value properties on products (and does not document them for line
  // items), so these two are looked up by search and then updated or created — see sync-plan.js.
  products: [text('woo_product_id', 'Woo product ID')],
  line_items: [text('woo_line_item_id', 'Woo line item ID')],
  // One ticket per distinct sync problem, so re-running the backfill never duplicates tickets.
  tickets: [uniqueId('sync_error_key', 'Sync error key')],
};

const stage = (key, label, displayOrder, metadata) => ({ key, label, displayOrder, metadata });

const DEAL_PIPELINE = {
  label: 'WooCommerce',
  displayOrder: 1,
  stages: [
    stage('pending_payment', 'Pending payment', 0, { probability: '0.2' }),
    stage('paid', 'Paid', 1, { probability: '0.9' }),
    stage('closedwon', 'Closed won', 2, { probability: '1.0' }),
    stage('closedlost', 'Closed lost', 3, { probability: '0.0' }),
    stage('refunded', 'Refunded', 4, { probability: '0.0' }),
  ],
};

const TICKET_PIPELINE = {
  label: 'Integration errors',
  displayOrder: 1,
  stages: [
    stage('new', 'New', 0, { ticketState: 'OPEN' }),
    stage('resolved', 'Resolved', 1, { ticketState: 'CLOSED' }),
  ],
};

// ---- src/lib/retry.js ----
// Retry policy for HubSpot calls (flow F4). Ceiling: 100 requests / 10 s, batches of ≤100.

const MAX_ATTEMPTS = 3;

// 429 = rate limit, 423 = HubSpot's "Locked" during high sync volume, 5xx = transient server errors.
function shouldRetry(status) {
  return status === 429 || status === 423 || (status >= 500 && status <= 599);
}

// Exponential (1 s, 2 s, 4 s…), but never shorter than what the error needs: a 429 without Retry-After
// waits out the whole 10 s rate window; a 423 waits at least 2 s (HubSpot's guidance).
function backoffDelayMs(attempt, retryAfterHeader, status) {
  const retryAfter = Number(retryAfterHeader);
  if (retryAfterHeader != null && Number.isFinite(retryAfter) && retryAfter > 0) return retryAfter * 1000;
  const exponential = 1000 * 2 ** (attempt - 1);
  if (status === 429) return Math.max(exponential, 10000);
  if (status === 423) return Math.max(exponential, 2000);
  return exponential;
}

function chunk(items, size) {
  const out = [];
  for (let i = 0; i < items.length; i += size) out.push(items.slice(i, i + size));
  return out;
}

// ---- src/lib/mapping.js ----
// WooCommerce order → HubSpot CRM inputs. Pure functions, inlined into n8n Code nodes.

// Woo status → internal stage key. Real HubSpot stage ids come from hubspot-setup (.hubspot-ids.json).
const STAGE_BY_STATUS = {
  pending: 'pending_payment',
  'on-hold': 'pending_payment',
  processing: 'paid',
  completed: 'closedwon',
  cancelled: 'closedlost',
  failed: 'closedlost',
  refunded: 'refunded',
};

const PAID_STATUSES = new Set(['processing', 'completed']);

const FREE_EMAIL_DOMAINS = new Set([
  'gmail.com', 'googlemail.com', 'hotmail.com', 'outlook.com', 'live.com', 'yahoo.com', 'yahoo.com.ar',
  'icloud.com', 'aol.com', 'proton.me', 'protonmail.com',
]);

const money = (n) => (Math.round(n * 100) / 100).toFixed(2);

function refundTotal(order) {
  return (order.refunds ?? []).reduce((sum, r) => sum + Math.abs(Number(r.total) || 0), 0);
}

function netTotal(order) {
  return Math.max(0, Number(order.total) - refundTotal(order));
}

const isoUtc = (wooGmtDate) => new Date(`${wooGmtDate}Z`).toISOString();

function companyDomain(email) {
  const { value } = validateEmail(email);
  if (!value) return null;
  const domain = value.split('@')[1];
  return FREE_EMAIL_DOMAINS.has(domain) ? null : domain;
}

function planCompanies(orders) {
  const byDomain = new Map();
  for (const order of orders) {
    const domain = companyDomain(order.billing?.email);
    if (!domain) continue;
    const name = String(order.billing?.company ?? '').trim();
    const existing = byDomain.get(domain);
    if (!existing || (existing.name === domain && name)) byDomain.set(domain, { domain, name: name || domain });
  }
  return [...byDomain.values()];
}

function buildContactInput(order) {
  const { clean, issues } = validateCustomer(order.billing);
  const properties = {};
  for (const [key, value] of Object.entries(clean)) if (value) properties[key] = value;
  if (Number(order.customer_id) > 0) properties.woo_customer_id = String(order.customer_id);
  properties.data_quality_status = issues.length ? 'needs_review' : 'ok';
  properties.data_quality_issues = issues.join('; ');
  return { email: clean.email, properties, issues };
}

function buildProductInputs(orders) {
  const byId = new Map();
  for (const order of orders) {
    for (const item of order.line_items ?? []) {
      const id = String(item.product_id);
      if (byId.has(id)) continue;
      byId.set(id, {
        idProperty: 'woo_product_id',
        id,
        properties: { woo_product_id: id, name: item.name, price: money(Number(item.price)), hs_sku: item.sku || undefined },
      });
    }
  }
  return [...byId.values()];
}

function buildDealInput(order, { pipelineId, stageIds }) {
  const stageKey = STAGE_BY_STATUS[order.status];
  if (!stageKey) throw new Error(`Unknown Woo status "${order.status}" on order ${order.id}`);
  const id = String(order.id);
  const name = [order.billing?.first_name, order.billing?.last_name].filter(Boolean).join(' ').trim();
  return {
    idProperty: 'woo_order_id',
    id,
    properties: {
      woo_order_id: id,
      dealname: `Woo #${order.number ?? id}${name ? ` — ${name}` : ''}`,
      pipeline: pipelineId,
      dealstage: stageIds[stageKey],
      amount: order.status === 'refunded' ? money(0) : money(netTotal(order)),
      refund_amount: money(refundTotal(order)),
      closedate: isoUtc(order.date_created_gmt),
      woo_status: order.status,
      deal_currency_code: order.currency,
    },
  };
}

function buildLineItemInputs(order) {
  return (order.line_items ?? []).map((item) => {
    const id = String(item.id);
    return {
      idProperty: 'woo_line_item_id',
      id,
      wooProductId: String(item.product_id),
      properties: {
        woo_line_item_id: id,
        name: item.name,
        quantity: String(item.quantity),
        price: money(Number(item.price)),
        hs_sku: item.sku || undefined,
      },
    };
  });
}

function aggregateCustomer(orders) {
  const paid = orders.filter((o) => PAID_STATUSES.has(o.status));
  const dates = paid.map((o) => o.date_created_gmt.slice(0, 10)).sort();
  return {
    total_orders: paid.length,
    total_revenue: Math.round(paid.reduce((s, o) => s + netTotal(o), 0) * 100) / 100,
    first_order_date: dates[0] ?? null,
    last_order_date: dates.at(-1) ?? null,
  };
}

// ---- src/lib/sync-plan.js ----
// Turns a batch of Woo orders into the ordered list of HubSpot requests the sync-orders workflow makes.
// Every function returns plain request objects { method, path, body, label } — or { skip: true, label }
// when there is nothing to send — so the n8n flow stays linear and every step is unit-tested here.



const BATCH = 100;
const skip = (label) => ({ skip: true, label });
const post = (path, body, label) => ({ method: 'POST', path, body, label });
// Batch writes tolerate 4xx: HubSpot rejects a whole batch for one bad record, and that must become a
// ticket naming the records, not abort the other 99 orders. `ids` lets the ticket say which records.
const batches = (path, inputs, label, idOf = (i) => i.id) =>
  (inputs.length
    ? chunk(inputs, BATCH).map((part, i) => ({
      ...post(path, { inputs: part }, `${label} ${i + 1}`), tolerateClientError: true, ids: part.map(idOf).map(String),
    }))
    : [skip(label)]);
const lower = (s) => String(s ?? '').trim().toLowerCase();

/** Searches `objectType` for records whose `property` is any of `values` (≤100 values per search). */
function searchIn(objectType, property, values, label) {
  const unique = [...new Set(values.map(String))];
  if (!unique.length) return [skip(label)];
  return chunk(unique, BATCH).map((part, i) => post(`/crm/v3/objects/${objectType}/search`, {
    filterGroups: [{ filters: [{ propertyName: property, operator: 'IN', values: part }] }],
    properties: [property],
    limit: BATCH,
  }, `${label} ${i + 1}`));
}

/** For objects HubSpot cannot upsert by our key: update what the search found, create the rest. */
function updateOrCreate(objectType, key, items, found, label) {
  const updates = [];
  const creates = [];
  for (const properties of items) {
    const id = found.get(lower(properties[key]));
    if (id) updates.push({ id, properties });
    else creates.push({ properties });
  }
  const idOf = (i) => i.properties[key];
  const requests = [
    ...(updates.length ? batches(`/crm/v3/objects/${objectType}/batch/update`, updates, `${label} update`, idOf) : []),
    ...(creates.length ? batches(`/crm/v3/objects/${objectType}/batch/create`, creates, `${label} create`, idOf) : []),
  ];
  return requests.length ? requests : [skip(label)];
}

function pipelineContext(dealPipelines, ticketPipelines) {
  const find = (list, def) => {
    const p = (list?.results ?? []).find((x) => x.label === def.label);
    if (!p) throw new Error(`HubSpot pipeline "${def.label}" not found — run scripts/hubspot-setup.mjs first`);
    const ids = {};
    for (const s of def.stages) {
      const stage = p.stages.find((x) => x.label === s.label);
      if (!stage) throw new Error(`Stage "${s.label}" missing in pipeline "${def.label}" — run scripts/hubspot-setup.mjs`);
      ids[s.key] = stage.id;
    }
    return { id: p.id, ids };
  };
  const deals = find(dealPipelines, DEAL_PIPELINE);
  const tickets = find(ticketPipelines, TICKET_PIPELINE);
  return { pipelineId: deals.id, stageIds: deals.ids, ticketPipelineId: tickets.id, ticketStageNewId: tickets.ids.new };
}

function contactRequests(orders, history) {
  const byEmail = new Map();
  for (const order of orders) {
    const contact = buildContactInput(order);
    if (contact.email) byEmail.set(contact.email, contact);
  }
  const inputs = [...byEmail.values()].map(({ email, properties }) => {
    const agg = aggregateCustomer(history.filter((o) => lower(o.billing?.email) === email));
    const extra = Object.fromEntries(Object.entries(agg).filter(([, v]) => v !== null));
    return { idProperty: 'email', id: email, properties: { ...properties, ...extra } };
  });
  return batches('/crm/v3/objects/contacts/batch/upsert', inputs, 'contacts');
}

function companySearchRequest(orders) {
  const domains = planCompanies(orders).map((c) => c.domain);
  if (!domains.length) return skip('company search');
  return post('/crm/v3/objects/companies/search', {
    filterGroups: [{ filters: [{ propertyName: 'domain', operator: 'IN', values: domains }] }],
    properties: ['domain', 'name'],
    limit: BATCH,
  }, 'company search');
}

function companyCreateRequest(orders, searchResponse) {
  const found = idMap([searchResponse], 'domain');
  const inputs = planCompanies(orders)
    .filter((c) => !found.has(c.domain))
    .map((c) => ({ properties: { domain: c.domain, name: c.name } }));
  return inputs.length
    ? batches('/crm/v3/objects/companies/batch/create', inputs, 'company create', (i) => i.properties.domain)[0]
    : skip('company create');
}

const productSearchRequests = (orders) =>
  searchIn('products', 'woo_product_id', buildProductInputs(orders).map((p) => p.id), 'product search');

const productWriteRequests = (orders, searchResponses) => updateOrCreate(
  'products', 'woo_product_id', buildProductInputs(orders).map((p) => p.properties),
  idMap(searchResponses, 'woo_product_id'), 'products',
);

function dealRequests(orders, ctx) {
  const inputs = [];
  const problems = [];
  for (const order of orders) {
    try {
      inputs.push(buildDealInput(order, ctx));
    } catch (err) {
      problems.push({
        key: `unknown-status:${order.id}`,
        subject: `Woo order #${order.number ?? order.id} not synced: unknown status`,
        content: err.message,
        priority: 'HIGH',
      });
    }
  }
  return { requests: batches('/crm/v3/objects/deals/batch/upsert', inputs, 'deals'), problems };
}

const lineItemSearchRequests = (orders) =>
  searchIn('line_items', 'woo_line_item_id', orders.flatMap(buildLineItemInputs).map((li) => li.id), 'line item search');

function lineItemWriteRequests(orders, productIds, searchResponses) {
  const items = orders.flatMap(buildLineItemInputs).map(({ wooProductId, properties }) => {
    const hsProductId = productIds.get(wooProductId);
    return hsProductId ? { ...properties, hs_product_id: hsProductId } : properties;
  });
  return updateOrCreate('line_items', 'woo_line_item_id', items, idMap(searchResponses, 'woo_line_item_id'), 'line items');
}

/** value of `property` (lowercased) → HubSpot record id, from any number of batch/search responses. */
function idMap(responses, property) {
  const map = new Map();
  for (const r of responses) {
    for (const rec of r?.body?.results ?? []) {
      const value = rec.properties?.[property];
      if (value != null) map.set(lower(value), String(rec.id));
    }
  }
  return map;
}

function associationRequests({ orders, contactIds, companyIds, dealIds, lineItemIds }) {
  const pairs = { 'contacts/companies': new Map(), 'deals/contacts': new Map(), 'deals/companies': new Map(), 'line_items/deals': new Map() };
  const add = (kind, from, to) => { if (from && to) pairs[kind].set(`${from}>${to}`, { from: { id: from }, to: { id: to } }); };
  for (const order of orders) {
    const email = lower(order.billing?.email);
    const contactId = contactIds.get(email);
    const companyId = companyIds.get(companyDomain(email) ?? '');
    const dealId = dealIds.get(String(order.id));
    add('contacts/companies', contactId, companyId);
    add('deals/contacts', dealId, contactId);
    add('deals/companies', dealId, companyId);
    for (const item of order.line_items ?? []) add('line_items/deals', lineItemIds.get(String(item.id)), dealId);
  }
  return Object.entries(pairs).map(([kind, map]) => (map.size
    ? { ...post(`/crm/v4/associations/${kind}/batch/associate/default`, { inputs: [...map.values()] }, `associate ${kind}`),
      tolerateClientError: true, ids: [...map.keys()] }
    : skip(`associate ${kind}`)));
}

function syncProblems(orders, responses, extra = []) {
  const problems = [];
  for (const order of orders) {
    const contact = buildContactInput(order);
    if (!contact.email) {
      problems.push({
        key: `no-contact:${order.id}`,
        subject: `Woo order #${order.number ?? order.id} synced without a contact`,
        content: `Billing email "${order.billing?.email ?? ''}" was rejected (${contact.issues.join('; ')}). `
          + 'The deal was synced; fix the email in WooCommerce and save the order to link a contact.',
        priority: 'MEDIUM',
      });
    }
  }
  for (const r of responses) {
    if (r && r.ok === false) {
      const ids = r.ids ?? [];
      problems.push({
        key: `batch-failed:${String(r.label).replace(/ \d+$/, '')}:${ids[0] ?? 'none'}..${ids.at(-1) ?? 'none'}`,
        subject: `HubSpot rejected a whole ${r.label} batch (${ids.length} records)`,
        content: `HTTP ${r.status} ${r.body?.category ?? ''}: ${r.body?.message ?? JSON.stringify(r.body ?? '')}
`
          + `Records: ${ids.join(', ')}`.slice(0, 1800),
        priority: 'HIGH',
      });
      continue;
    }
    for (const e of r?.body?.errors ?? []) {
      for (const id of e.context?.ids ?? ['unknown']) {
        problems.push({
          key: `batch:${String(r.label).replace(/ \d+$/, '')}:${id}`,
          subject: `HubSpot rejected ${r.label} record ${id}`,
          content: `${e.category ?? 'ERROR'}: ${e.message ?? ''}`.slice(0, 2000),
          priority: 'HIGH',
        });
      }
    }
  }
  return [...problems, ...extra];
}

function ticketReadRequest(problems) {
  if (!problems.length) return skip('ticket lookup');
  return searchIn('tickets', 'sync_error_key', problems.slice(0, BATCH).map((p) => p.key), 'ticket lookup')[0];
}

function ticketCreateRequest(problems, readResponse, ctx) {
  const existing = idMap([readResponse], 'sync_error_key');
  const inputs = problems.slice(0, BATCH)
    .filter((p) => !existing.has(lower(p.key)))
    .map((p) => ({
      properties: {
        sync_error_key: p.key,
        subject: p.subject,
        content: p.content,
        hs_pipeline: ctx.ticketPipelineId,
        hs_pipeline_stage: ctx.ticketStageNewId,
        hs_ticket_priority: p.priority,
      },
    }));
  return inputs.length
    ? batches('/crm/v3/objects/tickets/batch/create', inputs, 'tickets', (i) => i.properties.sync_error_key)[0]
    : skip('tickets');
}

// ---- step ----
const input = $('Sync in').first().json;
const orders = input.orders;
const history = input.history ?? orders;
const responses = (node) => $(node).all().map((item) => item.json);
const ctx = () => { const [deals, tickets] = responses('Get pipelines'); return pipelineContext(deals.body, tickets.body); };
const out = (requests) => [].concat(requests).map((json) => ({ json }));
return out(productWriteRequests(orders, responses('Search products')));

// ---- src/lib/validate.js ----
// Data-quality checks (flow F3). Pure functions: inlined into n8n Code nodes by build-workflows.
// Rule: never block the sync. Invalid values become null and are reported as issues.

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[a-z]{2,}$/;

const DISPOSABLE_DOMAINS = new Set([
  'mailinator.com', '10minutemail.com', 'guerrillamail.com', 'yopmail.com', 'tempmail.com',
]);

// Common typos of webmail domains → correct domain.
const DOMAIN_TYPOS = {
  'gmial.com': 'gmail.com', 'gmal.com': 'gmail.com', 'gnail.com': 'gmail.com', 'gmail.con': 'gmail.com',
  'gmial.con': 'gmail.com', 'gmail.cmo': 'gmail.com',
  'hotmial.com': 'hotmail.com', 'hotmal.com': 'hotmail.com', 'hotmail.con': 'hotmail.com',
  'yaho.com': 'yahoo.com', 'yahoo.con': 'yahoo.com', 'outlok.com': 'outlook.com',
};

const DIAL_CODES = {
  AR: '54', US: '1', MX: '52', ES: '34', CL: '56', UY: '598', BR: '55', CO: '57', PE: '51', GB: '44', DE: '49',
};

const COUNTRY_NAMES = {
  argentina: 'AR',
  'united states': 'US', usa: 'US', 'estados unidos': 'US', eeuu: 'US',
  mexico: 'MX', 'méxico': 'MX',
  spain: 'ES', 'españa': 'ES', espana: 'ES',
  chile: 'CL', uruguay: 'UY',
  brazil: 'BR', brasil: 'BR',
  colombia: 'CO', peru: 'PE', 'perú': 'PE',
  'united kingdom': 'GB', uk: 'GB', 'reino unido': 'GB',
  germany: 'DE', alemania: 'DE',
};

function validateEmail(raw) {
  const email = String(raw ?? '').trim().toLowerCase();
  if (!EMAIL_RE.test(email)) return { value: null, issue: 'email_invalid_format' };
  const [local, domain] = email.split('@');
  // Dot errors pass the simple pattern but HubSpot rejects them (and one bad email would fail a whole batch).
  if (/^\.|\.$|\.\./.test(local) || domain.split('.').some((label) => !label)) {
    return { value: null, issue: 'email_invalid_format' };
  }
  if (DOMAIN_TYPOS[domain]) return { value: null, issue: `email_typo_domain:${domain}→${DOMAIN_TYPOS[domain]}` };
  if (DISPOSABLE_DOMAINS.has(domain)) return { value: null, issue: 'email_disposable' };
  return { value: email, issue: null };
}

function normalizePhone(raw, countryIso2) {
  const text = String(raw ?? '').trim();
  if (!text) return { value: null, issue: null };
  const invalid = { value: null, issue: 'phone_invalid' };
  const digits = text.replace(/\D/g, '');
  if (/[a-z]/i.test(text) || !digits) return invalid;

  let e164;
  if (text.startsWith('+')) {
    e164 = digits;
  } else {
    const dial = DIAL_CODES[countryIso2] ?? DIAL_CODES.AR;
    let national = digits;
    if (national.startsWith(dial) && national.length > 10) national = national.slice(dial.length);
    national = national.replace(/^0/, ''); // trunk prefix (AR, ES, GB, DE…)
    if (national.length < 6) return invalid;
    e164 = dial + national;
  }
  if (e164.length < 8 || e164.length > 15) return invalid;
  return { value: `+${e164}`, issue: null };
}

function normalizeCountry(raw) {
  const text = String(raw ?? '').trim();
  if (!text) return { value: null, issue: null };
  const upper = text.toUpperCase();
  if (DIAL_CODES[upper]) return { value: upper, issue: null };
  const byName = COUNTRY_NAMES[text.toLowerCase()];
  return byName ? { value: byName, issue: null } : { value: null, issue: 'country_unknown' };
}

function validateCustomer(billing = {}) {
  const issues = [];
  const take = (result) => {
    if (result.issue) issues.push(result.issue);
    return result.value;
  };
  const email = take(validateEmail(billing.email));
  const country = take(normalizeCountry(billing.country));
  const phone = take(normalizePhone(billing.phone, country));
  const clean = {
    email,
    phone,
    country,
    firstname: String(billing.first_name ?? '').trim() || null,
    lastname: String(billing.last_name ?? '').trim() || null,
    company: String(billing.company ?? '').trim() || null,
  };
  return { clean, issues };
}

// ---- src/lib/hubspot-schema.js ----
// HubSpot schema the sync needs. Created idempotently by scripts/hubspot-setup.mjs.

const PROPERTY_GROUP = { name: 'woocommerce', label: 'WooCommerce', displayOrder: -1 };

const base = { groupName: PROPERTY_GROUP.name };
const text = (name, label, extra = {}) => ({ ...base, name, label, type: 'string', fieldType: 'text', ...extra });
const number = (name, label) => ({ ...base, name, label, type: 'number', fieldType: 'number' });
const date = (name, label) => ({ ...base, name, label, type: 'date', fieldType: 'date' });
const select = (name, label, values) => ({
  ...base, name, label, type: 'enumeration', fieldType: 'select',
  options: values.map(([value, optionLabel], displayOrder) => ({ value, label: optionLabel, displayOrder })),
});
const uniqueId = (name, label) => text(name, label, { hasUniqueValue: true });

const PROPERTIES = {
  contacts: [
    text('woo_customer_id', 'Woo customer ID'),
    number('total_orders', 'Total orders (paid)'),
    number('total_revenue', 'Total revenue (net of refunds)'),
    date('first_order_date', 'First order date'),
    date('last_order_date', 'Last order date'),
    select('customer_segment', 'Customer segment', [['new', 'New'], ['repeat', 'Repeat'], ['vip', 'VIP']]),
    select('data_quality_status', 'Data quality status', [['ok', 'OK'], ['needs_review', 'Needs review']]),
    text('data_quality_issues', 'Data quality issues', { type: 'string', fieldType: 'textarea' }),
  ],
  deals: [
    uniqueId('woo_order_id', 'Woo order ID'),
    number('refund_amount', 'Refund amount'),
    text('woo_status', 'Woo order status'),
  ],
  // HubSpot does not support unique-value properties on products (and does not document them for line
  // items), so these two are looked up by search and then updated or created — see sync-plan.js.
  products: [text('woo_product_id', 'Woo product ID')],
  line_items: [text('woo_line_item_id', 'Woo line item ID')],
  // One ticket per distinct sync problem, so re-running the backfill never duplicates tickets.
  tickets: [uniqueId('sync_error_key', 'Sync error key')],
};

const stage = (key, label, displayOrder, metadata) => ({ key, label, displayOrder, metadata });

const DEAL_PIPELINE = {
  label: 'WooCommerce',
  displayOrder: 1,
  stages: [
    stage('pending_payment', 'Pending payment', 0, { probability: '0.2' }),
    stage('paid', 'Paid', 1, { probability: '0.9' }),
    stage('closedwon', 'Closed won', 2, { probability: '1.0' }),
    stage('closedlost', 'Closed lost', 3, { probability: '0.0' }),
    stage('refunded', 'Refunded', 4, { probability: '0.0' }),
  ],
};

const TICKET_PIPELINE = {
  label: 'Integration errors',
  displayOrder: 1,
  stages: [
    stage('new', 'New', 0, { ticketState: 'OPEN' }),
    stage('resolved', 'Resolved', 1, { ticketState: 'CLOSED' }),
  ],
};

// ---- src/lib/retry.js ----
// Retry policy for HubSpot calls (flow F4). Ceiling: 100 requests / 10 s, batches of ≤100.

const MAX_ATTEMPTS = 3;

// 429 = rate limit, 423 = HubSpot's "Locked" during high sync volume, 5xx = transient server errors.
function shouldRetry(status) {
  return status === 429 || status === 423 || (status >= 500 && status <= 599);
}

// Exponential (1 s, 2 s, 4 s…), but never shorter than what the error needs: a 429 without Retry-After
// waits out the whole 10 s rate window; a 423 waits at least 2 s (HubSpot's guidance).
function backoffDelayMs(attempt, retryAfterHeader, status) {
  const retryAfter = Number(retryAfterHeader);
  if (retryAfterHeader != null && Number.isFinite(retryAfter) && retryAfter > 0) return retryAfter * 1000;
  const exponential = 1000 * 2 ** (attempt - 1);
  if (status === 429) return Math.max(exponential, 10000);
  if (status === 423) return Math.max(exponential, 2000);
  return exponential;
}

function chunk(items, size) {
  const out = [];
  for (let i = 0; i < items.length; i += size) out.push(items.slice(i, i + size));
  return out;
}

// ---- src/lib/mapping.js ----
// WooCommerce order → HubSpot CRM inputs. Pure functions, inlined into n8n Code nodes.

// Woo status → internal stage key. Real HubSpot stage ids come from hubspot-setup (.hubspot-ids.json).
const STAGE_BY_STATUS = {
  pending: 'pending_payment',
  'on-hold': 'pending_payment',
  processing: 'paid',
  completed: 'closedwon',
  cancelled: 'closedlost',
  failed: 'closedlost',
  refunded: 'refunded',
};

const PAID_STATUSES = new Set(['processing', 'completed']);

const FREE_EMAIL_DOMAINS = new Set([
  'gmail.com', 'googlemail.com', 'hotmail.com', 'outlook.com', 'live.com', 'yahoo.com', 'yahoo.com.ar',
  'icloud.com', 'aol.com', 'proton.me', 'protonmail.com',
]);

const money = (n) => (Math.round(n * 100) / 100).toFixed(2);

function refundTotal(order) {
  return (order.refunds ?? []).reduce((sum, r) => sum + Math.abs(Number(r.total) || 0), 0);
}

function netTotal(order) {
  return Math.max(0, Number(order.total) - refundTotal(order));
}

const isoUtc = (wooGmtDate) => new Date(`${wooGmtDate}Z`).toISOString();

function companyDomain(email) {
  const { value } = validateEmail(email);
  if (!value) return null;
  const domain = value.split('@')[1];
  return FREE_EMAIL_DOMAINS.has(domain) ? null : domain;
}

function planCompanies(orders) {
  const byDomain = new Map();
  for (const order of orders) {
    const domain = companyDomain(order.billing?.email);
    if (!domain) continue;
    const name = String(order.billing?.company ?? '').trim();
    const existing = byDomain.get(domain);
    if (!existing || (existing.name === domain && name)) byDomain.set(domain, { domain, name: name || domain });
  }
  return [...byDomain.values()];
}

function buildContactInput(order) {
  const { clean, issues } = validateCustomer(order.billing);
  const properties = {};
  for (const [key, value] of Object.entries(clean)) if (value) properties[key] = value;
  if (Number(order.customer_id) > 0) properties.woo_customer_id = String(order.customer_id);
  properties.data_quality_status = issues.length ? 'needs_review' : 'ok';
  properties.data_quality_issues = issues.join('; ');
  return { email: clean.email, properties, issues };
}

function buildProductInputs(orders) {
  const byId = new Map();
  for (const order of orders) {
    for (const item of order.line_items ?? []) {
      const id = String(item.product_id);
      if (byId.has(id)) continue;
      byId.set(id, {
        idProperty: 'woo_product_id',
        id,
        properties: { woo_product_id: id, name: item.name, price: money(Number(item.price)), hs_sku: item.sku || undefined },
      });
    }
  }
  return [...byId.values()];
}

function buildDealInput(order, { pipelineId, stageIds }) {
  const stageKey = STAGE_BY_STATUS[order.status];
  if (!stageKey) throw new Error(`Unknown Woo status "${order.status}" on order ${order.id}`);
  const id = String(order.id);
  const name = [order.billing?.first_name, order.billing?.last_name].filter(Boolean).join(' ').trim();
  return {
    idProperty: 'woo_order_id',
    id,
    properties: {
      woo_order_id: id,
      dealname: `Woo #${order.number ?? id}${name ? ` — ${name}` : ''}`,
      pipeline: pipelineId,
      dealstage: stageIds[stageKey],
      amount: order.status === 'refunded' ? money(0) : money(netTotal(order)),
      refund_amount: money(refundTotal(order)),
      closedate: isoUtc(order.date_created_gmt),
      woo_status: order.status,
      deal_currency_code: order.currency,
    },
  };
}

function buildLineItemInputs(order) {
  return (order.line_items ?? []).map((item) => {
    const id = String(item.id);
    return {
      idProperty: 'woo_line_item_id',
      id,
      wooProductId: String(item.product_id),
      properties: {
        woo_line_item_id: id,
        name: item.name,
        quantity: String(item.quantity),
        price: money(Number(item.price)),
        hs_sku: item.sku || undefined,
      },
    };
  });
}

function aggregateCustomer(orders) {
  const paid = orders.filter((o) => PAID_STATUSES.has(o.status));
  const dates = paid.map((o) => o.date_created_gmt.slice(0, 10)).sort();
  return {
    total_orders: paid.length,
    total_revenue: Math.round(paid.reduce((s, o) => s + netTotal(o), 0) * 100) / 100,
    first_order_date: dates[0] ?? null,
    last_order_date: dates.at(-1) ?? null,
  };
}

// ---- src/lib/sync-plan.js ----
// Turns a batch of Woo orders into the ordered list of HubSpot requests the sync-orders workflow makes.
// Every function returns plain request objects { method, path, body, label } — or { skip: true, label }
// when there is nothing to send — so the n8n flow stays linear and every step is unit-tested here.



const BATCH = 100;
const skip = (label) => ({ skip: true, label });
const post = (path, body, label) => ({ method: 'POST', path, body, label });
// Batch writes tolerate 4xx: HubSpot rejects a whole batch for one bad record, and that must become a
// ticket naming the records, not abort the other 99 orders. `ids` lets the ticket say which records.
const batches = (path, inputs, label, idOf = (i) => i.id) =>
  (inputs.length
    ? chunk(inputs, BATCH).map((part, i) => ({
      ...post(path, { inputs: part }, `${label} ${i + 1}`), tolerateClientError: true, ids: part.map(idOf).map(String),
    }))
    : [skip(label)]);
const lower = (s) => String(s ?? '').trim().toLowerCase();

/** Searches `objectType` for records whose `property` is any of `values` (≤100 values per search). */
function searchIn(objectType, property, values, label) {
  const unique = [...new Set(values.map(String))];
  if (!unique.length) return [skip(label)];
  return chunk(unique, BATCH).map((part, i) => post(`/crm/v3/objects/${objectType}/search`, {
    filterGroups: [{ filters: [{ propertyName: property, operator: 'IN', values: part }] }],
    properties: [property],
    limit: BATCH,
  }, `${label} ${i + 1}`));
}

/** For objects HubSpot cannot upsert by our key: update what the search found, create the rest. */
function updateOrCreate(objectType, key, items, found, label) {
  const updates = [];
  const creates = [];
  for (const properties of items) {
    const id = found.get(lower(properties[key]));
    if (id) updates.push({ id, properties });
    else creates.push({ properties });
  }
  const idOf = (i) => i.properties[key];
  const requests = [
    ...(updates.length ? batches(`/crm/v3/objects/${objectType}/batch/update`, updates, `${label} update`, idOf) : []),
    ...(creates.length ? batches(`/crm/v3/objects/${objectType}/batch/create`, creates, `${label} create`, idOf) : []),
  ];
  return requests.length ? requests : [skip(label)];
}

function pipelineContext(dealPipelines, ticketPipelines) {
  const find = (list, def) => {
    const p = (list?.results ?? []).find((x) => x.label === def.label);
    if (!p) throw new Error(`HubSpot pipeline "${def.label}" not found — run scripts/hubspot-setup.mjs first`);
    const ids = {};
    for (const s of def.stages) {
      const stage = p.stages.find((x) => x.label === s.label);
      if (!stage) throw new Error(`Stage "${s.label}" missing in pipeline "${def.label}" — run scripts/hubspot-setup.mjs`);
      ids[s.key] = stage.id;
    }
    return { id: p.id, ids };
  };
  const deals = find(dealPipelines, DEAL_PIPELINE);
  const tickets = find(ticketPipelines, TICKET_PIPELINE);
  return { pipelineId: deals.id, stageIds: deals.ids, ticketPipelineId: tickets.id, ticketStageNewId: tickets.ids.new };
}

function contactRequests(orders, history) {
  const byEmail = new Map();
  for (const order of orders) {
    const contact = buildContactInput(order);
    if (contact.email) byEmail.set(contact.email, contact);
  }
  const inputs = [...byEmail.values()].map(({ email, properties }) => {
    const agg = aggregateCustomer(history.filter((o) => lower(o.billing?.email) === email));
    const extra = Object.fromEntries(Object.entries(agg).filter(([, v]) => v !== null));
    return { idProperty: 'email', id: email, properties: { ...properties, ...extra } };
  });
  return batches('/crm/v3/objects/contacts/batch/upsert', inputs, 'contacts');
}

function companySearchRequest(orders) {
  const domains = planCompanies(orders).map((c) => c.domain);
  if (!domains.length) return skip('company search');
  return post('/crm/v3/objects/companies/search', {
    filterGroups: [{ filters: [{ propertyName: 'domain', operator: 'IN', values: domains }] }],
    properties: ['domain', 'name'],
    limit: BATCH,
  }, 'company search');
}

function companyCreateRequest(orders, searchResponse) {
  const found = idMap([searchResponse], 'domain');
  const inputs = planCompanies(orders)
    .filter((c) => !found.has(c.domain))
    .map((c) => ({ properties: { domain: c.domain, name: c.name } }));
  return inputs.length
    ? batches('/crm/v3/objects/companies/batch/create', inputs, 'company create', (i) => i.properties.domain)[0]
    : skip('company create');
}

const productSearchRequests = (orders) =>
  searchIn('products', 'woo_product_id', buildProductInputs(orders).map((p) => p.id), 'product search');

const productWriteRequests = (orders, searchResponses) => updateOrCreate(
  'products', 'woo_product_id', buildProductInputs(orders).map((p) => p.properties),
  idMap(searchResponses, 'woo_product_id'), 'products',
);

function dealRequests(orders, ctx) {
  const inputs = [];
  const problems = [];
  for (const order of orders) {
    try {
      inputs.push(buildDealInput(order, ctx));
    } catch (err) {
      problems.push({
        key: `unknown-status:${order.id}`,
        subject: `Woo order #${order.number ?? order.id} not synced: unknown status`,
        content: err.message,
        priority: 'HIGH',
      });
    }
  }
  return { requests: batches('/crm/v3/objects/deals/batch/upsert', inputs, 'deals'), problems };
}

const lineItemSearchRequests = (orders) =>
  searchIn('line_items', 'woo_line_item_id', orders.flatMap(buildLineItemInputs).map((li) => li.id), 'line item search');

function lineItemWriteRequests(orders, productIds, searchResponses) {
  const items = orders.flatMap(buildLineItemInputs).map(({ wooProductId, properties }) => {
    const hsProductId = productIds.get(wooProductId);
    return hsProductId ? { ...properties, hs_product_id: hsProductId } : properties;
  });
  return updateOrCreate('line_items', 'woo_line_item_id', items, idMap(searchResponses, 'woo_line_item_id'), 'line items');
}

/** value of `property` (lowercased) → HubSpot record id, from any number of batch/search responses. */
function idMap(responses, property) {
  const map = new Map();
  for (const r of responses) {
    for (const rec of r?.body?.results ?? []) {
      const value = rec.properties?.[property];
      if (value != null) map.set(lower(value), String(rec.id));
    }
  }
  return map;
}

function associationRequests({ orders, contactIds, companyIds, dealIds, lineItemIds }) {
  const pairs = { 'contacts/companies': new Map(), 'deals/contacts': new Map(), 'deals/companies': new Map(), 'line_items/deals': new Map() };
  const add = (kind, from, to) => { if (from && to) pairs[kind].set(`${from}>${to}`, { from: { id: from }, to: { id: to } }); };
  for (const order of orders) {
    const email = lower(order.billing?.email);
    const contactId = contactIds.get(email);
    const companyId = companyIds.get(companyDomain(email) ?? '');
    const dealId = dealIds.get(String(order.id));
    add('contacts/companies', contactId, companyId);
    add('deals/contacts', dealId, contactId);
    add('deals/companies', dealId, companyId);
    for (const item of order.line_items ?? []) add('line_items/deals', lineItemIds.get(String(item.id)), dealId);
  }
  return Object.entries(pairs).map(([kind, map]) => (map.size
    ? { ...post(`/crm/v4/associations/${kind}/batch/associate/default`, { inputs: [...map.values()] }, `associate ${kind}`),
      tolerateClientError: true, ids: [...map.keys()] }
    : skip(`associate ${kind}`)));
}

function syncProblems(orders, responses, extra = []) {
  const problems = [];
  for (const order of orders) {
    const contact = buildContactInput(order);
    if (!contact.email) {
      problems.push({
        key: `no-contact:${order.id}`,
        subject: `Woo order #${order.number ?? order.id} synced without a contact`,
        content: `Billing email "${order.billing?.email ?? ''}" was rejected (${contact.issues.join('; ')}). `
          + 'The deal was synced; fix the email in WooCommerce and save the order to link a contact.',
        priority: 'MEDIUM',
      });
    }
  }
  for (const r of responses) {
    if (r && r.ok === false) {
      const ids = r.ids ?? [];
      problems.push({
        key: `batch-failed:${String(r.label).replace(/ \d+$/, '')}:${ids[0] ?? 'none'}..${ids.at(-1) ?? 'none'}`,
        subject: `HubSpot rejected a whole ${r.label} batch (${ids.length} records)`,
        content: `HTTP ${r.status} ${r.body?.category ?? ''}: ${r.body?.message ?? JSON.stringify(r.body ?? '')}
`
          + `Records: ${ids.join(', ')}`.slice(0, 1800),
        priority: 'HIGH',
      });
      continue;
    }
    for (const e of r?.body?.errors ?? []) {
      for (const id of e.context?.ids ?? ['unknown']) {
        problems.push({
          key: `batch:${String(r.label).replace(/ \d+$/, '')}:${id}`,
          subject: `HubSpot rejected ${r.label} record ${id}`,
          content: `${e.category ?? 'ERROR'}: ${e.message ?? ''}`.slice(0, 2000),
          priority: 'HIGH',
        });
      }
    }
  }
  return [...problems, ...extra];
}

function ticketReadRequest(problems) {
  if (!problems.length) return skip('ticket lookup');
  return searchIn('tickets', 'sync_error_key', problems.slice(0, BATCH).map((p) => p.key), 'ticket lookup')[0];
}

function ticketCreateRequest(problems, readResponse, ctx) {
  const existing = idMap([readResponse], 'sync_error_key');
  const inputs = problems.slice(0, BATCH)
    .filter((p) => !existing.has(lower(p.key)))
    .map((p) => ({
      properties: {
        sync_error_key: p.key,
        subject: p.subject,
        content: p.content,
        hs_pipeline: ctx.ticketPipelineId,
        hs_pipeline_stage: ctx.ticketStageNewId,
        hs_ticket_priority: p.priority,
      },
    }));
  return inputs.length
    ? batches('/crm/v3/objects/tickets/batch/create', inputs, 'tickets', (i) => i.properties.sync_error_key)[0]
    : skip('tickets');
}

// ---- step ----
const input = $('Sync in').first().json;
const orders = input.orders;
const history = input.history ?? orders;
const responses = (node) => $(node).all().map((item) => item.json);
const ctx = () => { const [deals, tickets] = responses('Get pipelines'); return pipelineContext(deals.body, tickets.body); };
const out = (requests) => [].concat(requests).map((json) => ({ json }));
return out(dealRequests(orders, ctx()).requests);

// ---- src/lib/validate.js ----
// Data-quality checks (flow F3). Pure functions: inlined into n8n Code nodes by build-workflows.
// Rule: never block the sync. Invalid values become null and are reported as issues.

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[a-z]{2,}$/;

const DISPOSABLE_DOMAINS = new Set([
  'mailinator.com', '10minutemail.com', 'guerrillamail.com', 'yopmail.com', 'tempmail.com',
]);

// Common typos of webmail domains → correct domain.
const DOMAIN_TYPOS = {
  'gmial.com': 'gmail.com', 'gmal.com': 'gmail.com', 'gnail.com': 'gmail.com', 'gmail.con': 'gmail.com',
  'gmial.con': 'gmail.com', 'gmail.cmo': 'gmail.com',
  'hotmial.com': 'hotmail.com', 'hotmal.com': 'hotmail.com', 'hotmail.con': 'hotmail.com',
  'yaho.com': 'yahoo.com', 'yahoo.con': 'yahoo.com', 'outlok.com': 'outlook.com',
};

const DIAL_CODES = {
  AR: '54', US: '1', MX: '52', ES: '34', CL: '56', UY: '598', BR: '55', CO: '57', PE: '51', GB: '44', DE: '49',
};

const COUNTRY_NAMES = {
  argentina: 'AR',
  'united states': 'US', usa: 'US', 'estados unidos': 'US', eeuu: 'US',
  mexico: 'MX', 'méxico': 'MX',
  spain: 'ES', 'españa': 'ES', espana: 'ES',
  chile: 'CL', uruguay: 'UY',
  brazil: 'BR', brasil: 'BR',
  colombia: 'CO', peru: 'PE', 'perú': 'PE',
  'united kingdom': 'GB', uk: 'GB', 'reino unido': 'GB',
  germany: 'DE', alemania: 'DE',
};

function validateEmail(raw) {
  const email = String(raw ?? '').trim().toLowerCase();
  if (!EMAIL_RE.test(email)) return { value: null, issue: 'email_invalid_format' };
  const [local, domain] = email.split('@');
  // Dot errors pass the simple pattern but HubSpot rejects them (and one bad email would fail a whole batch).
  if (/^\.|\.$|\.\./.test(local) || domain.split('.').some((label) => !label)) {
    return { value: null, issue: 'email_invalid_format' };
  }
  if (DOMAIN_TYPOS[domain]) return { value: null, issue: `email_typo_domain:${domain}→${DOMAIN_TYPOS[domain]}` };
  if (DISPOSABLE_DOMAINS.has(domain)) return { value: null, issue: 'email_disposable' };
  return { value: email, issue: null };
}

function normalizePhone(raw, countryIso2) {
  const text = String(raw ?? '').trim();
  if (!text) return { value: null, issue: null };
  const invalid = { value: null, issue: 'phone_invalid' };
  const digits = text.replace(/\D/g, '');
  if (/[a-z]/i.test(text) || !digits) return invalid;

  let e164;
  if (text.startsWith('+')) {
    e164 = digits;
  } else {
    const dial = DIAL_CODES[countryIso2] ?? DIAL_CODES.AR;
    let national = digits;
    if (national.startsWith(dial) && national.length > 10) national = national.slice(dial.length);
    national = national.replace(/^0/, ''); // trunk prefix (AR, ES, GB, DE…)
    if (national.length < 6) return invalid;
    e164 = dial + national;
  }
  if (e164.length < 8 || e164.length > 15) return invalid;
  return { value: `+${e164}`, issue: null };
}

function normalizeCountry(raw) {
  const text = String(raw ?? '').trim();
  if (!text) return { value: null, issue: null };
  const upper = text.toUpperCase();
  if (DIAL_CODES[upper]) return { value: upper, issue: null };
  const byName = COUNTRY_NAMES[text.toLowerCase()];
  return byName ? { value: byName, issue: null } : { value: null, issue: 'country_unknown' };
}

function validateCustomer(billing = {}) {
  const issues = [];
  const take = (result) => {
    if (result.issue) issues.push(result.issue);
    return result.value;
  };
  const email = take(validateEmail(billing.email));
  const country = take(normalizeCountry(billing.country));
  const phone = take(normalizePhone(billing.phone, country));
  const clean = {
    email,
    phone,
    country,
    firstname: String(billing.first_name ?? '').trim() || null,
    lastname: String(billing.last_name ?? '').trim() || null,
    company: String(billing.company ?? '').trim() || null,
  };
  return { clean, issues };
}

// ---- src/lib/hubspot-schema.js ----
// HubSpot schema the sync needs. Created idempotently by scripts/hubspot-setup.mjs.

const PROPERTY_GROUP = { name: 'woocommerce', label: 'WooCommerce', displayOrder: -1 };

const base = { groupName: PROPERTY_GROUP.name };
const text = (name, label, extra = {}) => ({ ...base, name, label, type: 'string', fieldType: 'text', ...extra });
const number = (name, label) => ({ ...base, name, label, type: 'number', fieldType: 'number' });
const date = (name, label) => ({ ...base, name, label, type: 'date', fieldType: 'date' });
const select = (name, label, values) => ({
  ...base, name, label, type: 'enumeration', fieldType: 'select',
  options: values.map(([value, optionLabel], displayOrder) => ({ value, label: optionLabel, displayOrder })),
});
const uniqueId = (name, label) => text(name, label, { hasUniqueValue: true });

const PROPERTIES = {
  contacts: [
    text('woo_customer_id', 'Woo customer ID'),
    number('total_orders', 'Total orders (paid)'),
    number('total_revenue', 'Total revenue (net of refunds)'),
    date('first_order_date', 'First order date'),
    date('last_order_date', 'Last order date'),
    select('customer_segment', 'Customer segment', [['new', 'New'], ['repeat', 'Repeat'], ['vip', 'VIP']]),
    select('data_quality_status', 'Data quality status', [['ok', 'OK'], ['needs_review', 'Needs review']]),
    text('data_quality_issues', 'Data quality issues', { type: 'string', fieldType: 'textarea' }),
  ],
  deals: [
    uniqueId('woo_order_id', 'Woo order ID'),
    number('refund_amount', 'Refund amount'),
    text('woo_status', 'Woo order status'),
  ],
  // HubSpot does not support unique-value properties on products (and does not document them for line
  // items), so these two are looked up by search and then updated or created — see sync-plan.js.
  products: [text('woo_product_id', 'Woo product ID')],
  line_items: [text('woo_line_item_id', 'Woo line item ID')],
  // One ticket per distinct sync problem, so re-running the backfill never duplicates tickets.
  tickets: [uniqueId('sync_error_key', 'Sync error key')],
};

const stage = (key, label, displayOrder, metadata) => ({ key, label, displayOrder, metadata });

const DEAL_PIPELINE = {
  label: 'WooCommerce',
  displayOrder: 1,
  stages: [
    stage('pending_payment', 'Pending payment', 0, { probability: '0.2' }),
    stage('paid', 'Paid', 1, { probability: '0.9' }),
    stage('closedwon', 'Closed won', 2, { probability: '1.0' }),
    stage('closedlost', 'Closed lost', 3, { probability: '0.0' }),
    stage('refunded', 'Refunded', 4, { probability: '0.0' }),
  ],
};

const TICKET_PIPELINE = {
  label: 'Integration errors',
  displayOrder: 1,
  stages: [
    stage('new', 'New', 0, { ticketState: 'OPEN' }),
    stage('resolved', 'Resolved', 1, { ticketState: 'CLOSED' }),
  ],
};

// ---- src/lib/retry.js ----
// Retry policy for HubSpot calls (flow F4). Ceiling: 100 requests / 10 s, batches of ≤100.

const MAX_ATTEMPTS = 3;

// 429 = rate limit, 423 = HubSpot's "Locked" during high sync volume, 5xx = transient server errors.
function shouldRetry(status) {
  return status === 429 || status === 423 || (status >= 500 && status <= 599);
}

// Exponential (1 s, 2 s, 4 s…), but never shorter than what the error needs: a 429 without Retry-After
// waits out the whole 10 s rate window; a 423 waits at least 2 s (HubSpot's guidance).
function backoffDelayMs(attempt, retryAfterHeader, status) {
  const retryAfter = Number(retryAfterHeader);
  if (retryAfterHeader != null && Number.isFinite(retryAfter) && retryAfter > 0) return retryAfter * 1000;
  const exponential = 1000 * 2 ** (attempt - 1);
  if (status === 429) return Math.max(exponential, 10000);
  if (status === 423) return Math.max(exponential, 2000);
  return exponential;
}

function chunk(items, size) {
  const out = [];
  for (let i = 0; i < items.length; i += size) out.push(items.slice(i, i + size));
  return out;
}

// ---- src/lib/mapping.js ----
// WooCommerce order → HubSpot CRM inputs. Pure functions, inlined into n8n Code nodes.

// Woo status → internal stage key. Real HubSpot stage ids come from hubspot-setup (.hubspot-ids.json).
const STAGE_BY_STATUS = {
  pending: 'pending_payment',
  'on-hold': 'pending_payment',
  processing: 'paid',
  completed: 'closedwon',
  cancelled: 'closedlost',
  failed: 'closedlost',
  refunded: 'refunded',
};

const PAID_STATUSES = new Set(['processing', 'completed']);

const FREE_EMAIL_DOMAINS = new Set([
  'gmail.com', 'googlemail.com', 'hotmail.com', 'outlook.com', 'live.com', 'yahoo.com', 'yahoo.com.ar',
  'icloud.com', 'aol.com', 'proton.me', 'protonmail.com',
]);

const money = (n) => (Math.round(n * 100) / 100).toFixed(2);

function refundTotal(order) {
  return (order.refunds ?? []).reduce((sum, r) => sum + Math.abs(Number(r.total) || 0), 0);
}

function netTotal(order) {
  return Math.max(0, Number(order.total) - refundTotal(order));
}

const isoUtc = (wooGmtDate) => new Date(`${wooGmtDate}Z`).toISOString();

function companyDomain(email) {
  const { value } = validateEmail(email);
  if (!value) return null;
  const domain = value.split('@')[1];
  return FREE_EMAIL_DOMAINS.has(domain) ? null : domain;
}

function planCompanies(orders) {
  const byDomain = new Map();
  for (const order of orders) {
    const domain = companyDomain(order.billing?.email);
    if (!domain) continue;
    const name = String(order.billing?.company ?? '').trim();
    const existing = byDomain.get(domain);
    if (!existing || (existing.name === domain && name)) byDomain.set(domain, { domain, name: name || domain });
  }
  return [...byDomain.values()];
}

function buildContactInput(order) {
  const { clean, issues } = validateCustomer(order.billing);
  const properties = {};
  for (const [key, value] of Object.entries(clean)) if (value) properties[key] = value;
  if (Number(order.customer_id) > 0) properties.woo_customer_id = String(order.customer_id);
  properties.data_quality_status = issues.length ? 'needs_review' : 'ok';
  properties.data_quality_issues = issues.join('; ');
  return { email: clean.email, properties, issues };
}

function buildProductInputs(orders) {
  const byId = new Map();
  for (const order of orders) {
    for (const item of order.line_items ?? []) {
      const id = String(item.product_id);
      if (byId.has(id)) continue;
      byId.set(id, {
        idProperty: 'woo_product_id',
        id,
        properties: { woo_product_id: id, name: item.name, price: money(Number(item.price)), hs_sku: item.sku || undefined },
      });
    }
  }
  return [...byId.values()];
}

function buildDealInput(order, { pipelineId, stageIds }) {
  const stageKey = STAGE_BY_STATUS[order.status];
  if (!stageKey) throw new Error(`Unknown Woo status "${order.status}" on order ${order.id}`);
  const id = String(order.id);
  const name = [order.billing?.first_name, order.billing?.last_name].filter(Boolean).join(' ').trim();
  return {
    idProperty: 'woo_order_id',
    id,
    properties: {
      woo_order_id: id,
      dealname: `Woo #${order.number ?? id}${name ? ` — ${name}` : ''}`,
      pipeline: pipelineId,
      dealstage: stageIds[stageKey],
      amount: order.status === 'refunded' ? money(0) : money(netTotal(order)),
      refund_amount: money(refundTotal(order)),
      closedate: isoUtc(order.date_created_gmt),
      woo_status: order.status,
      deal_currency_code: order.currency,
    },
  };
}

function buildLineItemInputs(order) {
  return (order.line_items ?? []).map((item) => {
    const id = String(item.id);
    return {
      idProperty: 'woo_line_item_id',
      id,
      wooProductId: String(item.product_id),
      properties: {
        woo_line_item_id: id,
        name: item.name,
        quantity: String(item.quantity),
        price: money(Number(item.price)),
        hs_sku: item.sku || undefined,
      },
    };
  });
}

function aggregateCustomer(orders) {
  const paid = orders.filter((o) => PAID_STATUSES.has(o.status));
  const dates = paid.map((o) => o.date_created_gmt.slice(0, 10)).sort();
  return {
    total_orders: paid.length,
    total_revenue: Math.round(paid.reduce((s, o) => s + netTotal(o), 0) * 100) / 100,
    first_order_date: dates[0] ?? null,
    last_order_date: dates.at(-1) ?? null,
  };
}

// ---- src/lib/sync-plan.js ----
// Turns a batch of Woo orders into the ordered list of HubSpot requests the sync-orders workflow makes.
// Every function returns plain request objects { method, path, body, label } — or { skip: true, label }
// when there is nothing to send — so the n8n flow stays linear and every step is unit-tested here.



const BATCH = 100;
const skip = (label) => ({ skip: true, label });
const post = (path, body, label) => ({ method: 'POST', path, body, label });
// Batch writes tolerate 4xx: HubSpot rejects a whole batch for one bad record, and that must become a
// ticket naming the records, not abort the other 99 orders. `ids` lets the ticket say which records.
const batches = (path, inputs, label, idOf = (i) => i.id) =>
  (inputs.length
    ? chunk(inputs, BATCH).map((part, i) => ({
      ...post(path, { inputs: part }, `${label} ${i + 1}`), tolerateClientError: true, ids: part.map(idOf).map(String),
    }))
    : [skip(label)]);
const lower = (s) => String(s ?? '').trim().toLowerCase();

/** Searches `objectType` for records whose `property` is any of `values` (≤100 values per search). */
function searchIn(objectType, property, values, label) {
  const unique = [...new Set(values.map(String))];
  if (!unique.length) return [skip(label)];
  return chunk(unique, BATCH).map((part, i) => post(`/crm/v3/objects/${objectType}/search`, {
    filterGroups: [{ filters: [{ propertyName: property, operator: 'IN', values: part }] }],
    properties: [property],
    limit: BATCH,
  }, `${label} ${i + 1}`));
}

/** For objects HubSpot cannot upsert by our key: update what the search found, create the rest. */
function updateOrCreate(objectType, key, items, found, label) {
  const updates = [];
  const creates = [];
  for (const properties of items) {
    const id = found.get(lower(properties[key]));
    if (id) updates.push({ id, properties });
    else creates.push({ properties });
  }
  const idOf = (i) => i.properties[key];
  const requests = [
    ...(updates.length ? batches(`/crm/v3/objects/${objectType}/batch/update`, updates, `${label} update`, idOf) : []),
    ...(creates.length ? batches(`/crm/v3/objects/${objectType}/batch/create`, creates, `${label} create`, idOf) : []),
  ];
  return requests.length ? requests : [skip(label)];
}

function pipelineContext(dealPipelines, ticketPipelines) {
  const find = (list, def) => {
    const p = (list?.results ?? []).find((x) => x.label === def.label);
    if (!p) throw new Error(`HubSpot pipeline "${def.label}" not found — run scripts/hubspot-setup.mjs first`);
    const ids = {};
    for (const s of def.stages) {
      const stage = p.stages.find((x) => x.label === s.label);
      if (!stage) throw new Error(`Stage "${s.label}" missing in pipeline "${def.label}" — run scripts/hubspot-setup.mjs`);
      ids[s.key] = stage.id;
    }
    return { id: p.id, ids };
  };
  const deals = find(dealPipelines, DEAL_PIPELINE);
  const tickets = find(ticketPipelines, TICKET_PIPELINE);
  return { pipelineId: deals.id, stageIds: deals.ids, ticketPipelineId: tickets.id, ticketStageNewId: tickets.ids.new };
}

function contactRequests(orders, history) {
  const byEmail = new Map();
  for (const order of orders) {
    const contact = buildContactInput(order);
    if (contact.email) byEmail.set(contact.email, contact);
  }
  const inputs = [...byEmail.values()].map(({ email, properties }) => {
    const agg = aggregateCustomer(history.filter((o) => lower(o.billing?.email) === email));
    const extra = Object.fromEntries(Object.entries(agg).filter(([, v]) => v !== null));
    return { idProperty: 'email', id: email, properties: { ...properties, ...extra } };
  });
  return batches('/crm/v3/objects/contacts/batch/upsert', inputs, 'contacts');
}

function companySearchRequest(orders) {
  const domains = planCompanies(orders).map((c) => c.domain);
  if (!domains.length) return skip('company search');
  return post('/crm/v3/objects/companies/search', {
    filterGroups: [{ filters: [{ propertyName: 'domain', operator: 'IN', values: domains }] }],
    properties: ['domain', 'name'],
    limit: BATCH,
  }, 'company search');
}

function companyCreateRequest(orders, searchResponse) {
  const found = idMap([searchResponse], 'domain');
  const inputs = planCompanies(orders)
    .filter((c) => !found.has(c.domain))
    .map((c) => ({ properties: { domain: c.domain, name: c.name } }));
  return inputs.length
    ? batches('/crm/v3/objects/companies/batch/create', inputs, 'company create', (i) => i.properties.domain)[0]
    : skip('company create');
}

const productSearchRequests = (orders) =>
  searchIn('products', 'woo_product_id', buildProductInputs(orders).map((p) => p.id), 'product search');

const productWriteRequests = (orders, searchResponses) => updateOrCreate(
  'products', 'woo_product_id', buildProductInputs(orders).map((p) => p.properties),
  idMap(searchResponses, 'woo_product_id'), 'products',
);

function dealRequests(orders, ctx) {
  const inputs = [];
  const problems = [];
  for (const order of orders) {
    try {
      inputs.push(buildDealInput(order, ctx));
    } catch (err) {
      problems.push({
        key: `unknown-status:${order.id}`,
        subject: `Woo order #${order.number ?? order.id} not synced: unknown status`,
        content: err.message,
        priority: 'HIGH',
      });
    }
  }
  return { requests: batches('/crm/v3/objects/deals/batch/upsert', inputs, 'deals'), problems };
}

const lineItemSearchRequests = (orders) =>
  searchIn('line_items', 'woo_line_item_id', orders.flatMap(buildLineItemInputs).map((li) => li.id), 'line item search');

function lineItemWriteRequests(orders, productIds, searchResponses) {
  const items = orders.flatMap(buildLineItemInputs).map(({ wooProductId, properties }) => {
    const hsProductId = productIds.get(wooProductId);
    return hsProductId ? { ...properties, hs_product_id: hsProductId } : properties;
  });
  return updateOrCreate('line_items', 'woo_line_item_id', items, idMap(searchResponses, 'woo_line_item_id'), 'line items');
}

/** value of `property` (lowercased) → HubSpot record id, from any number of batch/search responses. */
function idMap(responses, property) {
  const map = new Map();
  for (const r of responses) {
    for (const rec of r?.body?.results ?? []) {
      const value = rec.properties?.[property];
      if (value != null) map.set(lower(value), String(rec.id));
    }
  }
  return map;
}

function associationRequests({ orders, contactIds, companyIds, dealIds, lineItemIds }) {
  const pairs = { 'contacts/companies': new Map(), 'deals/contacts': new Map(), 'deals/companies': new Map(), 'line_items/deals': new Map() };
  const add = (kind, from, to) => { if (from && to) pairs[kind].set(`${from}>${to}`, { from: { id: from }, to: { id: to } }); };
  for (const order of orders) {
    const email = lower(order.billing?.email);
    const contactId = contactIds.get(email);
    const companyId = companyIds.get(companyDomain(email) ?? '');
    const dealId = dealIds.get(String(order.id));
    add('contacts/companies', contactId, companyId);
    add('deals/contacts', dealId, contactId);
    add('deals/companies', dealId, companyId);
    for (const item of order.line_items ?? []) add('line_items/deals', lineItemIds.get(String(item.id)), dealId);
  }
  return Object.entries(pairs).map(([kind, map]) => (map.size
    ? { ...post(`/crm/v4/associations/${kind}/batch/associate/default`, { inputs: [...map.values()] }, `associate ${kind}`),
      tolerateClientError: true, ids: [...map.keys()] }
    : skip(`associate ${kind}`)));
}

function syncProblems(orders, responses, extra = []) {
  const problems = [];
  for (const order of orders) {
    const contact = buildContactInput(order);
    if (!contact.email) {
      problems.push({
        key: `no-contact:${order.id}`,
        subject: `Woo order #${order.number ?? order.id} synced without a contact`,
        content: `Billing email "${order.billing?.email ?? ''}" was rejected (${contact.issues.join('; ')}). `
          + 'The deal was synced; fix the email in WooCommerce and save the order to link a contact.',
        priority: 'MEDIUM',
      });
    }
  }
  for (const r of responses) {
    if (r && r.ok === false) {
      const ids = r.ids ?? [];
      problems.push({
        key: `batch-failed:${String(r.label).replace(/ \d+$/, '')}:${ids[0] ?? 'none'}..${ids.at(-1) ?? 'none'}`,
        subject: `HubSpot rejected a whole ${r.label} batch (${ids.length} records)`,
        content: `HTTP ${r.status} ${r.body?.category ?? ''}: ${r.body?.message ?? JSON.stringify(r.body ?? '')}
`
          + `Records: ${ids.join(', ')}`.slice(0, 1800),
        priority: 'HIGH',
      });
      continue;
    }
    for (const e of r?.body?.errors ?? []) {
      for (const id of e.context?.ids ?? ['unknown']) {
        problems.push({
          key: `batch:${String(r.label).replace(/ \d+$/, '')}:${id}`,
          subject: `HubSpot rejected ${r.label} record ${id}`,
          content: `${e.category ?? 'ERROR'}: ${e.message ?? ''}`.slice(0, 2000),
          priority: 'HIGH',
        });
      }
    }
  }
  return [...problems, ...extra];
}

function ticketReadRequest(problems) {
  if (!problems.length) return skip('ticket lookup');
  return searchIn('tickets', 'sync_error_key', problems.slice(0, BATCH).map((p) => p.key), 'ticket lookup')[0];
}

function ticketCreateRequest(problems, readResponse, ctx) {
  const existing = idMap([readResponse], 'sync_error_key');
  const inputs = problems.slice(0, BATCH)
    .filter((p) => !existing.has(lower(p.key)))
    .map((p) => ({
      properties: {
        sync_error_key: p.key,
        subject: p.subject,
        content: p.content,
        hs_pipeline: ctx.ticketPipelineId,
        hs_pipeline_stage: ctx.ticketStageNewId,
        hs_ticket_priority: p.priority,
      },
    }));
  return inputs.length
    ? batches('/crm/v3/objects/tickets/batch/create', inputs, 'tickets', (i) => i.properties.sync_error_key)[0]
    : skip('tickets');
}

// ---- step ----
const input = $('Sync in').first().json;
const orders = input.orders;
const history = input.history ?? orders;
const responses = (node) => $(node).all().map((item) => item.json);
const ctx = () => { const [deals, tickets] = responses('Get pipelines'); return pipelineContext(deals.body, tickets.body); };
const out = (requests) => [].concat(requests).map((json) => ({ json }));
return out(lineItemSearchRequests(orders));

// ---- src/lib/validate.js ----
// Data-quality checks (flow F3). Pure functions: inlined into n8n Code nodes by build-workflows.
// Rule: never block the sync. Invalid values become null and are reported as issues.

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[a-z]{2,}$/;

const DISPOSABLE_DOMAINS = new Set([
  'mailinator.com', '10minutemail.com', 'guerrillamail.com', 'yopmail.com', 'tempmail.com',
]);

// Common typos of webmail domains → correct domain.
const DOMAIN_TYPOS = {
  'gmial.com': 'gmail.com', 'gmal.com': 'gmail.com', 'gnail.com': 'gmail.com', 'gmail.con': 'gmail.com',
  'gmial.con': 'gmail.com', 'gmail.cmo': 'gmail.com',
  'hotmial.com': 'hotmail.com', 'hotmal.com': 'hotmail.com', 'hotmail.con': 'hotmail.com',
  'yaho.com': 'yahoo.com', 'yahoo.con': 'yahoo.com', 'outlok.com': 'outlook.com',
};

const DIAL_CODES = {
  AR: '54', US: '1', MX: '52', ES: '34', CL: '56', UY: '598', BR: '55', CO: '57', PE: '51', GB: '44', DE: '49',
};

const COUNTRY_NAMES = {
  argentina: 'AR',
  'united states': 'US', usa: 'US', 'estados unidos': 'US', eeuu: 'US',
  mexico: 'MX', 'méxico': 'MX',
  spain: 'ES', 'españa': 'ES', espana: 'ES',
  chile: 'CL', uruguay: 'UY',
  brazil: 'BR', brasil: 'BR',
  colombia: 'CO', peru: 'PE', 'perú': 'PE',
  'united kingdom': 'GB', uk: 'GB', 'reino unido': 'GB',
  germany: 'DE', alemania: 'DE',
};

function validateEmail(raw) {
  const email = String(raw ?? '').trim().toLowerCase();
  if (!EMAIL_RE.test(email)) return { value: null, issue: 'email_invalid_format' };
  const [local, domain] = email.split('@');
  // Dot errors pass the simple pattern but HubSpot rejects them (and one bad email would fail a whole batch).
  if (/^\.|\.$|\.\./.test(local) || domain.split('.').some((label) => !label)) {
    return { value: null, issue: 'email_invalid_format' };
  }
  if (DOMAIN_TYPOS[domain]) return { value: null, issue: `email_typo_domain:${domain}→${DOMAIN_TYPOS[domain]}` };
  if (DISPOSABLE_DOMAINS.has(domain)) return { value: null, issue: 'email_disposable' };
  return { value: email, issue: null };
}

function normalizePhone(raw, countryIso2) {
  const text = String(raw ?? '').trim();
  if (!text) return { value: null, issue: null };
  const invalid = { value: null, issue: 'phone_invalid' };
  const digits = text.replace(/\D/g, '');
  if (/[a-z]/i.test(text) || !digits) return invalid;

  let e164;
  if (text.startsWith('+')) {
    e164 = digits;
  } else {
    const dial = DIAL_CODES[countryIso2] ?? DIAL_CODES.AR;
    let national = digits;
    if (national.startsWith(dial) && national.length > 10) national = national.slice(dial.length);
    national = national.replace(/^0/, ''); // trunk prefix (AR, ES, GB, DE…)
    if (national.length < 6) return invalid;
    e164 = dial + national;
  }
  if (e164.length < 8 || e164.length > 15) return invalid;
  return { value: `+${e164}`, issue: null };
}

function normalizeCountry(raw) {
  const text = String(raw ?? '').trim();
  if (!text) return { value: null, issue: null };
  const upper = text.toUpperCase();
  if (DIAL_CODES[upper]) return { value: upper, issue: null };
  const byName = COUNTRY_NAMES[text.toLowerCase()];
  return byName ? { value: byName, issue: null } : { value: null, issue: 'country_unknown' };
}

function validateCustomer(billing = {}) {
  const issues = [];
  const take = (result) => {
    if (result.issue) issues.push(result.issue);
    return result.value;
  };
  const email = take(validateEmail(billing.email));
  const country = take(normalizeCountry(billing.country));
  const phone = take(normalizePhone(billing.phone, country));
  const clean = {
    email,
    phone,
    country,
    firstname: String(billing.first_name ?? '').trim() || null,
    lastname: String(billing.last_name ?? '').trim() || null,
    company: String(billing.company ?? '').trim() || null,
  };
  return { clean, issues };
}

// ---- src/lib/hubspot-schema.js ----
// HubSpot schema the sync needs. Created idempotently by scripts/hubspot-setup.mjs.

const PROPERTY_GROUP = { name: 'woocommerce', label: 'WooCommerce', displayOrder: -1 };

const base = { groupName: PROPERTY_GROUP.name };
const text = (name, label, extra = {}) => ({ ...base, name, label, type: 'string', fieldType: 'text', ...extra });
const number = (name, label) => ({ ...base, name, label, type: 'number', fieldType: 'number' });
const date = (name, label) => ({ ...base, name, label, type: 'date', fieldType: 'date' });
const select = (name, label, values) => ({
  ...base, name, label, type: 'enumeration', fieldType: 'select',
  options: values.map(([value, optionLabel], displayOrder) => ({ value, label: optionLabel, displayOrder })),
});
const uniqueId = (name, label) => text(name, label, { hasUniqueValue: true });

const PROPERTIES = {
  contacts: [
    text('woo_customer_id', 'Woo customer ID'),
    number('total_orders', 'Total orders (paid)'),
    number('total_revenue', 'Total revenue (net of refunds)'),
    date('first_order_date', 'First order date'),
    date('last_order_date', 'Last order date'),
    select('customer_segment', 'Customer segment', [['new', 'New'], ['repeat', 'Repeat'], ['vip', 'VIP']]),
    select('data_quality_status', 'Data quality status', [['ok', 'OK'], ['needs_review', 'Needs review']]),
    text('data_quality_issues', 'Data quality issues', { type: 'string', fieldType: 'textarea' }),
  ],
  deals: [
    uniqueId('woo_order_id', 'Woo order ID'),
    number('refund_amount', 'Refund amount'),
    text('woo_status', 'Woo order status'),
  ],
  // HubSpot does not support unique-value properties on products (and does not document them for line
  // items), so these two are looked up by search and then updated or created — see sync-plan.js.
  products: [text('woo_product_id', 'Woo product ID')],
  line_items: [text('woo_line_item_id', 'Woo line item ID')],
  // One ticket per distinct sync problem, so re-running the backfill never duplicates tickets.
  tickets: [uniqueId('sync_error_key', 'Sync error key')],
};

const stage = (key, label, displayOrder, metadata) => ({ key, label, displayOrder, metadata });

const DEAL_PIPELINE = {
  label: 'WooCommerce',
  displayOrder: 1,
  stages: [
    stage('pending_payment', 'Pending payment', 0, { probability: '0.2' }),
    stage('paid', 'Paid', 1, { probability: '0.9' }),
    stage('closedwon', 'Closed won', 2, { probability: '1.0' }),
    stage('closedlost', 'Closed lost', 3, { probability: '0.0' }),
    stage('refunded', 'Refunded', 4, { probability: '0.0' }),
  ],
};

const TICKET_PIPELINE = {
  label: 'Integration errors',
  displayOrder: 1,
  stages: [
    stage('new', 'New', 0, { ticketState: 'OPEN' }),
    stage('resolved', 'Resolved', 1, { ticketState: 'CLOSED' }),
  ],
};

// ---- src/lib/retry.js ----
// Retry policy for HubSpot calls (flow F4). Ceiling: 100 requests / 10 s, batches of ≤100.

const MAX_ATTEMPTS = 3;

// 429 = rate limit, 423 = HubSpot's "Locked" during high sync volume, 5xx = transient server errors.
function shouldRetry(status) {
  return status === 429 || status === 423 || (status >= 500 && status <= 599);
}

// Exponential (1 s, 2 s, 4 s…), but never shorter than what the error needs: a 429 without Retry-After
// waits out the whole 10 s rate window; a 423 waits at least 2 s (HubSpot's guidance).
function backoffDelayMs(attempt, retryAfterHeader, status) {
  const retryAfter = Number(retryAfterHeader);
  if (retryAfterHeader != null && Number.isFinite(retryAfter) && retryAfter > 0) return retryAfter * 1000;
  const exponential = 1000 * 2 ** (attempt - 1);
  if (status === 429) return Math.max(exponential, 10000);
  if (status === 423) return Math.max(exponential, 2000);
  return exponential;
}

function chunk(items, size) {
  const out = [];
  for (let i = 0; i < items.length; i += size) out.push(items.slice(i, i + size));
  return out;
}

// ---- src/lib/mapping.js ----
// WooCommerce order → HubSpot CRM inputs. Pure functions, inlined into n8n Code nodes.

// Woo status → internal stage key. Real HubSpot stage ids come from hubspot-setup (.hubspot-ids.json).
const STAGE_BY_STATUS = {
  pending: 'pending_payment',
  'on-hold': 'pending_payment',
  processing: 'paid',
  completed: 'closedwon',
  cancelled: 'closedlost',
  failed: 'closedlost',
  refunded: 'refunded',
};

const PAID_STATUSES = new Set(['processing', 'completed']);

const FREE_EMAIL_DOMAINS = new Set([
  'gmail.com', 'googlemail.com', 'hotmail.com', 'outlook.com', 'live.com', 'yahoo.com', 'yahoo.com.ar',
  'icloud.com', 'aol.com', 'proton.me', 'protonmail.com',
]);

const money = (n) => (Math.round(n * 100) / 100).toFixed(2);

function refundTotal(order) {
  return (order.refunds ?? []).reduce((sum, r) => sum + Math.abs(Number(r.total) || 0), 0);
}

function netTotal(order) {
  return Math.max(0, Number(order.total) - refundTotal(order));
}

const isoUtc = (wooGmtDate) => new Date(`${wooGmtDate}Z`).toISOString();

function companyDomain(email) {
  const { value } = validateEmail(email);
  if (!value) return null;
  const domain = value.split('@')[1];
  return FREE_EMAIL_DOMAINS.has(domain) ? null : domain;
}

function planCompanies(orders) {
  const byDomain = new Map();
  for (const order of orders) {
    const domain = companyDomain(order.billing?.email);
    if (!domain) continue;
    const name = String(order.billing?.company ?? '').trim();
    const existing = byDomain.get(domain);
    if (!existing || (existing.name === domain && name)) byDomain.set(domain, { domain, name: name || domain });
  }
  return [...byDomain.values()];
}

function buildContactInput(order) {
  const { clean, issues } = validateCustomer(order.billing);
  const properties = {};
  for (const [key, value] of Object.entries(clean)) if (value) properties[key] = value;
  if (Number(order.customer_id) > 0) properties.woo_customer_id = String(order.customer_id);
  properties.data_quality_status = issues.length ? 'needs_review' : 'ok';
  properties.data_quality_issues = issues.join('; ');
  return { email: clean.email, properties, issues };
}

function buildProductInputs(orders) {
  const byId = new Map();
  for (const order of orders) {
    for (const item of order.line_items ?? []) {
      const id = String(item.product_id);
      if (byId.has(id)) continue;
      byId.set(id, {
        idProperty: 'woo_product_id',
        id,
        properties: { woo_product_id: id, name: item.name, price: money(Number(item.price)), hs_sku: item.sku || undefined },
      });
    }
  }
  return [...byId.values()];
}

function buildDealInput(order, { pipelineId, stageIds }) {
  const stageKey = STAGE_BY_STATUS[order.status];
  if (!stageKey) throw new Error(`Unknown Woo status "${order.status}" on order ${order.id}`);
  const id = String(order.id);
  const name = [order.billing?.first_name, order.billing?.last_name].filter(Boolean).join(' ').trim();
  return {
    idProperty: 'woo_order_id',
    id,
    properties: {
      woo_order_id: id,
      dealname: `Woo #${order.number ?? id}${name ? ` — ${name}` : ''}`,
      pipeline: pipelineId,
      dealstage: stageIds[stageKey],
      amount: order.status === 'refunded' ? money(0) : money(netTotal(order)),
      refund_amount: money(refundTotal(order)),
      closedate: isoUtc(order.date_created_gmt),
      woo_status: order.status,
      deal_currency_code: order.currency,
    },
  };
}

function buildLineItemInputs(order) {
  return (order.line_items ?? []).map((item) => {
    const id = String(item.id);
    return {
      idProperty: 'woo_line_item_id',
      id,
      wooProductId: String(item.product_id),
      properties: {
        woo_line_item_id: id,
        name: item.name,
        quantity: String(item.quantity),
        price: money(Number(item.price)),
        hs_sku: item.sku || undefined,
      },
    };
  });
}

function aggregateCustomer(orders) {
  const paid = orders.filter((o) => PAID_STATUSES.has(o.status));
  const dates = paid.map((o) => o.date_created_gmt.slice(0, 10)).sort();
  return {
    total_orders: paid.length,
    total_revenue: Math.round(paid.reduce((s, o) => s + netTotal(o), 0) * 100) / 100,
    first_order_date: dates[0] ?? null,
    last_order_date: dates.at(-1) ?? null,
  };
}

// ---- src/lib/sync-plan.js ----
// Turns a batch of Woo orders into the ordered list of HubSpot requests the sync-orders workflow makes.
// Every function returns plain request objects { method, path, body, label } — or { skip: true, label }
// when there is nothing to send — so the n8n flow stays linear and every step is unit-tested here.



const BATCH = 100;
const skip = (label) => ({ skip: true, label });
const post = (path, body, label) => ({ method: 'POST', path, body, label });
// Batch writes tolerate 4xx: HubSpot rejects a whole batch for one bad record, and that must become a
// ticket naming the records, not abort the other 99 orders. `ids` lets the ticket say which records.
const batches = (path, inputs, label, idOf = (i) => i.id) =>
  (inputs.length
    ? chunk(inputs, BATCH).map((part, i) => ({
      ...post(path, { inputs: part }, `${label} ${i + 1}`), tolerateClientError: true, ids: part.map(idOf).map(String),
    }))
    : [skip(label)]);
const lower = (s) => String(s ?? '').trim().toLowerCase();

/** Searches `objectType` for records whose `property` is any of `values` (≤100 values per search). */
function searchIn(objectType, property, values, label) {
  const unique = [...new Set(values.map(String))];
  if (!unique.length) return [skip(label)];
  return chunk(unique, BATCH).map((part, i) => post(`/crm/v3/objects/${objectType}/search`, {
    filterGroups: [{ filters: [{ propertyName: property, operator: 'IN', values: part }] }],
    properties: [property],
    limit: BATCH,
  }, `${label} ${i + 1}`));
}

/** For objects HubSpot cannot upsert by our key: update what the search found, create the rest. */
function updateOrCreate(objectType, key, items, found, label) {
  const updates = [];
  const creates = [];
  for (const properties of items) {
    const id = found.get(lower(properties[key]));
    if (id) updates.push({ id, properties });
    else creates.push({ properties });
  }
  const idOf = (i) => i.properties[key];
  const requests = [
    ...(updates.length ? batches(`/crm/v3/objects/${objectType}/batch/update`, updates, `${label} update`, idOf) : []),
    ...(creates.length ? batches(`/crm/v3/objects/${objectType}/batch/create`, creates, `${label} create`, idOf) : []),
  ];
  return requests.length ? requests : [skip(label)];
}

function pipelineContext(dealPipelines, ticketPipelines) {
  const find = (list, def) => {
    const p = (list?.results ?? []).find((x) => x.label === def.label);
    if (!p) throw new Error(`HubSpot pipeline "${def.label}" not found — run scripts/hubspot-setup.mjs first`);
    const ids = {};
    for (const s of def.stages) {
      const stage = p.stages.find((x) => x.label === s.label);
      if (!stage) throw new Error(`Stage "${s.label}" missing in pipeline "${def.label}" — run scripts/hubspot-setup.mjs`);
      ids[s.key] = stage.id;
    }
    return { id: p.id, ids };
  };
  const deals = find(dealPipelines, DEAL_PIPELINE);
  const tickets = find(ticketPipelines, TICKET_PIPELINE);
  return { pipelineId: deals.id, stageIds: deals.ids, ticketPipelineId: tickets.id, ticketStageNewId: tickets.ids.new };
}

function contactRequests(orders, history) {
  const byEmail = new Map();
  for (const order of orders) {
    const contact = buildContactInput(order);
    if (contact.email) byEmail.set(contact.email, contact);
  }
  const inputs = [...byEmail.values()].map(({ email, properties }) => {
    const agg = aggregateCustomer(history.filter((o) => lower(o.billing?.email) === email));
    const extra = Object.fromEntries(Object.entries(agg).filter(([, v]) => v !== null));
    return { idProperty: 'email', id: email, properties: { ...properties, ...extra } };
  });
  return batches('/crm/v3/objects/contacts/batch/upsert', inputs, 'contacts');
}

function companySearchRequest(orders) {
  const domains = planCompanies(orders).map((c) => c.domain);
  if (!domains.length) return skip('company search');
  return post('/crm/v3/objects/companies/search', {
    filterGroups: [{ filters: [{ propertyName: 'domain', operator: 'IN', values: domains }] }],
    properties: ['domain', 'name'],
    limit: BATCH,
  }, 'company search');
}

function companyCreateRequest(orders, searchResponse) {
  const found = idMap([searchResponse], 'domain');
  const inputs = planCompanies(orders)
    .filter((c) => !found.has(c.domain))
    .map((c) => ({ properties: { domain: c.domain, name: c.name } }));
  return inputs.length
    ? batches('/crm/v3/objects/companies/batch/create', inputs, 'company create', (i) => i.properties.domain)[0]
    : skip('company create');
}

const productSearchRequests = (orders) =>
  searchIn('products', 'woo_product_id', buildProductInputs(orders).map((p) => p.id), 'product search');

const productWriteRequests = (orders, searchResponses) => updateOrCreate(
  'products', 'woo_product_id', buildProductInputs(orders).map((p) => p.properties),
  idMap(searchResponses, 'woo_product_id'), 'products',
);

function dealRequests(orders, ctx) {
  const inputs = [];
  const problems = [];
  for (const order of orders) {
    try {
      inputs.push(buildDealInput(order, ctx));
    } catch (err) {
      problems.push({
        key: `unknown-status:${order.id}`,
        subject: `Woo order #${order.number ?? order.id} not synced: unknown status`,
        content: err.message,
        priority: 'HIGH',
      });
    }
  }
  return { requests: batches('/crm/v3/objects/deals/batch/upsert', inputs, 'deals'), problems };
}

const lineItemSearchRequests = (orders) =>
  searchIn('line_items', 'woo_line_item_id', orders.flatMap(buildLineItemInputs).map((li) => li.id), 'line item search');

function lineItemWriteRequests(orders, productIds, searchResponses) {
  const items = orders.flatMap(buildLineItemInputs).map(({ wooProductId, properties }) => {
    const hsProductId = productIds.get(wooProductId);
    return hsProductId ? { ...properties, hs_product_id: hsProductId } : properties;
  });
  return updateOrCreate('line_items', 'woo_line_item_id', items, idMap(searchResponses, 'woo_line_item_id'), 'line items');
}

/** value of `property` (lowercased) → HubSpot record id, from any number of batch/search responses. */
function idMap(responses, property) {
  const map = new Map();
  for (const r of responses) {
    for (const rec of r?.body?.results ?? []) {
      const value = rec.properties?.[property];
      if (value != null) map.set(lower(value), String(rec.id));
    }
  }
  return map;
}

function associationRequests({ orders, contactIds, companyIds, dealIds, lineItemIds }) {
  const pairs = { 'contacts/companies': new Map(), 'deals/contacts': new Map(), 'deals/companies': new Map(), 'line_items/deals': new Map() };
  const add = (kind, from, to) => { if (from && to) pairs[kind].set(`${from}>${to}`, { from: { id: from }, to: { id: to } }); };
  for (const order of orders) {
    const email = lower(order.billing?.email);
    const contactId = contactIds.get(email);
    const companyId = companyIds.get(companyDomain(email) ?? '');
    const dealId = dealIds.get(String(order.id));
    add('contacts/companies', contactId, companyId);
    add('deals/contacts', dealId, contactId);
    add('deals/companies', dealId, companyId);
    for (const item of order.line_items ?? []) add('line_items/deals', lineItemIds.get(String(item.id)), dealId);
  }
  return Object.entries(pairs).map(([kind, map]) => (map.size
    ? { ...post(`/crm/v4/associations/${kind}/batch/associate/default`, { inputs: [...map.values()] }, `associate ${kind}`),
      tolerateClientError: true, ids: [...map.keys()] }
    : skip(`associate ${kind}`)));
}

function syncProblems(orders, responses, extra = []) {
  const problems = [];
  for (const order of orders) {
    const contact = buildContactInput(order);
    if (!contact.email) {
      problems.push({
        key: `no-contact:${order.id}`,
        subject: `Woo order #${order.number ?? order.id} synced without a contact`,
        content: `Billing email "${order.billing?.email ?? ''}" was rejected (${contact.issues.join('; ')}). `
          + 'The deal was synced; fix the email in WooCommerce and save the order to link a contact.',
        priority: 'MEDIUM',
      });
    }
  }
  for (const r of responses) {
    if (r && r.ok === false) {
      const ids = r.ids ?? [];
      problems.push({
        key: `batch-failed:${String(r.label).replace(/ \d+$/, '')}:${ids[0] ?? 'none'}..${ids.at(-1) ?? 'none'}`,
        subject: `HubSpot rejected a whole ${r.label} batch (${ids.length} records)`,
        content: `HTTP ${r.status} ${r.body?.category ?? ''}: ${r.body?.message ?? JSON.stringify(r.body ?? '')}
`
          + `Records: ${ids.join(', ')}`.slice(0, 1800),
        priority: 'HIGH',
      });
      continue;
    }
    for (const e of r?.body?.errors ?? []) {
      for (const id of e.context?.ids ?? ['unknown']) {
        problems.push({
          key: `batch:${String(r.label).replace(/ \d+$/, '')}:${id}`,
          subject: `HubSpot rejected ${r.label} record ${id}`,
          content: `${e.category ?? 'ERROR'}: ${e.message ?? ''}`.slice(0, 2000),
          priority: 'HIGH',
        });
      }
    }
  }
  return [...problems, ...extra];
}

function ticketReadRequest(problems) {
  if (!problems.length) return skip('ticket lookup');
  return searchIn('tickets', 'sync_error_key', problems.slice(0, BATCH).map((p) => p.key), 'ticket lookup')[0];
}

function ticketCreateRequest(problems, readResponse, ctx) {
  const existing = idMap([readResponse], 'sync_error_key');
  const inputs = problems.slice(0, BATCH)
    .filter((p) => !existing.has(lower(p.key)))
    .map((p) => ({
      properties: {
        sync_error_key: p.key,
        subject: p.subject,
        content: p.content,
        hs_pipeline: ctx.ticketPipelineId,
        hs_pipeline_stage: ctx.ticketStageNewId,
        hs_ticket_priority: p.priority,
      },
    }));
  return inputs.length
    ? batches('/crm/v3/objects/tickets/batch/create', inputs, 'tickets', (i) => i.properties.sync_error_key)[0]
    : skip('tickets');
}

// ---- step ----
const input = $('Sync in').first().json;
const orders = input.orders;
const history = input.history ?? orders;
const responses = (node) => $(node).all().map((item) => item.json);
const ctx = () => { const [deals, tickets] = responses('Get pipelines'); return pipelineContext(deals.body, tickets.body); };
const out = (requests) => [].concat(requests).map((json) => ({ json }));
const productIds = idMap([...responses('Search products'), ...responses('Upsert products')], 'woo_product_id');
return out(lineItemWriteRequests(orders, productIds, responses('Search line items')));

// ---- src/lib/validate.js ----
// Data-quality checks (flow F3). Pure functions: inlined into n8n Code nodes by build-workflows.
// Rule: never block the sync. Invalid values become null and are reported as issues.

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[a-z]{2,}$/;

const DISPOSABLE_DOMAINS = new Set([
  'mailinator.com', '10minutemail.com', 'guerrillamail.com', 'yopmail.com', 'tempmail.com',
]);

// Common typos of webmail domains → correct domain.
const DOMAIN_TYPOS = {
  'gmial.com': 'gmail.com', 'gmal.com': 'gmail.com', 'gnail.com': 'gmail.com', 'gmail.con': 'gmail.com',
  'gmial.con': 'gmail.com', 'gmail.cmo': 'gmail.com',
  'hotmial.com': 'hotmail.com', 'hotmal.com': 'hotmail.com', 'hotmail.con': 'hotmail.com',
  'yaho.com': 'yahoo.com', 'yahoo.con': 'yahoo.com', 'outlok.com': 'outlook.com',
};

const DIAL_CODES = {
  AR: '54', US: '1', MX: '52', ES: '34', CL: '56', UY: '598', BR: '55', CO: '57', PE: '51', GB: '44', DE: '49',
};

const COUNTRY_NAMES = {
  argentina: 'AR',
  'united states': 'US', usa: 'US', 'estados unidos': 'US', eeuu: 'US',
  mexico: 'MX', 'méxico': 'MX',
  spain: 'ES', 'españa': 'ES', espana: 'ES',
  chile: 'CL', uruguay: 'UY',
  brazil: 'BR', brasil: 'BR',
  colombia: 'CO', peru: 'PE', 'perú': 'PE',
  'united kingdom': 'GB', uk: 'GB', 'reino unido': 'GB',
  germany: 'DE', alemania: 'DE',
};

function validateEmail(raw) {
  const email = String(raw ?? '').trim().toLowerCase();
  if (!EMAIL_RE.test(email)) return { value: null, issue: 'email_invalid_format' };
  const [local, domain] = email.split('@');
  // Dot errors pass the simple pattern but HubSpot rejects them (and one bad email would fail a whole batch).
  if (/^\.|\.$|\.\./.test(local) || domain.split('.').some((label) => !label)) {
    return { value: null, issue: 'email_invalid_format' };
  }
  if (DOMAIN_TYPOS[domain]) return { value: null, issue: `email_typo_domain:${domain}→${DOMAIN_TYPOS[domain]}` };
  if (DISPOSABLE_DOMAINS.has(domain)) return { value: null, issue: 'email_disposable' };
  return { value: email, issue: null };
}

function normalizePhone(raw, countryIso2) {
  const text = String(raw ?? '').trim();
  if (!text) return { value: null, issue: null };
  const invalid = { value: null, issue: 'phone_invalid' };
  const digits = text.replace(/\D/g, '');
  if (/[a-z]/i.test(text) || !digits) return invalid;

  let e164;
  if (text.startsWith('+')) {
    e164 = digits;
  } else {
    const dial = DIAL_CODES[countryIso2] ?? DIAL_CODES.AR;
    let national = digits;
    if (national.startsWith(dial) && national.length > 10) national = national.slice(dial.length);
    national = national.replace(/^0/, ''); // trunk prefix (AR, ES, GB, DE…)
    if (national.length < 6) return invalid;
    e164 = dial + national;
  }
  if (e164.length < 8 || e164.length > 15) return invalid;
  return { value: `+${e164}`, issue: null };
}

function normalizeCountry(raw) {
  const text = String(raw ?? '').trim();
  if (!text) return { value: null, issue: null };
  const upper = text.toUpperCase();
  if (DIAL_CODES[upper]) return { value: upper, issue: null };
  const byName = COUNTRY_NAMES[text.toLowerCase()];
  return byName ? { value: byName, issue: null } : { value: null, issue: 'country_unknown' };
}

function validateCustomer(billing = {}) {
  const issues = [];
  const take = (result) => {
    if (result.issue) issues.push(result.issue);
    return result.value;
  };
  const email = take(validateEmail(billing.email));
  const country = take(normalizeCountry(billing.country));
  const phone = take(normalizePhone(billing.phone, country));
  const clean = {
    email,
    phone,
    country,
    firstname: String(billing.first_name ?? '').trim() || null,
    lastname: String(billing.last_name ?? '').trim() || null,
    company: String(billing.company ?? '').trim() || null,
  };
  return { clean, issues };
}

// ---- src/lib/hubspot-schema.js ----
// HubSpot schema the sync needs. Created idempotently by scripts/hubspot-setup.mjs.

const PROPERTY_GROUP = { name: 'woocommerce', label: 'WooCommerce', displayOrder: -1 };

const base = { groupName: PROPERTY_GROUP.name };
const text = (name, label, extra = {}) => ({ ...base, name, label, type: 'string', fieldType: 'text', ...extra });
const number = (name, label) => ({ ...base, name, label, type: 'number', fieldType: 'number' });
const date = (name, label) => ({ ...base, name, label, type: 'date', fieldType: 'date' });
const select = (name, label, values) => ({
  ...base, name, label, type: 'enumeration', fieldType: 'select',
  options: values.map(([value, optionLabel], displayOrder) => ({ value, label: optionLabel, displayOrder })),
});
const uniqueId = (name, label) => text(name, label, { hasUniqueValue: true });

const PROPERTIES = {
  contacts: [
    text('woo_customer_id', 'Woo customer ID'),
    number('total_orders', 'Total orders (paid)'),
    number('total_revenue', 'Total revenue (net of refunds)'),
    date('first_order_date', 'First order date'),
    date('last_order_date', 'Last order date'),
    select('customer_segment', 'Customer segment', [['new', 'New'], ['repeat', 'Repeat'], ['vip', 'VIP']]),
    select('data_quality_status', 'Data quality status', [['ok', 'OK'], ['needs_review', 'Needs review']]),
    text('data_quality_issues', 'Data quality issues', { type: 'string', fieldType: 'textarea' }),
  ],
  deals: [
    uniqueId('woo_order_id', 'Woo order ID'),
    number('refund_amount', 'Refund amount'),
    text('woo_status', 'Woo order status'),
  ],
  // HubSpot does not support unique-value properties on products (and does not document them for line
  // items), so these two are looked up by search and then updated or created — see sync-plan.js.
  products: [text('woo_product_id', 'Woo product ID')],
  line_items: [text('woo_line_item_id', 'Woo line item ID')],
  // One ticket per distinct sync problem, so re-running the backfill never duplicates tickets.
  tickets: [uniqueId('sync_error_key', 'Sync error key')],
};

const stage = (key, label, displayOrder, metadata) => ({ key, label, displayOrder, metadata });

const DEAL_PIPELINE = {
  label: 'WooCommerce',
  displayOrder: 1,
  stages: [
    stage('pending_payment', 'Pending payment', 0, { probability: '0.2' }),
    stage('paid', 'Paid', 1, { probability: '0.9' }),
    stage('closedwon', 'Closed won', 2, { probability: '1.0' }),
    stage('closedlost', 'Closed lost', 3, { probability: '0.0' }),
    stage('refunded', 'Refunded', 4, { probability: '0.0' }),
  ],
};

const TICKET_PIPELINE = {
  label: 'Integration errors',
  displayOrder: 1,
  stages: [
    stage('new', 'New', 0, { ticketState: 'OPEN' }),
    stage('resolved', 'Resolved', 1, { ticketState: 'CLOSED' }),
  ],
};

// ---- src/lib/retry.js ----
// Retry policy for HubSpot calls (flow F4). Ceiling: 100 requests / 10 s, batches of ≤100.

const MAX_ATTEMPTS = 3;

// 429 = rate limit, 423 = HubSpot's "Locked" during high sync volume, 5xx = transient server errors.
function shouldRetry(status) {
  return status === 429 || status === 423 || (status >= 500 && status <= 599);
}

// Exponential (1 s, 2 s, 4 s…), but never shorter than what the error needs: a 429 without Retry-After
// waits out the whole 10 s rate window; a 423 waits at least 2 s (HubSpot's guidance).
function backoffDelayMs(attempt, retryAfterHeader, status) {
  const retryAfter = Number(retryAfterHeader);
  if (retryAfterHeader != null && Number.isFinite(retryAfter) && retryAfter > 0) return retryAfter * 1000;
  const exponential = 1000 * 2 ** (attempt - 1);
  if (status === 429) return Math.max(exponential, 10000);
  if (status === 423) return Math.max(exponential, 2000);
  return exponential;
}

function chunk(items, size) {
  const out = [];
  for (let i = 0; i < items.length; i += size) out.push(items.slice(i, i + size));
  return out;
}

// ---- src/lib/mapping.js ----
// WooCommerce order → HubSpot CRM inputs. Pure functions, inlined into n8n Code nodes.

// Woo status → internal stage key. Real HubSpot stage ids come from hubspot-setup (.hubspot-ids.json).
const STAGE_BY_STATUS = {
  pending: 'pending_payment',
  'on-hold': 'pending_payment',
  processing: 'paid',
  completed: 'closedwon',
  cancelled: 'closedlost',
  failed: 'closedlost',
  refunded: 'refunded',
};

const PAID_STATUSES = new Set(['processing', 'completed']);

const FREE_EMAIL_DOMAINS = new Set([
  'gmail.com', 'googlemail.com', 'hotmail.com', 'outlook.com', 'live.com', 'yahoo.com', 'yahoo.com.ar',
  'icloud.com', 'aol.com', 'proton.me', 'protonmail.com',
]);

const money = (n) => (Math.round(n * 100) / 100).toFixed(2);

function refundTotal(order) {
  return (order.refunds ?? []).reduce((sum, r) => sum + Math.abs(Number(r.total) || 0), 0);
}

function netTotal(order) {
  return Math.max(0, Number(order.total) - refundTotal(order));
}

const isoUtc = (wooGmtDate) => new Date(`${wooGmtDate}Z`).toISOString();

function companyDomain(email) {
  const { value } = validateEmail(email);
  if (!value) return null;
  const domain = value.split('@')[1];
  return FREE_EMAIL_DOMAINS.has(domain) ? null : domain;
}

function planCompanies(orders) {
  const byDomain = new Map();
  for (const order of orders) {
    const domain = companyDomain(order.billing?.email);
    if (!domain) continue;
    const name = String(order.billing?.company ?? '').trim();
    const existing = byDomain.get(domain);
    if (!existing || (existing.name === domain && name)) byDomain.set(domain, { domain, name: name || domain });
  }
  return [...byDomain.values()];
}

function buildContactInput(order) {
  const { clean, issues } = validateCustomer(order.billing);
  const properties = {};
  for (const [key, value] of Object.entries(clean)) if (value) properties[key] = value;
  if (Number(order.customer_id) > 0) properties.woo_customer_id = String(order.customer_id);
  properties.data_quality_status = issues.length ? 'needs_review' : 'ok';
  properties.data_quality_issues = issues.join('; ');
  return { email: clean.email, properties, issues };
}

function buildProductInputs(orders) {
  const byId = new Map();
  for (const order of orders) {
    for (const item of order.line_items ?? []) {
      const id = String(item.product_id);
      if (byId.has(id)) continue;
      byId.set(id, {
        idProperty: 'woo_product_id',
        id,
        properties: { woo_product_id: id, name: item.name, price: money(Number(item.price)), hs_sku: item.sku || undefined },
      });
    }
  }
  return [...byId.values()];
}

function buildDealInput(order, { pipelineId, stageIds }) {
  const stageKey = STAGE_BY_STATUS[order.status];
  if (!stageKey) throw new Error(`Unknown Woo status "${order.status}" on order ${order.id}`);
  const id = String(order.id);
  const name = [order.billing?.first_name, order.billing?.last_name].filter(Boolean).join(' ').trim();
  return {
    idProperty: 'woo_order_id',
    id,
    properties: {
      woo_order_id: id,
      dealname: `Woo #${order.number ?? id}${name ? ` — ${name}` : ''}`,
      pipeline: pipelineId,
      dealstage: stageIds[stageKey],
      amount: order.status === 'refunded' ? money(0) : money(netTotal(order)),
      refund_amount: money(refundTotal(order)),
      closedate: isoUtc(order.date_created_gmt),
      woo_status: order.status,
      deal_currency_code: order.currency,
    },
  };
}

function buildLineItemInputs(order) {
  return (order.line_items ?? []).map((item) => {
    const id = String(item.id);
    return {
      idProperty: 'woo_line_item_id',
      id,
      wooProductId: String(item.product_id),
      properties: {
        woo_line_item_id: id,
        name: item.name,
        quantity: String(item.quantity),
        price: money(Number(item.price)),
        hs_sku: item.sku || undefined,
      },
    };
  });
}

function aggregateCustomer(orders) {
  const paid = orders.filter((o) => PAID_STATUSES.has(o.status));
  const dates = paid.map((o) => o.date_created_gmt.slice(0, 10)).sort();
  return {
    total_orders: paid.length,
    total_revenue: Math.round(paid.reduce((s, o) => s + netTotal(o), 0) * 100) / 100,
    first_order_date: dates[0] ?? null,
    last_order_date: dates.at(-1) ?? null,
  };
}

// ---- src/lib/sync-plan.js ----
// Turns a batch of Woo orders into the ordered list of HubSpot requests the sync-orders workflow makes.
// Every function returns plain request objects { method, path, body, label } — or { skip: true, label }
// when there is nothing to send — so the n8n flow stays linear and every step is unit-tested here.



const BATCH = 100;
const skip = (label) => ({ skip: true, label });
const post = (path, body, label) => ({ method: 'POST', path, body, label });
// Batch writes tolerate 4xx: HubSpot rejects a whole batch for one bad record, and that must become a
// ticket naming the records, not abort the other 99 orders. `ids` lets the ticket say which records.
const batches = (path, inputs, label, idOf = (i) => i.id) =>
  (inputs.length
    ? chunk(inputs, BATCH).map((part, i) => ({
      ...post(path, { inputs: part }, `${label} ${i + 1}`), tolerateClientError: true, ids: part.map(idOf).map(String),
    }))
    : [skip(label)]);
const lower = (s) => String(s ?? '').trim().toLowerCase();

/** Searches `objectType` for records whose `property` is any of `values` (≤100 values per search). */
function searchIn(objectType, property, values, label) {
  const unique = [...new Set(values.map(String))];
  if (!unique.length) return [skip(label)];
  return chunk(unique, BATCH).map((part, i) => post(`/crm/v3/objects/${objectType}/search`, {
    filterGroups: [{ filters: [{ propertyName: property, operator: 'IN', values: part }] }],
    properties: [property],
    limit: BATCH,
  }, `${label} ${i + 1}`));
}

/** For objects HubSpot cannot upsert by our key: update what the search found, create the rest. */
function updateOrCreate(objectType, key, items, found, label) {
  const updates = [];
  const creates = [];
  for (const properties of items) {
    const id = found.get(lower(properties[key]));
    if (id) updates.push({ id, properties });
    else creates.push({ properties });
  }
  const idOf = (i) => i.properties[key];
  const requests = [
    ...(updates.length ? batches(`/crm/v3/objects/${objectType}/batch/update`, updates, `${label} update`, idOf) : []),
    ...(creates.length ? batches(`/crm/v3/objects/${objectType}/batch/create`, creates, `${label} create`, idOf) : []),
  ];
  return requests.length ? requests : [skip(label)];
}

function pipelineContext(dealPipelines, ticketPipelines) {
  const find = (list, def) => {
    const p = (list?.results ?? []).find((x) => x.label === def.label);
    if (!p) throw new Error(`HubSpot pipeline "${def.label}" not found — run scripts/hubspot-setup.mjs first`);
    const ids = {};
    for (const s of def.stages) {
      const stage = p.stages.find((x) => x.label === s.label);
      if (!stage) throw new Error(`Stage "${s.label}" missing in pipeline "${def.label}" — run scripts/hubspot-setup.mjs`);
      ids[s.key] = stage.id;
    }
    return { id: p.id, ids };
  };
  const deals = find(dealPipelines, DEAL_PIPELINE);
  const tickets = find(ticketPipelines, TICKET_PIPELINE);
  return { pipelineId: deals.id, stageIds: deals.ids, ticketPipelineId: tickets.id, ticketStageNewId: tickets.ids.new };
}

function contactRequests(orders, history) {
  const byEmail = new Map();
  for (const order of orders) {
    const contact = buildContactInput(order);
    if (contact.email) byEmail.set(contact.email, contact);
  }
  const inputs = [...byEmail.values()].map(({ email, properties }) => {
    const agg = aggregateCustomer(history.filter((o) => lower(o.billing?.email) === email));
    const extra = Object.fromEntries(Object.entries(agg).filter(([, v]) => v !== null));
    return { idProperty: 'email', id: email, properties: { ...properties, ...extra } };
  });
  return batches('/crm/v3/objects/contacts/batch/upsert', inputs, 'contacts');
}

function companySearchRequest(orders) {
  const domains = planCompanies(orders).map((c) => c.domain);
  if (!domains.length) return skip('company search');
  return post('/crm/v3/objects/companies/search', {
    filterGroups: [{ filters: [{ propertyName: 'domain', operator: 'IN', values: domains }] }],
    properties: ['domain', 'name'],
    limit: BATCH,
  }, 'company search');
}

function companyCreateRequest(orders, searchResponse) {
  const found = idMap([searchResponse], 'domain');
  const inputs = planCompanies(orders)
    .filter((c) => !found.has(c.domain))
    .map((c) => ({ properties: { domain: c.domain, name: c.name } }));
  return inputs.length
    ? batches('/crm/v3/objects/companies/batch/create', inputs, 'company create', (i) => i.properties.domain)[0]
    : skip('company create');
}

const productSearchRequests = (orders) =>
  searchIn('products', 'woo_product_id', buildProductInputs(orders).map((p) => p.id), 'product search');

const productWriteRequests = (orders, searchResponses) => updateOrCreate(
  'products', 'woo_product_id', buildProductInputs(orders).map((p) => p.properties),
  idMap(searchResponses, 'woo_product_id'), 'products',
);

function dealRequests(orders, ctx) {
  const inputs = [];
  const problems = [];
  for (const order of orders) {
    try {
      inputs.push(buildDealInput(order, ctx));
    } catch (err) {
      problems.push({
        key: `unknown-status:${order.id}`,
        subject: `Woo order #${order.number ?? order.id} not synced: unknown status`,
        content: err.message,
        priority: 'HIGH',
      });
    }
  }
  return { requests: batches('/crm/v3/objects/deals/batch/upsert', inputs, 'deals'), problems };
}

const lineItemSearchRequests = (orders) =>
  searchIn('line_items', 'woo_line_item_id', orders.flatMap(buildLineItemInputs).map((li) => li.id), 'line item search');

function lineItemWriteRequests(orders, productIds, searchResponses) {
  const items = orders.flatMap(buildLineItemInputs).map(({ wooProductId, properties }) => {
    const hsProductId = productIds.get(wooProductId);
    return hsProductId ? { ...properties, hs_product_id: hsProductId } : properties;
  });
  return updateOrCreate('line_items', 'woo_line_item_id', items, idMap(searchResponses, 'woo_line_item_id'), 'line items');
}

/** value of `property` (lowercased) → HubSpot record id, from any number of batch/search responses. */
function idMap(responses, property) {
  const map = new Map();
  for (const r of responses) {
    for (const rec of r?.body?.results ?? []) {
      const value = rec.properties?.[property];
      if (value != null) map.set(lower(value), String(rec.id));
    }
  }
  return map;
}

function associationRequests({ orders, contactIds, companyIds, dealIds, lineItemIds }) {
  const pairs = { 'contacts/companies': new Map(), 'deals/contacts': new Map(), 'deals/companies': new Map(), 'line_items/deals': new Map() };
  const add = (kind, from, to) => { if (from && to) pairs[kind].set(`${from}>${to}`, { from: { id: from }, to: { id: to } }); };
  for (const order of orders) {
    const email = lower(order.billing?.email);
    const contactId = contactIds.get(email);
    const companyId = companyIds.get(companyDomain(email) ?? '');
    const dealId = dealIds.get(String(order.id));
    add('contacts/companies', contactId, companyId);
    add('deals/contacts', dealId, contactId);
    add('deals/companies', dealId, companyId);
    for (const item of order.line_items ?? []) add('line_items/deals', lineItemIds.get(String(item.id)), dealId);
  }
  return Object.entries(pairs).map(([kind, map]) => (map.size
    ? { ...post(`/crm/v4/associations/${kind}/batch/associate/default`, { inputs: [...map.values()] }, `associate ${kind}`),
      tolerateClientError: true, ids: [...map.keys()] }
    : skip(`associate ${kind}`)));
}

function syncProblems(orders, responses, extra = []) {
  const problems = [];
  for (const order of orders) {
    const contact = buildContactInput(order);
    if (!contact.email) {
      problems.push({
        key: `no-contact:${order.id}`,
        subject: `Woo order #${order.number ?? order.id} synced without a contact`,
        content: `Billing email "${order.billing?.email ?? ''}" was rejected (${contact.issues.join('; ')}). `
          + 'The deal was synced; fix the email in WooCommerce and save the order to link a contact.',
        priority: 'MEDIUM',
      });
    }
  }
  for (const r of responses) {
    if (r && r.ok === false) {
      const ids = r.ids ?? [];
      problems.push({
        key: `batch-failed:${String(r.label).replace(/ \d+$/, '')}:${ids[0] ?? 'none'}..${ids.at(-1) ?? 'none'}`,
        subject: `HubSpot rejected a whole ${r.label} batch (${ids.length} records)`,
        content: `HTTP ${r.status} ${r.body?.category ?? ''}: ${r.body?.message ?? JSON.stringify(r.body ?? '')}
`
          + `Records: ${ids.join(', ')}`.slice(0, 1800),
        priority: 'HIGH',
      });
      continue;
    }
    for (const e of r?.body?.errors ?? []) {
      for (const id of e.context?.ids ?? ['unknown']) {
        problems.push({
          key: `batch:${String(r.label).replace(/ \d+$/, '')}:${id}`,
          subject: `HubSpot rejected ${r.label} record ${id}`,
          content: `${e.category ?? 'ERROR'}: ${e.message ?? ''}`.slice(0, 2000),
          priority: 'HIGH',
        });
      }
    }
  }
  return [...problems, ...extra];
}

function ticketReadRequest(problems) {
  if (!problems.length) return skip('ticket lookup');
  return searchIn('tickets', 'sync_error_key', problems.slice(0, BATCH).map((p) => p.key), 'ticket lookup')[0];
}

function ticketCreateRequest(problems, readResponse, ctx) {
  const existing = idMap([readResponse], 'sync_error_key');
  const inputs = problems.slice(0, BATCH)
    .filter((p) => !existing.has(lower(p.key)))
    .map((p) => ({
      properties: {
        sync_error_key: p.key,
        subject: p.subject,
        content: p.content,
        hs_pipeline: ctx.ticketPipelineId,
        hs_pipeline_stage: ctx.ticketStageNewId,
        hs_ticket_priority: p.priority,
      },
    }));
  return inputs.length
    ? batches('/crm/v3/objects/tickets/batch/create', inputs, 'tickets', (i) => i.properties.sync_error_key)[0]
    : skip('tickets');
}

// ---- step ----
const input = $('Sync in').first().json;
const orders = input.orders;
const history = input.history ?? orders;
const responses = (node) => $(node).all().map((item) => item.json);
const ctx = () => { const [deals, tickets] = responses('Get pipelines'); return pipelineContext(deals.body, tickets.body); };
const out = (requests) => [].concat(requests).map((json) => ({ json }));
return out(associationRequests({
  orders,
  contactIds: idMap(responses('Upsert contacts'), 'email'),
  companyIds: idMap([...responses('Search companies'), ...responses('Create companies')], 'domain'),
  dealIds: idMap(responses('Upsert deals'), 'woo_order_id'),
  lineItemIds: idMap([...responses('Search line items'), ...responses('Upsert line items')], 'woo_line_item_id'),
}));

// ---- src/lib/validate.js ----
// Data-quality checks (flow F3). Pure functions: inlined into n8n Code nodes by build-workflows.
// Rule: never block the sync. Invalid values become null and are reported as issues.

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[a-z]{2,}$/;

const DISPOSABLE_DOMAINS = new Set([
  'mailinator.com', '10minutemail.com', 'guerrillamail.com', 'yopmail.com', 'tempmail.com',
]);

// Common typos of webmail domains → correct domain.
const DOMAIN_TYPOS = {
  'gmial.com': 'gmail.com', 'gmal.com': 'gmail.com', 'gnail.com': 'gmail.com', 'gmail.con': 'gmail.com',
  'gmial.con': 'gmail.com', 'gmail.cmo': 'gmail.com',
  'hotmial.com': 'hotmail.com', 'hotmal.com': 'hotmail.com', 'hotmail.con': 'hotmail.com',
  'yaho.com': 'yahoo.com', 'yahoo.con': 'yahoo.com', 'outlok.com': 'outlook.com',
};

const DIAL_CODES = {
  AR: '54', US: '1', MX: '52', ES: '34', CL: '56', UY: '598', BR: '55', CO: '57', PE: '51', GB: '44', DE: '49',
};

const COUNTRY_NAMES = {
  argentina: 'AR',
  'united states': 'US', usa: 'US', 'estados unidos': 'US', eeuu: 'US',
  mexico: 'MX', 'méxico': 'MX',
  spain: 'ES', 'españa': 'ES', espana: 'ES',
  chile: 'CL', uruguay: 'UY',
  brazil: 'BR', brasil: 'BR',
  colombia: 'CO', peru: 'PE', 'perú': 'PE',
  'united kingdom': 'GB', uk: 'GB', 'reino unido': 'GB',
  germany: 'DE', alemania: 'DE',
};

function validateEmail(raw) {
  const email = String(raw ?? '').trim().toLowerCase();
  if (!EMAIL_RE.test(email)) return { value: null, issue: 'email_invalid_format' };
  const [local, domain] = email.split('@');
  // Dot errors pass the simple pattern but HubSpot rejects them (and one bad email would fail a whole batch).
  if (/^\.|\.$|\.\./.test(local) || domain.split('.').some((label) => !label)) {
    return { value: null, issue: 'email_invalid_format' };
  }
  if (DOMAIN_TYPOS[domain]) return { value: null, issue: `email_typo_domain:${domain}→${DOMAIN_TYPOS[domain]}` };
  if (DISPOSABLE_DOMAINS.has(domain)) return { value: null, issue: 'email_disposable' };
  return { value: email, issue: null };
}

function normalizePhone(raw, countryIso2) {
  const text = String(raw ?? '').trim();
  if (!text) return { value: null, issue: null };
  const invalid = { value: null, issue: 'phone_invalid' };
  const digits = text.replace(/\D/g, '');
  if (/[a-z]/i.test(text) || !digits) return invalid;

  let e164;
  if (text.startsWith('+')) {
    e164 = digits;
  } else {
    const dial = DIAL_CODES[countryIso2] ?? DIAL_CODES.AR;
    let national = digits;
    if (national.startsWith(dial) && national.length > 10) national = national.slice(dial.length);
    national = national.replace(/^0/, ''); // trunk prefix (AR, ES, GB, DE…)
    if (national.length < 6) return invalid;
    e164 = dial + national;
  }
  if (e164.length < 8 || e164.length > 15) return invalid;
  return { value: `+${e164}`, issue: null };
}

function normalizeCountry(raw) {
  const text = String(raw ?? '').trim();
  if (!text) return { value: null, issue: null };
  const upper = text.toUpperCase();
  if (DIAL_CODES[upper]) return { value: upper, issue: null };
  const byName = COUNTRY_NAMES[text.toLowerCase()];
  return byName ? { value: byName, issue: null } : { value: null, issue: 'country_unknown' };
}

function validateCustomer(billing = {}) {
  const issues = [];
  const take = (result) => {
    if (result.issue) issues.push(result.issue);
    return result.value;
  };
  const email = take(validateEmail(billing.email));
  const country = take(normalizeCountry(billing.country));
  const phone = take(normalizePhone(billing.phone, country));
  const clean = {
    email,
    phone,
    country,
    firstname: String(billing.first_name ?? '').trim() || null,
    lastname: String(billing.last_name ?? '').trim() || null,
    company: String(billing.company ?? '').trim() || null,
  };
  return { clean, issues };
}

// ---- src/lib/hubspot-schema.js ----
// HubSpot schema the sync needs. Created idempotently by scripts/hubspot-setup.mjs.

const PROPERTY_GROUP = { name: 'woocommerce', label: 'WooCommerce', displayOrder: -1 };

const base = { groupName: PROPERTY_GROUP.name };
const text = (name, label, extra = {}) => ({ ...base, name, label, type: 'string', fieldType: 'text', ...extra });
const number = (name, label) => ({ ...base, name, label, type: 'number', fieldType: 'number' });
const date = (name, label) => ({ ...base, name, label, type: 'date', fieldType: 'date' });
const select = (name, label, values) => ({
  ...base, name, label, type: 'enumeration', fieldType: 'select',
  options: values.map(([value, optionLabel], displayOrder) => ({ value, label: optionLabel, displayOrder })),
});
const uniqueId = (name, label) => text(name, label, { hasUniqueValue: true });

const PROPERTIES = {
  contacts: [
    text('woo_customer_id', 'Woo customer ID'),
    number('total_orders', 'Total orders (paid)'),
    number('total_revenue', 'Total revenue (net of refunds)'),
    date('first_order_date', 'First order date'),
    date('last_order_date', 'Last order date'),
    select('customer_segment', 'Customer segment', [['new', 'New'], ['repeat', 'Repeat'], ['vip', 'VIP']]),
    select('data_quality_status', 'Data quality status', [['ok', 'OK'], ['needs_review', 'Needs review']]),
    text('data_quality_issues', 'Data quality issues', { type: 'string', fieldType: 'textarea' }),
  ],
  deals: [
    uniqueId('woo_order_id', 'Woo order ID'),
    number('refund_amount', 'Refund amount'),
    text('woo_status', 'Woo order status'),
  ],
  // HubSpot does not support unique-value properties on products (and does not document them for line
  // items), so these two are looked up by search and then updated or created — see sync-plan.js.
  products: [text('woo_product_id', 'Woo product ID')],
  line_items: [text('woo_line_item_id', 'Woo line item ID')],
  // One ticket per distinct sync problem, so re-running the backfill never duplicates tickets.
  tickets: [uniqueId('sync_error_key', 'Sync error key')],
};

const stage = (key, label, displayOrder, metadata) => ({ key, label, displayOrder, metadata });

const DEAL_PIPELINE = {
  label: 'WooCommerce',
  displayOrder: 1,
  stages: [
    stage('pending_payment', 'Pending payment', 0, { probability: '0.2' }),
    stage('paid', 'Paid', 1, { probability: '0.9' }),
    stage('closedwon', 'Closed won', 2, { probability: '1.0' }),
    stage('closedlost', 'Closed lost', 3, { probability: '0.0' }),
    stage('refunded', 'Refunded', 4, { probability: '0.0' }),
  ],
};

const TICKET_PIPELINE = {
  label: 'Integration errors',
  displayOrder: 1,
  stages: [
    stage('new', 'New', 0, { ticketState: 'OPEN' }),
    stage('resolved', 'Resolved', 1, { ticketState: 'CLOSED' }),
  ],
};

// ---- src/lib/retry.js ----
// Retry policy for HubSpot calls (flow F4). Ceiling: 100 requests / 10 s, batches of ≤100.

const MAX_ATTEMPTS = 3;

// 429 = rate limit, 423 = HubSpot's "Locked" during high sync volume, 5xx = transient server errors.
function shouldRetry(status) {
  return status === 429 || status === 423 || (status >= 500 && status <= 599);
}

// Exponential (1 s, 2 s, 4 s…), but never shorter than what the error needs: a 429 without Retry-After
// waits out the whole 10 s rate window; a 423 waits at least 2 s (HubSpot's guidance).
function backoffDelayMs(attempt, retryAfterHeader, status) {
  const retryAfter = Number(retryAfterHeader);
  if (retryAfterHeader != null && Number.isFinite(retryAfter) && retryAfter > 0) return retryAfter * 1000;
  const exponential = 1000 * 2 ** (attempt - 1);
  if (status === 429) return Math.max(exponential, 10000);
  if (status === 423) return Math.max(exponential, 2000);
  return exponential;
}

function chunk(items, size) {
  const out = [];
  for (let i = 0; i < items.length; i += size) out.push(items.slice(i, i + size));
  return out;
}

// ---- src/lib/mapping.js ----
// WooCommerce order → HubSpot CRM inputs. Pure functions, inlined into n8n Code nodes.

// Woo status → internal stage key. Real HubSpot stage ids come from hubspot-setup (.hubspot-ids.json).
const STAGE_BY_STATUS = {
  pending: 'pending_payment',
  'on-hold': 'pending_payment',
  processing: 'paid',
  completed: 'closedwon',
  cancelled: 'closedlost',
  failed: 'closedlost',
  refunded: 'refunded',
};

const PAID_STATUSES = new Set(['processing', 'completed']);

const FREE_EMAIL_DOMAINS = new Set([
  'gmail.com', 'googlemail.com', 'hotmail.com', 'outlook.com', 'live.com', 'yahoo.com', 'yahoo.com.ar',
  'icloud.com', 'aol.com', 'proton.me', 'protonmail.com',
]);

const money = (n) => (Math.round(n * 100) / 100).toFixed(2);

function refundTotal(order) {
  return (order.refunds ?? []).reduce((sum, r) => sum + Math.abs(Number(r.total) || 0), 0);
}

function netTotal(order) {
  return Math.max(0, Number(order.total) - refundTotal(order));
}

const isoUtc = (wooGmtDate) => new Date(`${wooGmtDate}Z`).toISOString();

function companyDomain(email) {
  const { value } = validateEmail(email);
  if (!value) return null;
  const domain = value.split('@')[1];
  return FREE_EMAIL_DOMAINS.has(domain) ? null : domain;
}

function planCompanies(orders) {
  const byDomain = new Map();
  for (const order of orders) {
    const domain = companyDomain(order.billing?.email);
    if (!domain) continue;
    const name = String(order.billing?.company ?? '').trim();
    const existing = byDomain.get(domain);
    if (!existing || (existing.name === domain && name)) byDomain.set(domain, { domain, name: name || domain });
  }
  return [...byDomain.values()];
}

function buildContactInput(order) {
  const { clean, issues } = validateCustomer(order.billing);
  const properties = {};
  for (const [key, value] of Object.entries(clean)) if (value) properties[key] = value;
  if (Number(order.customer_id) > 0) properties.woo_customer_id = String(order.customer_id);
  properties.data_quality_status = issues.length ? 'needs_review' : 'ok';
  properties.data_quality_issues = issues.join('; ');
  return { email: clean.email, properties, issues };
}

function buildProductInputs(orders) {
  const byId = new Map();
  for (const order of orders) {
    for (const item of order.line_items ?? []) {
      const id = String(item.product_id);
      if (byId.has(id)) continue;
      byId.set(id, {
        idProperty: 'woo_product_id',
        id,
        properties: { woo_product_id: id, name: item.name, price: money(Number(item.price)), hs_sku: item.sku || undefined },
      });
    }
  }
  return [...byId.values()];
}

function buildDealInput(order, { pipelineId, stageIds }) {
  const stageKey = STAGE_BY_STATUS[order.status];
  if (!stageKey) throw new Error(`Unknown Woo status "${order.status}" on order ${order.id}`);
  const id = String(order.id);
  const name = [order.billing?.first_name, order.billing?.last_name].filter(Boolean).join(' ').trim();
  return {
    idProperty: 'woo_order_id',
    id,
    properties: {
      woo_order_id: id,
      dealname: `Woo #${order.number ?? id}${name ? ` — ${name}` : ''}`,
      pipeline: pipelineId,
      dealstage: stageIds[stageKey],
      amount: order.status === 'refunded' ? money(0) : money(netTotal(order)),
      refund_amount: money(refundTotal(order)),
      closedate: isoUtc(order.date_created_gmt),
      woo_status: order.status,
      deal_currency_code: order.currency,
    },
  };
}

function buildLineItemInputs(order) {
  return (order.line_items ?? []).map((item) => {
    const id = String(item.id);
    return {
      idProperty: 'woo_line_item_id',
      id,
      wooProductId: String(item.product_id),
      properties: {
        woo_line_item_id: id,
        name: item.name,
        quantity: String(item.quantity),
        price: money(Number(item.price)),
        hs_sku: item.sku || undefined,
      },
    };
  });
}

function aggregateCustomer(orders) {
  const paid = orders.filter((o) => PAID_STATUSES.has(o.status));
  const dates = paid.map((o) => o.date_created_gmt.slice(0, 10)).sort();
  return {
    total_orders: paid.length,
    total_revenue: Math.round(paid.reduce((s, o) => s + netTotal(o), 0) * 100) / 100,
    first_order_date: dates[0] ?? null,
    last_order_date: dates.at(-1) ?? null,
  };
}

// ---- src/lib/sync-plan.js ----
// Turns a batch of Woo orders into the ordered list of HubSpot requests the sync-orders workflow makes.
// Every function returns plain request objects { method, path, body, label } — or { skip: true, label }
// when there is nothing to send — so the n8n flow stays linear and every step is unit-tested here.



const BATCH = 100;
const skip = (label) => ({ skip: true, label });
const post = (path, body, label) => ({ method: 'POST', path, body, label });
// Batch writes tolerate 4xx: HubSpot rejects a whole batch for one bad record, and that must become a
// ticket naming the records, not abort the other 99 orders. `ids` lets the ticket say which records.
const batches = (path, inputs, label, idOf = (i) => i.id) =>
  (inputs.length
    ? chunk(inputs, BATCH).map((part, i) => ({
      ...post(path, { inputs: part }, `${label} ${i + 1}`), tolerateClientError: true, ids: part.map(idOf).map(String),
    }))
    : [skip(label)]);
const lower = (s) => String(s ?? '').trim().toLowerCase();

/** Searches `objectType` for records whose `property` is any of `values` (≤100 values per search). */
function searchIn(objectType, property, values, label) {
  const unique = [...new Set(values.map(String))];
  if (!unique.length) return [skip(label)];
  return chunk(unique, BATCH).map((part, i) => post(`/crm/v3/objects/${objectType}/search`, {
    filterGroups: [{ filters: [{ propertyName: property, operator: 'IN', values: part }] }],
    properties: [property],
    limit: BATCH,
  }, `${label} ${i + 1}`));
}

/** For objects HubSpot cannot upsert by our key: update what the search found, create the rest. */
function updateOrCreate(objectType, key, items, found, label) {
  const updates = [];
  const creates = [];
  for (const properties of items) {
    const id = found.get(lower(properties[key]));
    if (id) updates.push({ id, properties });
    else creates.push({ properties });
  }
  const idOf = (i) => i.properties[key];
  const requests = [
    ...(updates.length ? batches(`/crm/v3/objects/${objectType}/batch/update`, updates, `${label} update`, idOf) : []),
    ...(creates.length ? batches(`/crm/v3/objects/${objectType}/batch/create`, creates, `${label} create`, idOf) : []),
  ];
  return requests.length ? requests : [skip(label)];
}

function pipelineContext(dealPipelines, ticketPipelines) {
  const find = (list, def) => {
    const p = (list?.results ?? []).find((x) => x.label === def.label);
    if (!p) throw new Error(`HubSpot pipeline "${def.label}" not found — run scripts/hubspot-setup.mjs first`);
    const ids = {};
    for (const s of def.stages) {
      const stage = p.stages.find((x) => x.label === s.label);
      if (!stage) throw new Error(`Stage "${s.label}" missing in pipeline "${def.label}" — run scripts/hubspot-setup.mjs`);
      ids[s.key] = stage.id;
    }
    return { id: p.id, ids };
  };
  const deals = find(dealPipelines, DEAL_PIPELINE);
  const tickets = find(ticketPipelines, TICKET_PIPELINE);
  return { pipelineId: deals.id, stageIds: deals.ids, ticketPipelineId: tickets.id, ticketStageNewId: tickets.ids.new };
}

function contactRequests(orders, history) {
  const byEmail = new Map();
  for (const order of orders) {
    const contact = buildContactInput(order);
    if (contact.email) byEmail.set(contact.email, contact);
  }
  const inputs = [...byEmail.values()].map(({ email, properties }) => {
    const agg = aggregateCustomer(history.filter((o) => lower(o.billing?.email) === email));
    const extra = Object.fromEntries(Object.entries(agg).filter(([, v]) => v !== null));
    return { idProperty: 'email', id: email, properties: { ...properties, ...extra } };
  });
  return batches('/crm/v3/objects/contacts/batch/upsert', inputs, 'contacts');
}

function companySearchRequest(orders) {
  const domains = planCompanies(orders).map((c) => c.domain);
  if (!domains.length) return skip('company search');
  return post('/crm/v3/objects/companies/search', {
    filterGroups: [{ filters: [{ propertyName: 'domain', operator: 'IN', values: domains }] }],
    properties: ['domain', 'name'],
    limit: BATCH,
  }, 'company search');
}

function companyCreateRequest(orders, searchResponse) {
  const found = idMap([searchResponse], 'domain');
  const inputs = planCompanies(orders)
    .filter((c) => !found.has(c.domain))
    .map((c) => ({ properties: { domain: c.domain, name: c.name } }));
  return inputs.length
    ? batches('/crm/v3/objects/companies/batch/create', inputs, 'company create', (i) => i.properties.domain)[0]
    : skip('company create');
}

const productSearchRequests = (orders) =>
  searchIn('products', 'woo_product_id', buildProductInputs(orders).map((p) => p.id), 'product search');

const productWriteRequests = (orders, searchResponses) => updateOrCreate(
  'products', 'woo_product_id', buildProductInputs(orders).map((p) => p.properties),
  idMap(searchResponses, 'woo_product_id'), 'products',
);

function dealRequests(orders, ctx) {
  const inputs = [];
  const problems = [];
  for (const order of orders) {
    try {
      inputs.push(buildDealInput(order, ctx));
    } catch (err) {
      problems.push({
        key: `unknown-status:${order.id}`,
        subject: `Woo order #${order.number ?? order.id} not synced: unknown status`,
        content: err.message,
        priority: 'HIGH',
      });
    }
  }
  return { requests: batches('/crm/v3/objects/deals/batch/upsert', inputs, 'deals'), problems };
}

const lineItemSearchRequests = (orders) =>
  searchIn('line_items', 'woo_line_item_id', orders.flatMap(buildLineItemInputs).map((li) => li.id), 'line item search');

function lineItemWriteRequests(orders, productIds, searchResponses) {
  const items = orders.flatMap(buildLineItemInputs).map(({ wooProductId, properties }) => {
    const hsProductId = productIds.get(wooProductId);
    return hsProductId ? { ...properties, hs_product_id: hsProductId } : properties;
  });
  return updateOrCreate('line_items', 'woo_line_item_id', items, idMap(searchResponses, 'woo_line_item_id'), 'line items');
}

/** value of `property` (lowercased) → HubSpot record id, from any number of batch/search responses. */
function idMap(responses, property) {
  const map = new Map();
  for (const r of responses) {
    for (const rec of r?.body?.results ?? []) {
      const value = rec.properties?.[property];
      if (value != null) map.set(lower(value), String(rec.id));
    }
  }
  return map;
}

function associationRequests({ orders, contactIds, companyIds, dealIds, lineItemIds }) {
  const pairs = { 'contacts/companies': new Map(), 'deals/contacts': new Map(), 'deals/companies': new Map(), 'line_items/deals': new Map() };
  const add = (kind, from, to) => { if (from && to) pairs[kind].set(`${from}>${to}`, { from: { id: from }, to: { id: to } }); };
  for (const order of orders) {
    const email = lower(order.billing?.email);
    const contactId = contactIds.get(email);
    const companyId = companyIds.get(companyDomain(email) ?? '');
    const dealId = dealIds.get(String(order.id));
    add('contacts/companies', contactId, companyId);
    add('deals/contacts', dealId, contactId);
    add('deals/companies', dealId, companyId);
    for (const item of order.line_items ?? []) add('line_items/deals', lineItemIds.get(String(item.id)), dealId);
  }
  return Object.entries(pairs).map(([kind, map]) => (map.size
    ? { ...post(`/crm/v4/associations/${kind}/batch/associate/default`, { inputs: [...map.values()] }, `associate ${kind}`),
      tolerateClientError: true, ids: [...map.keys()] }
    : skip(`associate ${kind}`)));
}

function syncProblems(orders, responses, extra = []) {
  const problems = [];
  for (const order of orders) {
    const contact = buildContactInput(order);
    if (!contact.email) {
      problems.push({
        key: `no-contact:${order.id}`,
        subject: `Woo order #${order.number ?? order.id} synced without a contact`,
        content: `Billing email "${order.billing?.email ?? ''}" was rejected (${contact.issues.join('; ')}). `
          + 'The deal was synced; fix the email in WooCommerce and save the order to link a contact.',
        priority: 'MEDIUM',
      });
    }
  }
  for (const r of responses) {
    if (r && r.ok === false) {
      const ids = r.ids ?? [];
      problems.push({
        key: `batch-failed:${String(r.label).replace(/ \d+$/, '')}:${ids[0] ?? 'none'}..${ids.at(-1) ?? 'none'}`,
        subject: `HubSpot rejected a whole ${r.label} batch (${ids.length} records)`,
        content: `HTTP ${r.status} ${r.body?.category ?? ''}: ${r.body?.message ?? JSON.stringify(r.body ?? '')}
`
          + `Records: ${ids.join(', ')}`.slice(0, 1800),
        priority: 'HIGH',
      });
      continue;
    }
    for (const e of r?.body?.errors ?? []) {
      for (const id of e.context?.ids ?? ['unknown']) {
        problems.push({
          key: `batch:${String(r.label).replace(/ \d+$/, '')}:${id}`,
          subject: `HubSpot rejected ${r.label} record ${id}`,
          content: `${e.category ?? 'ERROR'}: ${e.message ?? ''}`.slice(0, 2000),
          priority: 'HIGH',
        });
      }
    }
  }
  return [...problems, ...extra];
}

function ticketReadRequest(problems) {
  if (!problems.length) return skip('ticket lookup');
  return searchIn('tickets', 'sync_error_key', problems.slice(0, BATCH).map((p) => p.key), 'ticket lookup')[0];
}

function ticketCreateRequest(problems, readResponse, ctx) {
  const existing = idMap([readResponse], 'sync_error_key');
  const inputs = problems.slice(0, BATCH)
    .filter((p) => !existing.has(lower(p.key)))
    .map((p) => ({
      properties: {
        sync_error_key: p.key,
        subject: p.subject,
        content: p.content,
        hs_pipeline: ctx.ticketPipelineId,
        hs_pipeline_stage: ctx.ticketStageNewId,
        hs_ticket_priority: p.priority,
      },
    }));
  return inputs.length
    ? batches('/crm/v3/objects/tickets/batch/create', inputs, 'tickets', (i) => i.properties.sync_error_key)[0]
    : skip('tickets');
}

// ---- step ----
const input = $('Sync in').first().json;
const orders = input.orders;
const history = input.history ?? orders;
const responses = (node) => $(node).all().map((item) => item.json);
const ctx = () => { const [deals, tickets] = responses('Get pipelines'); return pipelineContext(deals.body, tickets.body); };
const out = (requests) => [].concat(requests).map((json) => ({ json }));
const written = ['Upsert contacts', 'Create companies', 'Upsert products', 'Upsert deals', 'Upsert line items', 'Associate']
  .flatMap(responses);
const problems = syncProblems(orders, written, dealRequests(orders, ctx()).problems);
return out(ticketReadRequest(problems));

// ---- src/lib/validate.js ----
// Data-quality checks (flow F3). Pure functions: inlined into n8n Code nodes by build-workflows.
// Rule: never block the sync. Invalid values become null and are reported as issues.

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[a-z]{2,}$/;

const DISPOSABLE_DOMAINS = new Set([
  'mailinator.com', '10minutemail.com', 'guerrillamail.com', 'yopmail.com', 'tempmail.com',
]);

// Common typos of webmail domains → correct domain.
const DOMAIN_TYPOS = {
  'gmial.com': 'gmail.com', 'gmal.com': 'gmail.com', 'gnail.com': 'gmail.com', 'gmail.con': 'gmail.com',
  'gmial.con': 'gmail.com', 'gmail.cmo': 'gmail.com',
  'hotmial.com': 'hotmail.com', 'hotmal.com': 'hotmail.com', 'hotmail.con': 'hotmail.com',
  'yaho.com': 'yahoo.com', 'yahoo.con': 'yahoo.com', 'outlok.com': 'outlook.com',
};

const DIAL_CODES = {
  AR: '54', US: '1', MX: '52', ES: '34', CL: '56', UY: '598', BR: '55', CO: '57', PE: '51', GB: '44', DE: '49',
};

const COUNTRY_NAMES = {
  argentina: 'AR',
  'united states': 'US', usa: 'US', 'estados unidos': 'US', eeuu: 'US',
  mexico: 'MX', 'méxico': 'MX',
  spain: 'ES', 'españa': 'ES', espana: 'ES',
  chile: 'CL', uruguay: 'UY',
  brazil: 'BR', brasil: 'BR',
  colombia: 'CO', peru: 'PE', 'perú': 'PE',
  'united kingdom': 'GB', uk: 'GB', 'reino unido': 'GB',
  germany: 'DE', alemania: 'DE',
};

function validateEmail(raw) {
  const email = String(raw ?? '').trim().toLowerCase();
  if (!EMAIL_RE.test(email)) return { value: null, issue: 'email_invalid_format' };
  const [local, domain] = email.split('@');
  // Dot errors pass the simple pattern but HubSpot rejects them (and one bad email would fail a whole batch).
  if (/^\.|\.$|\.\./.test(local) || domain.split('.').some((label) => !label)) {
    return { value: null, issue: 'email_invalid_format' };
  }
  if (DOMAIN_TYPOS[domain]) return { value: null, issue: `email_typo_domain:${domain}→${DOMAIN_TYPOS[domain]}` };
  if (DISPOSABLE_DOMAINS.has(domain)) return { value: null, issue: 'email_disposable' };
  return { value: email, issue: null };
}

function normalizePhone(raw, countryIso2) {
  const text = String(raw ?? '').trim();
  if (!text) return { value: null, issue: null };
  const invalid = { value: null, issue: 'phone_invalid' };
  const digits = text.replace(/\D/g, '');
  if (/[a-z]/i.test(text) || !digits) return invalid;

  let e164;
  if (text.startsWith('+')) {
    e164 = digits;
  } else {
    const dial = DIAL_CODES[countryIso2] ?? DIAL_CODES.AR;
    let national = digits;
    if (national.startsWith(dial) && national.length > 10) national = national.slice(dial.length);
    national = national.replace(/^0/, ''); // trunk prefix (AR, ES, GB, DE…)
    if (national.length < 6) return invalid;
    e164 = dial + national;
  }
  if (e164.length < 8 || e164.length > 15) return invalid;
  return { value: `+${e164}`, issue: null };
}

function normalizeCountry(raw) {
  const text = String(raw ?? '').trim();
  if (!text) return { value: null, issue: null };
  const upper = text.toUpperCase();
  if (DIAL_CODES[upper]) return { value: upper, issue: null };
  const byName = COUNTRY_NAMES[text.toLowerCase()];
  return byName ? { value: byName, issue: null } : { value: null, issue: 'country_unknown' };
}

function validateCustomer(billing = {}) {
  const issues = [];
  const take = (result) => {
    if (result.issue) issues.push(result.issue);
    return result.value;
  };
  const email = take(validateEmail(billing.email));
  const country = take(normalizeCountry(billing.country));
  const phone = take(normalizePhone(billing.phone, country));
  const clean = {
    email,
    phone,
    country,
    firstname: String(billing.first_name ?? '').trim() || null,
    lastname: String(billing.last_name ?? '').trim() || null,
    company: String(billing.company ?? '').trim() || null,
  };
  return { clean, issues };
}

// ---- src/lib/hubspot-schema.js ----
// HubSpot schema the sync needs. Created idempotently by scripts/hubspot-setup.mjs.

const PROPERTY_GROUP = { name: 'woocommerce', label: 'WooCommerce', displayOrder: -1 };

const base = { groupName: PROPERTY_GROUP.name };
const text = (name, label, extra = {}) => ({ ...base, name, label, type: 'string', fieldType: 'text', ...extra });
const number = (name, label) => ({ ...base, name, label, type: 'number', fieldType: 'number' });
const date = (name, label) => ({ ...base, name, label, type: 'date', fieldType: 'date' });
const select = (name, label, values) => ({
  ...base, name, label, type: 'enumeration', fieldType: 'select',
  options: values.map(([value, optionLabel], displayOrder) => ({ value, label: optionLabel, displayOrder })),
});
const uniqueId = (name, label) => text(name, label, { hasUniqueValue: true });

const PROPERTIES = {
  contacts: [
    text('woo_customer_id', 'Woo customer ID'),
    number('total_orders', 'Total orders (paid)'),
    number('total_revenue', 'Total revenue (net of refunds)'),
    date('first_order_date', 'First order date'),
    date('last_order_date', 'Last order date'),
    select('customer_segment', 'Customer segment', [['new', 'New'], ['repeat', 'Repeat'], ['vip', 'VIP']]),
    select('data_quality_status', 'Data quality status', [['ok', 'OK'], ['needs_review', 'Needs review']]),
    text('data_quality_issues', 'Data quality issues', { type: 'string', fieldType: 'textarea' }),
  ],
  deals: [
    uniqueId('woo_order_id', 'Woo order ID'),
    number('refund_amount', 'Refund amount'),
    text('woo_status', 'Woo order status'),
  ],
  // HubSpot does not support unique-value properties on products (and does not document them for line
  // items), so these two are looked up by search and then updated or created — see sync-plan.js.
  products: [text('woo_product_id', 'Woo product ID')],
  line_items: [text('woo_line_item_id', 'Woo line item ID')],
  // One ticket per distinct sync problem, so re-running the backfill never duplicates tickets.
  tickets: [uniqueId('sync_error_key', 'Sync error key')],
};

const stage = (key, label, displayOrder, metadata) => ({ key, label, displayOrder, metadata });

const DEAL_PIPELINE = {
  label: 'WooCommerce',
  displayOrder: 1,
  stages: [
    stage('pending_payment', 'Pending payment', 0, { probability: '0.2' }),
    stage('paid', 'Paid', 1, { probability: '0.9' }),
    stage('closedwon', 'Closed won', 2, { probability: '1.0' }),
    stage('closedlost', 'Closed lost', 3, { probability: '0.0' }),
    stage('refunded', 'Refunded', 4, { probability: '0.0' }),
  ],
};

const TICKET_PIPELINE = {
  label: 'Integration errors',
  displayOrder: 1,
  stages: [
    stage('new', 'New', 0, { ticketState: 'OPEN' }),
    stage('resolved', 'Resolved', 1, { ticketState: 'CLOSED' }),
  ],
};

// ---- src/lib/retry.js ----
// Retry policy for HubSpot calls (flow F4). Ceiling: 100 requests / 10 s, batches of ≤100.

const MAX_ATTEMPTS = 3;

// 429 = rate limit, 423 = HubSpot's "Locked" during high sync volume, 5xx = transient server errors.
function shouldRetry(status) {
  return status === 429 || status === 423 || (status >= 500 && status <= 599);
}

// Exponential (1 s, 2 s, 4 s…), but never shorter than what the error needs: a 429 without Retry-After
// waits out the whole 10 s rate window; a 423 waits at least 2 s (HubSpot's guidance).
function backoffDelayMs(attempt, retryAfterHeader, status) {
  const retryAfter = Number(retryAfterHeader);
  if (retryAfterHeader != null && Number.isFinite(retryAfter) && retryAfter > 0) return retryAfter * 1000;
  const exponential = 1000 * 2 ** (attempt - 1);
  if (status === 429) return Math.max(exponential, 10000);
  if (status === 423) return Math.max(exponential, 2000);
  return exponential;
}

function chunk(items, size) {
  const out = [];
  for (let i = 0; i < items.length; i += size) out.push(items.slice(i, i + size));
  return out;
}

// ---- src/lib/mapping.js ----
// WooCommerce order → HubSpot CRM inputs. Pure functions, inlined into n8n Code nodes.

// Woo status → internal stage key. Real HubSpot stage ids come from hubspot-setup (.hubspot-ids.json).
const STAGE_BY_STATUS = {
  pending: 'pending_payment',
  'on-hold': 'pending_payment',
  processing: 'paid',
  completed: 'closedwon',
  cancelled: 'closedlost',
  failed: 'closedlost',
  refunded: 'refunded',
};

const PAID_STATUSES = new Set(['processing', 'completed']);

const FREE_EMAIL_DOMAINS = new Set([
  'gmail.com', 'googlemail.com', 'hotmail.com', 'outlook.com', 'live.com', 'yahoo.com', 'yahoo.com.ar',
  'icloud.com', 'aol.com', 'proton.me', 'protonmail.com',
]);

const money = (n) => (Math.round(n * 100) / 100).toFixed(2);

function refundTotal(order) {
  return (order.refunds ?? []).reduce((sum, r) => sum + Math.abs(Number(r.total) || 0), 0);
}

function netTotal(order) {
  return Math.max(0, Number(order.total) - refundTotal(order));
}

const isoUtc = (wooGmtDate) => new Date(`${wooGmtDate}Z`).toISOString();

function companyDomain(email) {
  const { value } = validateEmail(email);
  if (!value) return null;
  const domain = value.split('@')[1];
  return FREE_EMAIL_DOMAINS.has(domain) ? null : domain;
}

function planCompanies(orders) {
  const byDomain = new Map();
  for (const order of orders) {
    const domain = companyDomain(order.billing?.email);
    if (!domain) continue;
    const name = String(order.billing?.company ?? '').trim();
    const existing = byDomain.get(domain);
    if (!existing || (existing.name === domain && name)) byDomain.set(domain, { domain, name: name || domain });
  }
  return [...byDomain.values()];
}

function buildContactInput(order) {
  const { clean, issues } = validateCustomer(order.billing);
  const properties = {};
  for (const [key, value] of Object.entries(clean)) if (value) properties[key] = value;
  if (Number(order.customer_id) > 0) properties.woo_customer_id = String(order.customer_id);
  properties.data_quality_status = issues.length ? 'needs_review' : 'ok';
  properties.data_quality_issues = issues.join('; ');
  return { email: clean.email, properties, issues };
}

function buildProductInputs(orders) {
  const byId = new Map();
  for (const order of orders) {
    for (const item of order.line_items ?? []) {
      const id = String(item.product_id);
      if (byId.has(id)) continue;
      byId.set(id, {
        idProperty: 'woo_product_id',
        id,
        properties: { woo_product_id: id, name: item.name, price: money(Number(item.price)), hs_sku: item.sku || undefined },
      });
    }
  }
  return [...byId.values()];
}

function buildDealInput(order, { pipelineId, stageIds }) {
  const stageKey = STAGE_BY_STATUS[order.status];
  if (!stageKey) throw new Error(`Unknown Woo status "${order.status}" on order ${order.id}`);
  const id = String(order.id);
  const name = [order.billing?.first_name, order.billing?.last_name].filter(Boolean).join(' ').trim();
  return {
    idProperty: 'woo_order_id',
    id,
    properties: {
      woo_order_id: id,
      dealname: `Woo #${order.number ?? id}${name ? ` — ${name}` : ''}`,
      pipeline: pipelineId,
      dealstage: stageIds[stageKey],
      amount: order.status === 'refunded' ? money(0) : money(netTotal(order)),
      refund_amount: money(refundTotal(order)),
      closedate: isoUtc(order.date_created_gmt),
      woo_status: order.status,
      deal_currency_code: order.currency,
    },
  };
}

function buildLineItemInputs(order) {
  return (order.line_items ?? []).map((item) => {
    const id = String(item.id);
    return {
      idProperty: 'woo_line_item_id',
      id,
      wooProductId: String(item.product_id),
      properties: {
        woo_line_item_id: id,
        name: item.name,
        quantity: String(item.quantity),
        price: money(Number(item.price)),
        hs_sku: item.sku || undefined,
      },
    };
  });
}

function aggregateCustomer(orders) {
  const paid = orders.filter((o) => PAID_STATUSES.has(o.status));
  const dates = paid.map((o) => o.date_created_gmt.slice(0, 10)).sort();
  return {
    total_orders: paid.length,
    total_revenue: Math.round(paid.reduce((s, o) => s + netTotal(o), 0) * 100) / 100,
    first_order_date: dates[0] ?? null,
    last_order_date: dates.at(-1) ?? null,
  };
}

// ---- src/lib/sync-plan.js ----
// Turns a batch of Woo orders into the ordered list of HubSpot requests the sync-orders workflow makes.
// Every function returns plain request objects { method, path, body, label } — or { skip: true, label }
// when there is nothing to send — so the n8n flow stays linear and every step is unit-tested here.



const BATCH = 100;
const skip = (label) => ({ skip: true, label });
const post = (path, body, label) => ({ method: 'POST', path, body, label });
// Batch writes tolerate 4xx: HubSpot rejects a whole batch for one bad record, and that must become a
// ticket naming the records, not abort the other 99 orders. `ids` lets the ticket say which records.
const batches = (path, inputs, label, idOf = (i) => i.id) =>
  (inputs.length
    ? chunk(inputs, BATCH).map((part, i) => ({
      ...post(path, { inputs: part }, `${label} ${i + 1}`), tolerateClientError: true, ids: part.map(idOf).map(String),
    }))
    : [skip(label)]);
const lower = (s) => String(s ?? '').trim().toLowerCase();

/** Searches `objectType` for records whose `property` is any of `values` (≤100 values per search). */
function searchIn(objectType, property, values, label) {
  const unique = [...new Set(values.map(String))];
  if (!unique.length) return [skip(label)];
  return chunk(unique, BATCH).map((part, i) => post(`/crm/v3/objects/${objectType}/search`, {
    filterGroups: [{ filters: [{ propertyName: property, operator: 'IN', values: part }] }],
    properties: [property],
    limit: BATCH,
  }, `${label} ${i + 1}`));
}

/** For objects HubSpot cannot upsert by our key: update what the search found, create the rest. */
function updateOrCreate(objectType, key, items, found, label) {
  const updates = [];
  const creates = [];
  for (const properties of items) {
    const id = found.get(lower(properties[key]));
    if (id) updates.push({ id, properties });
    else creates.push({ properties });
  }
  const idOf = (i) => i.properties[key];
  const requests = [
    ...(updates.length ? batches(`/crm/v3/objects/${objectType}/batch/update`, updates, `${label} update`, idOf) : []),
    ...(creates.length ? batches(`/crm/v3/objects/${objectType}/batch/create`, creates, `${label} create`, idOf) : []),
  ];
  return requests.length ? requests : [skip(label)];
}

function pipelineContext(dealPipelines, ticketPipelines) {
  const find = (list, def) => {
    const p = (list?.results ?? []).find((x) => x.label === def.label);
    if (!p) throw new Error(`HubSpot pipeline "${def.label}" not found — run scripts/hubspot-setup.mjs first`);
    const ids = {};
    for (const s of def.stages) {
      const stage = p.stages.find((x) => x.label === s.label);
      if (!stage) throw new Error(`Stage "${s.label}" missing in pipeline "${def.label}" — run scripts/hubspot-setup.mjs`);
      ids[s.key] = stage.id;
    }
    return { id: p.id, ids };
  };
  const deals = find(dealPipelines, DEAL_PIPELINE);
  const tickets = find(ticketPipelines, TICKET_PIPELINE);
  return { pipelineId: deals.id, stageIds: deals.ids, ticketPipelineId: tickets.id, ticketStageNewId: tickets.ids.new };
}

function contactRequests(orders, history) {
  const byEmail = new Map();
  for (const order of orders) {
    const contact = buildContactInput(order);
    if (contact.email) byEmail.set(contact.email, contact);
  }
  const inputs = [...byEmail.values()].map(({ email, properties }) => {
    const agg = aggregateCustomer(history.filter((o) => lower(o.billing?.email) === email));
    const extra = Object.fromEntries(Object.entries(agg).filter(([, v]) => v !== null));
    return { idProperty: 'email', id: email, properties: { ...properties, ...extra } };
  });
  return batches('/crm/v3/objects/contacts/batch/upsert', inputs, 'contacts');
}

function companySearchRequest(orders) {
  const domains = planCompanies(orders).map((c) => c.domain);
  if (!domains.length) return skip('company search');
  return post('/crm/v3/objects/companies/search', {
    filterGroups: [{ filters: [{ propertyName: 'domain', operator: 'IN', values: domains }] }],
    properties: ['domain', 'name'],
    limit: BATCH,
  }, 'company search');
}

function companyCreateRequest(orders, searchResponse) {
  const found = idMap([searchResponse], 'domain');
  const inputs = planCompanies(orders)
    .filter((c) => !found.has(c.domain))
    .map((c) => ({ properties: { domain: c.domain, name: c.name } }));
  return inputs.length
    ? batches('/crm/v3/objects/companies/batch/create', inputs, 'company create', (i) => i.properties.domain)[0]
    : skip('company create');
}

const productSearchRequests = (orders) =>
  searchIn('products', 'woo_product_id', buildProductInputs(orders).map((p) => p.id), 'product search');

const productWriteRequests = (orders, searchResponses) => updateOrCreate(
  'products', 'woo_product_id', buildProductInputs(orders).map((p) => p.properties),
  idMap(searchResponses, 'woo_product_id'), 'products',
);

function dealRequests(orders, ctx) {
  const inputs = [];
  const problems = [];
  for (const order of orders) {
    try {
      inputs.push(buildDealInput(order, ctx));
    } catch (err) {
      problems.push({
        key: `unknown-status:${order.id}`,
        subject: `Woo order #${order.number ?? order.id} not synced: unknown status`,
        content: err.message,
        priority: 'HIGH',
      });
    }
  }
  return { requests: batches('/crm/v3/objects/deals/batch/upsert', inputs, 'deals'), problems };
}

const lineItemSearchRequests = (orders) =>
  searchIn('line_items', 'woo_line_item_id', orders.flatMap(buildLineItemInputs).map((li) => li.id), 'line item search');

function lineItemWriteRequests(orders, productIds, searchResponses) {
  const items = orders.flatMap(buildLineItemInputs).map(({ wooProductId, properties }) => {
    const hsProductId = productIds.get(wooProductId);
    return hsProductId ? { ...properties, hs_product_id: hsProductId } : properties;
  });
  return updateOrCreate('line_items', 'woo_line_item_id', items, idMap(searchResponses, 'woo_line_item_id'), 'line items');
}

/** value of `property` (lowercased) → HubSpot record id, from any number of batch/search responses. */
function idMap(responses, property) {
  const map = new Map();
  for (const r of responses) {
    for (const rec of r?.body?.results ?? []) {
      const value = rec.properties?.[property];
      if (value != null) map.set(lower(value), String(rec.id));
    }
  }
  return map;
}

function associationRequests({ orders, contactIds, companyIds, dealIds, lineItemIds }) {
  const pairs = { 'contacts/companies': new Map(), 'deals/contacts': new Map(), 'deals/companies': new Map(), 'line_items/deals': new Map() };
  const add = (kind, from, to) => { if (from && to) pairs[kind].set(`${from}>${to}`, { from: { id: from }, to: { id: to } }); };
  for (const order of orders) {
    const email = lower(order.billing?.email);
    const contactId = contactIds.get(email);
    const companyId = companyIds.get(companyDomain(email) ?? '');
    const dealId = dealIds.get(String(order.id));
    add('contacts/companies', contactId, companyId);
    add('deals/contacts', dealId, contactId);
    add('deals/companies', dealId, companyId);
    for (const item of order.line_items ?? []) add('line_items/deals', lineItemIds.get(String(item.id)), dealId);
  }
  return Object.entries(pairs).map(([kind, map]) => (map.size
    ? { ...post(`/crm/v4/associations/${kind}/batch/associate/default`, { inputs: [...map.values()] }, `associate ${kind}`),
      tolerateClientError: true, ids: [...map.keys()] }
    : skip(`associate ${kind}`)));
}

function syncProblems(orders, responses, extra = []) {
  const problems = [];
  for (const order of orders) {
    const contact = buildContactInput(order);
    if (!contact.email) {
      problems.push({
        key: `no-contact:${order.id}`,
        subject: `Woo order #${order.number ?? order.id} synced without a contact`,
        content: `Billing email "${order.billing?.email ?? ''}" was rejected (${contact.issues.join('; ')}). `
          + 'The deal was synced; fix the email in WooCommerce and save the order to link a contact.',
        priority: 'MEDIUM',
      });
    }
  }
  for (const r of responses) {
    if (r && r.ok === false) {
      const ids = r.ids ?? [];
      problems.push({
        key: `batch-failed:${String(r.label).replace(/ \d+$/, '')}:${ids[0] ?? 'none'}..${ids.at(-1) ?? 'none'}`,
        subject: `HubSpot rejected a whole ${r.label} batch (${ids.length} records)`,
        content: `HTTP ${r.status} ${r.body?.category ?? ''}: ${r.body?.message ?? JSON.stringify(r.body ?? '')}
`
          + `Records: ${ids.join(', ')}`.slice(0, 1800),
        priority: 'HIGH',
      });
      continue;
    }
    for (const e of r?.body?.errors ?? []) {
      for (const id of e.context?.ids ?? ['unknown']) {
        problems.push({
          key: `batch:${String(r.label).replace(/ \d+$/, '')}:${id}`,
          subject: `HubSpot rejected ${r.label} record ${id}`,
          content: `${e.category ?? 'ERROR'}: ${e.message ?? ''}`.slice(0, 2000),
          priority: 'HIGH',
        });
      }
    }
  }
  return [...problems, ...extra];
}

function ticketReadRequest(problems) {
  if (!problems.length) return skip('ticket lookup');
  return searchIn('tickets', 'sync_error_key', problems.slice(0, BATCH).map((p) => p.key), 'ticket lookup')[0];
}

function ticketCreateRequest(problems, readResponse, ctx) {
  const existing = idMap([readResponse], 'sync_error_key');
  const inputs = problems.slice(0, BATCH)
    .filter((p) => !existing.has(lower(p.key)))
    .map((p) => ({
      properties: {
        sync_error_key: p.key,
        subject: p.subject,
        content: p.content,
        hs_pipeline: ctx.ticketPipelineId,
        hs_pipeline_stage: ctx.ticketStageNewId,
        hs_ticket_priority: p.priority,
      },
    }));
  return inputs.length
    ? batches('/crm/v3/objects/tickets/batch/create', inputs, 'tickets', (i) => i.properties.sync_error_key)[0]
    : skip('tickets');
}

// ---- step ----
const input = $('Sync in').first().json;
const orders = input.orders;
const history = input.history ?? orders;
const responses = (node) => $(node).all().map((item) => item.json);
const ctx = () => { const [deals, tickets] = responses('Get pipelines'); return pipelineContext(deals.body, tickets.body); };
const out = (requests) => [].concat(requests).map((json) => ({ json }));
const written = ['Upsert contacts', 'Create companies', 'Upsert products', 'Upsert deals', 'Upsert line items', 'Associate']
  .flatMap(responses);
const problems = syncProblems(orders, written, dealRequests(orders, ctx()).problems);
return out(ticketCreateRequest(problems, responses('Find tickets')[0], ctx()));

// ---- src/lib/validate.js ----
// Data-quality checks (flow F3). Pure functions: inlined into n8n Code nodes by build-workflows.
// Rule: never block the sync. Invalid values become null and are reported as issues.

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[a-z]{2,}$/;

const DISPOSABLE_DOMAINS = new Set([
  'mailinator.com', '10minutemail.com', 'guerrillamail.com', 'yopmail.com', 'tempmail.com',
]);

// Common typos of webmail domains → correct domain.
const DOMAIN_TYPOS = {
  'gmial.com': 'gmail.com', 'gmal.com': 'gmail.com', 'gnail.com': 'gmail.com', 'gmail.con': 'gmail.com',
  'gmial.con': 'gmail.com', 'gmail.cmo': 'gmail.com',
  'hotmial.com': 'hotmail.com', 'hotmal.com': 'hotmail.com', 'hotmail.con': 'hotmail.com',
  'yaho.com': 'yahoo.com', 'yahoo.con': 'yahoo.com', 'outlok.com': 'outlook.com',
};

const DIAL_CODES = {
  AR: '54', US: '1', MX: '52', ES: '34', CL: '56', UY: '598', BR: '55', CO: '57', PE: '51', GB: '44', DE: '49',
};

const COUNTRY_NAMES = {
  argentina: 'AR',
  'united states': 'US', usa: 'US', 'estados unidos': 'US', eeuu: 'US',
  mexico: 'MX', 'méxico': 'MX',
  spain: 'ES', 'españa': 'ES', espana: 'ES',
  chile: 'CL', uruguay: 'UY',
  brazil: 'BR', brasil: 'BR',
  colombia: 'CO', peru: 'PE', 'perú': 'PE',
  'united kingdom': 'GB', uk: 'GB', 'reino unido': 'GB',
  germany: 'DE', alemania: 'DE',
};

function validateEmail(raw) {
  const email = String(raw ?? '').trim().toLowerCase();
  if (!EMAIL_RE.test(email)) return { value: null, issue: 'email_invalid_format' };
  const [local, domain] = email.split('@');
  // Dot errors pass the simple pattern but HubSpot rejects them (and one bad email would fail a whole batch).
  if (/^\.|\.$|\.\./.test(local) || domain.split('.').some((label) => !label)) {
    return { value: null, issue: 'email_invalid_format' };
  }
  if (DOMAIN_TYPOS[domain]) return { value: null, issue: `email_typo_domain:${domain}→${DOMAIN_TYPOS[domain]}` };
  if (DISPOSABLE_DOMAINS.has(domain)) return { value: null, issue: 'email_disposable' };
  return { value: email, issue: null };
}

function normalizePhone(raw, countryIso2) {
  const text = String(raw ?? '').trim();
  if (!text) return { value: null, issue: null };
  const invalid = { value: null, issue: 'phone_invalid' };
  const digits = text.replace(/\D/g, '');
  if (/[a-z]/i.test(text) || !digits) return invalid;

  let e164;
  if (text.startsWith('+')) {
    e164 = digits;
  } else {
    const dial = DIAL_CODES[countryIso2] ?? DIAL_CODES.AR;
    let national = digits;
    if (national.startsWith(dial) && national.length > 10) national = national.slice(dial.length);
    national = national.replace(/^0/, ''); // trunk prefix (AR, ES, GB, DE…)
    if (national.length < 6) return invalid;
    e164 = dial + national;
  }
  if (e164.length < 8 || e164.length > 15) return invalid;
  return { value: `+${e164}`, issue: null };
}

function normalizeCountry(raw) {
  const text = String(raw ?? '').trim();
  if (!text) return { value: null, issue: null };
  const upper = text.toUpperCase();
  if (DIAL_CODES[upper]) return { value: upper, issue: null };
  const byName = COUNTRY_NAMES[text.toLowerCase()];
  return byName ? { value: byName, issue: null } : { value: null, issue: 'country_unknown' };
}

function validateCustomer(billing = {}) {
  const issues = [];
  const take = (result) => {
    if (result.issue) issues.push(result.issue);
    return result.value;
  };
  const email = take(validateEmail(billing.email));
  const country = take(normalizeCountry(billing.country));
  const phone = take(normalizePhone(billing.phone, country));
  const clean = {
    email,
    phone,
    country,
    firstname: String(billing.first_name ?? '').trim() || null,
    lastname: String(billing.last_name ?? '').trim() || null,
    company: String(billing.company ?? '').trim() || null,
  };
  return { clean, issues };
}

// ---- src/lib/hubspot-schema.js ----
// HubSpot schema the sync needs. Created idempotently by scripts/hubspot-setup.mjs.

const PROPERTY_GROUP = { name: 'woocommerce', label: 'WooCommerce', displayOrder: -1 };

const base = { groupName: PROPERTY_GROUP.name };
const text = (name, label, extra = {}) => ({ ...base, name, label, type: 'string', fieldType: 'text', ...extra });
const number = (name, label) => ({ ...base, name, label, type: 'number', fieldType: 'number' });
const date = (name, label) => ({ ...base, name, label, type: 'date', fieldType: 'date' });
const select = (name, label, values) => ({
  ...base, name, label, type: 'enumeration', fieldType: 'select',
  options: values.map(([value, optionLabel], displayOrder) => ({ value, label: optionLabel, displayOrder })),
});
const uniqueId = (name, label) => text(name, label, { hasUniqueValue: true });

const PROPERTIES = {
  contacts: [
    text('woo_customer_id', 'Woo customer ID'),
    number('total_orders', 'Total orders (paid)'),
    number('total_revenue', 'Total revenue (net of refunds)'),
    date('first_order_date', 'First order date'),
    date('last_order_date', 'Last order date'),
    select('customer_segment', 'Customer segment', [['new', 'New'], ['repeat', 'Repeat'], ['vip', 'VIP']]),
    select('data_quality_status', 'Data quality status', [['ok', 'OK'], ['needs_review', 'Needs review']]),
    text('data_quality_issues', 'Data quality issues', { type: 'string', fieldType: 'textarea' }),
  ],
  deals: [
    uniqueId('woo_order_id', 'Woo order ID'),
    number('refund_amount', 'Refund amount'),
    text('woo_status', 'Woo order status'),
  ],
  // HubSpot does not support unique-value properties on products (and does not document them for line
  // items), so these two are looked up by search and then updated or created — see sync-plan.js.
  products: [text('woo_product_id', 'Woo product ID')],
  line_items: [text('woo_line_item_id', 'Woo line item ID')],
  // One ticket per distinct sync problem, so re-running the backfill never duplicates tickets.
  tickets: [uniqueId('sync_error_key', 'Sync error key')],
};

const stage = (key, label, displayOrder, metadata) => ({ key, label, displayOrder, metadata });

const DEAL_PIPELINE = {
  label: 'WooCommerce',
  displayOrder: 1,
  stages: [
    stage('pending_payment', 'Pending payment', 0, { probability: '0.2' }),
    stage('paid', 'Paid', 1, { probability: '0.9' }),
    stage('closedwon', 'Closed won', 2, { probability: '1.0' }),
    stage('closedlost', 'Closed lost', 3, { probability: '0.0' }),
    stage('refunded', 'Refunded', 4, { probability: '0.0' }),
  ],
};

const TICKET_PIPELINE = {
  label: 'Integration errors',
  displayOrder: 1,
  stages: [
    stage('new', 'New', 0, { ticketState: 'OPEN' }),
    stage('resolved', 'Resolved', 1, { ticketState: 'CLOSED' }),
  ],
};

// ---- src/lib/retry.js ----
// Retry policy for HubSpot calls (flow F4). Ceiling: 100 requests / 10 s, batches of ≤100.

const MAX_ATTEMPTS = 3;

// 429 = rate limit, 423 = HubSpot's "Locked" during high sync volume, 5xx = transient server errors.
function shouldRetry(status) {
  return status === 429 || status === 423 || (status >= 500 && status <= 599);
}

// Exponential (1 s, 2 s, 4 s…), but never shorter than what the error needs: a 429 without Retry-After
// waits out the whole 10 s rate window; a 423 waits at least 2 s (HubSpot's guidance).
function backoffDelayMs(attempt, retryAfterHeader, status) {
  const retryAfter = Number(retryAfterHeader);
  if (retryAfterHeader != null && Number.isFinite(retryAfter) && retryAfter > 0) return retryAfter * 1000;
  const exponential = 1000 * 2 ** (attempt - 1);
  if (status === 429) return Math.max(exponential, 10000);
  if (status === 423) return Math.max(exponential, 2000);
  return exponential;
}

function chunk(items, size) {
  const out = [];
  for (let i = 0; i < items.length; i += size) out.push(items.slice(i, i + size));
  return out;
}

// ---- src/lib/mapping.js ----
// WooCommerce order → HubSpot CRM inputs. Pure functions, inlined into n8n Code nodes.

// Woo status → internal stage key. Real HubSpot stage ids come from hubspot-setup (.hubspot-ids.json).
const STAGE_BY_STATUS = {
  pending: 'pending_payment',
  'on-hold': 'pending_payment',
  processing: 'paid',
  completed: 'closedwon',
  cancelled: 'closedlost',
  failed: 'closedlost',
  refunded: 'refunded',
};

const PAID_STATUSES = new Set(['processing', 'completed']);

const FREE_EMAIL_DOMAINS = new Set([
  'gmail.com', 'googlemail.com', 'hotmail.com', 'outlook.com', 'live.com', 'yahoo.com', 'yahoo.com.ar',
  'icloud.com', 'aol.com', 'proton.me', 'protonmail.com',
]);

const money = (n) => (Math.round(n * 100) / 100).toFixed(2);

function refundTotal(order) {
  return (order.refunds ?? []).reduce((sum, r) => sum + Math.abs(Number(r.total) || 0), 0);
}

function netTotal(order) {
  return Math.max(0, Number(order.total) - refundTotal(order));
}

const isoUtc = (wooGmtDate) => new Date(`${wooGmtDate}Z`).toISOString();

function companyDomain(email) {
  const { value } = validateEmail(email);
  if (!value) return null;
  const domain = value.split('@')[1];
  return FREE_EMAIL_DOMAINS.has(domain) ? null : domain;
}

function planCompanies(orders) {
  const byDomain = new Map();
  for (const order of orders) {
    const domain = companyDomain(order.billing?.email);
    if (!domain) continue;
    const name = String(order.billing?.company ?? '').trim();
    const existing = byDomain.get(domain);
    if (!existing || (existing.name === domain && name)) byDomain.set(domain, { domain, name: name || domain });
  }
  return [...byDomain.values()];
}

function buildContactInput(order) {
  const { clean, issues } = validateCustomer(order.billing);
  const properties = {};
  for (const [key, value] of Object.entries(clean)) if (value) properties[key] = value;
  if (Number(order.customer_id) > 0) properties.woo_customer_id = String(order.customer_id);
  properties.data_quality_status = issues.length ? 'needs_review' : 'ok';
  properties.data_quality_issues = issues.join('; ');
  return { email: clean.email, properties, issues };
}

function buildProductInputs(orders) {
  const byId = new Map();
  for (const order of orders) {
    for (const item of order.line_items ?? []) {
      const id = String(item.product_id);
      if (byId.has(id)) continue;
      byId.set(id, {
        idProperty: 'woo_product_id',
        id,
        properties: { woo_product_id: id, name: item.name, price: money(Number(item.price)), hs_sku: item.sku || undefined },
      });
    }
  }
  return [...byId.values()];
}

function buildDealInput(order, { pipelineId, stageIds }) {
  const stageKey = STAGE_BY_STATUS[order.status];
  if (!stageKey) throw new Error(`Unknown Woo status "${order.status}" on order ${order.id}`);
  const id = String(order.id);
  const name = [order.billing?.first_name, order.billing?.last_name].filter(Boolean).join(' ').trim();
  return {
    idProperty: 'woo_order_id',
    id,
    properties: {
      woo_order_id: id,
      dealname: `Woo #${order.number ?? id}${name ? ` — ${name}` : ''}`,
      pipeline: pipelineId,
      dealstage: stageIds[stageKey],
      amount: order.status === 'refunded' ? money(0) : money(netTotal(order)),
      refund_amount: money(refundTotal(order)),
      closedate: isoUtc(order.date_created_gmt),
      woo_status: order.status,
      deal_currency_code: order.currency,
    },
  };
}

function buildLineItemInputs(order) {
  return (order.line_items ?? []).map((item) => {
    const id = String(item.id);
    return {
      idProperty: 'woo_line_item_id',
      id,
      wooProductId: String(item.product_id),
      properties: {
        woo_line_item_id: id,
        name: item.name,
        quantity: String(item.quantity),
        price: money(Number(item.price)),
        hs_sku: item.sku || undefined,
      },
    };
  });
}

function aggregateCustomer(orders) {
  const paid = orders.filter((o) => PAID_STATUSES.has(o.status));
  const dates = paid.map((o) => o.date_created_gmt.slice(0, 10)).sort();
  return {
    total_orders: paid.length,
    total_revenue: Math.round(paid.reduce((s, o) => s + netTotal(o), 0) * 100) / 100,
    first_order_date: dates[0] ?? null,
    last_order_date: dates.at(-1) ?? null,
  };
}

// ---- src/lib/sync-plan.js ----
// Turns a batch of Woo orders into the ordered list of HubSpot requests the sync-orders workflow makes.
// Every function returns plain request objects { method, path, body, label } — or { skip: true, label }
// when there is nothing to send — so the n8n flow stays linear and every step is unit-tested here.



const BATCH = 100;
const skip = (label) => ({ skip: true, label });
const post = (path, body, label) => ({ method: 'POST', path, body, label });
// Batch writes tolerate 4xx: HubSpot rejects a whole batch for one bad record, and that must become a
// ticket naming the records, not abort the other 99 orders. `ids` lets the ticket say which records.
const batches = (path, inputs, label, idOf = (i) => i.id) =>
  (inputs.length
    ? chunk(inputs, BATCH).map((part, i) => ({
      ...post(path, { inputs: part }, `${label} ${i + 1}`), tolerateClientError: true, ids: part.map(idOf).map(String),
    }))
    : [skip(label)]);
const lower = (s) => String(s ?? '').trim().toLowerCase();

/** Searches `objectType` for records whose `property` is any of `values` (≤100 values per search). */
function searchIn(objectType, property, values, label) {
  const unique = [...new Set(values.map(String))];
  if (!unique.length) return [skip(label)];
  return chunk(unique, BATCH).map((part, i) => post(`/crm/v3/objects/${objectType}/search`, {
    filterGroups: [{ filters: [{ propertyName: property, operator: 'IN', values: part }] }],
    properties: [property],
    limit: BATCH,
  }, `${label} ${i + 1}`));
}

/** For objects HubSpot cannot upsert by our key: update what the search found, create the rest. */
function updateOrCreate(objectType, key, items, found, label) {
  const updates = [];
  const creates = [];
  for (const properties of items) {
    const id = found.get(lower(properties[key]));
    if (id) updates.push({ id, properties });
    else creates.push({ properties });
  }
  const idOf = (i) => i.properties[key];
  const requests = [
    ...(updates.length ? batches(`/crm/v3/objects/${objectType}/batch/update`, updates, `${label} update`, idOf) : []),
    ...(creates.length ? batches(`/crm/v3/objects/${objectType}/batch/create`, creates, `${label} create`, idOf) : []),
  ];
  return requests.length ? requests : [skip(label)];
}

function pipelineContext(dealPipelines, ticketPipelines) {
  const find = (list, def) => {
    const p = (list?.results ?? []).find((x) => x.label === def.label);
    if (!p) throw new Error(`HubSpot pipeline "${def.label}" not found — run scripts/hubspot-setup.mjs first`);
    const ids = {};
    for (const s of def.stages) {
      const stage = p.stages.find((x) => x.label === s.label);
      if (!stage) throw new Error(`Stage "${s.label}" missing in pipeline "${def.label}" — run scripts/hubspot-setup.mjs`);
      ids[s.key] = stage.id;
    }
    return { id: p.id, ids };
  };
  const deals = find(dealPipelines, DEAL_PIPELINE);
  const tickets = find(ticketPipelines, TICKET_PIPELINE);
  return { pipelineId: deals.id, stageIds: deals.ids, ticketPipelineId: tickets.id, ticketStageNewId: tickets.ids.new };
}

function contactRequests(orders, history) {
  const byEmail = new Map();
  for (const order of orders) {
    const contact = buildContactInput(order);
    if (contact.email) byEmail.set(contact.email, contact);
  }
  const inputs = [...byEmail.values()].map(({ email, properties }) => {
    const agg = aggregateCustomer(history.filter((o) => lower(o.billing?.email) === email));
    const extra = Object.fromEntries(Object.entries(agg).filter(([, v]) => v !== null));
    return { idProperty: 'email', id: email, properties: { ...properties, ...extra } };
  });
  return batches('/crm/v3/objects/contacts/batch/upsert', inputs, 'contacts');
}

function companySearchRequest(orders) {
  const domains = planCompanies(orders).map((c) => c.domain);
  if (!domains.length) return skip('company search');
  return post('/crm/v3/objects/companies/search', {
    filterGroups: [{ filters: [{ propertyName: 'domain', operator: 'IN', values: domains }] }],
    properties: ['domain', 'name'],
    limit: BATCH,
  }, 'company search');
}

function companyCreateRequest(orders, searchResponse) {
  const found = idMap([searchResponse], 'domain');
  const inputs = planCompanies(orders)
    .filter((c) => !found.has(c.domain))
    .map((c) => ({ properties: { domain: c.domain, name: c.name } }));
  return inputs.length
    ? batches('/crm/v3/objects/companies/batch/create', inputs, 'company create', (i) => i.properties.domain)[0]
    : skip('company create');
}

const productSearchRequests = (orders) =>
  searchIn('products', 'woo_product_id', buildProductInputs(orders).map((p) => p.id), 'product search');

const productWriteRequests = (orders, searchResponses) => updateOrCreate(
  'products', 'woo_product_id', buildProductInputs(orders).map((p) => p.properties),
  idMap(searchResponses, 'woo_product_id'), 'products',
);

function dealRequests(orders, ctx) {
  const inputs = [];
  const problems = [];
  for (const order of orders) {
    try {
      inputs.push(buildDealInput(order, ctx));
    } catch (err) {
      problems.push({
        key: `unknown-status:${order.id}`,
        subject: `Woo order #${order.number ?? order.id} not synced: unknown status`,
        content: err.message,
        priority: 'HIGH',
      });
    }
  }
  return { requests: batches('/crm/v3/objects/deals/batch/upsert', inputs, 'deals'), problems };
}

const lineItemSearchRequests = (orders) =>
  searchIn('line_items', 'woo_line_item_id', orders.flatMap(buildLineItemInputs).map((li) => li.id), 'line item search');

function lineItemWriteRequests(orders, productIds, searchResponses) {
  const items = orders.flatMap(buildLineItemInputs).map(({ wooProductId, properties }) => {
    const hsProductId = productIds.get(wooProductId);
    return hsProductId ? { ...properties, hs_product_id: hsProductId } : properties;
  });
  return updateOrCreate('line_items', 'woo_line_item_id', items, idMap(searchResponses, 'woo_line_item_id'), 'line items');
}

/** value of `property` (lowercased) → HubSpot record id, from any number of batch/search responses. */
function idMap(responses, property) {
  const map = new Map();
  for (const r of responses) {
    for (const rec of r?.body?.results ?? []) {
      const value = rec.properties?.[property];
      if (value != null) map.set(lower(value), String(rec.id));
    }
  }
  return map;
}

function associationRequests({ orders, contactIds, companyIds, dealIds, lineItemIds }) {
  const pairs = { 'contacts/companies': new Map(), 'deals/contacts': new Map(), 'deals/companies': new Map(), 'line_items/deals': new Map() };
  const add = (kind, from, to) => { if (from && to) pairs[kind].set(`${from}>${to}`, { from: { id: from }, to: { id: to } }); };
  for (const order of orders) {
    const email = lower(order.billing?.email);
    const contactId = contactIds.get(email);
    const companyId = companyIds.get(companyDomain(email) ?? '');
    const dealId = dealIds.get(String(order.id));
    add('contacts/companies', contactId, companyId);
    add('deals/contacts', dealId, contactId);
    add('deals/companies', dealId, companyId);
    for (const item of order.line_items ?? []) add('line_items/deals', lineItemIds.get(String(item.id)), dealId);
  }
  return Object.entries(pairs).map(([kind, map]) => (map.size
    ? { ...post(`/crm/v4/associations/${kind}/batch/associate/default`, { inputs: [...map.values()] }, `associate ${kind}`),
      tolerateClientError: true, ids: [...map.keys()] }
    : skip(`associate ${kind}`)));
}

function syncProblems(orders, responses, extra = []) {
  const problems = [];
  for (const order of orders) {
    const contact = buildContactInput(order);
    if (!contact.email) {
      problems.push({
        key: `no-contact:${order.id}`,
        subject: `Woo order #${order.number ?? order.id} synced without a contact`,
        content: `Billing email "${order.billing?.email ?? ''}" was rejected (${contact.issues.join('; ')}). `
          + 'The deal was synced; fix the email in WooCommerce and save the order to link a contact.',
        priority: 'MEDIUM',
      });
    }
  }
  for (const r of responses) {
    if (r && r.ok === false) {
      const ids = r.ids ?? [];
      problems.push({
        key: `batch-failed:${String(r.label).replace(/ \d+$/, '')}:${ids[0] ?? 'none'}..${ids.at(-1) ?? 'none'}`,
        subject: `HubSpot rejected a whole ${r.label} batch (${ids.length} records)`,
        content: `HTTP ${r.status} ${r.body?.category ?? ''}: ${r.body?.message ?? JSON.stringify(r.body ?? '')}
`
          + `Records: ${ids.join(', ')}`.slice(0, 1800),
        priority: 'HIGH',
      });
      continue;
    }
    for (const e of r?.body?.errors ?? []) {
      for (const id of e.context?.ids ?? ['unknown']) {
        problems.push({
          key: `batch:${String(r.label).replace(/ \d+$/, '')}:${id}`,
          subject: `HubSpot rejected ${r.label} record ${id}`,
          content: `${e.category ?? 'ERROR'}: ${e.message ?? ''}`.slice(0, 2000),
          priority: 'HIGH',
        });
      }
    }
  }
  return [...problems, ...extra];
}

function ticketReadRequest(problems) {
  if (!problems.length) return skip('ticket lookup');
  return searchIn('tickets', 'sync_error_key', problems.slice(0, BATCH).map((p) => p.key), 'ticket lookup')[0];
}

function ticketCreateRequest(problems, readResponse, ctx) {
  const existing = idMap([readResponse], 'sync_error_key');
  const inputs = problems.slice(0, BATCH)
    .filter((p) => !existing.has(lower(p.key)))
    .map((p) => ({
      properties: {
        sync_error_key: p.key,
        subject: p.subject,
        content: p.content,
        hs_pipeline: ctx.ticketPipelineId,
        hs_pipeline_stage: ctx.ticketStageNewId,
        hs_ticket_priority: p.priority,
      },
    }));
  return inputs.length
    ? batches('/crm/v3/objects/tickets/batch/create', inputs, 'tickets', (i) => i.properties.sync_error_key)[0]
    : skip('tickets');
}

// ---- step ----
const input = $('Sync in').first().json;
const orders = input.orders;
const history = input.history ?? orders;
const responses = (node) => $(node).all().map((item) => item.json);
const ctx = () => { const [deals, tickets] = responses('Get pipelines'); return pipelineContext(deals.body, tickets.body); };
const out = (requests) => [].concat(requests).map((json) => ({ json }));
const count = (node) => responses(node).reduce((n, r) => n + (r.body?.results?.length ?? 0), 0);
return [{ json: {
  orders: orders.length,
  contacts: count('Upsert contacts'),
  companiesCreated: count('Create companies'),
  products: count('Upsert products'),
  deals: count('Upsert deals'),
  lineItems: count('Upsert line items'),
  associations: count('Associate'),
  ticketsCreated: count('Create tickets'),
  rejectedBatches: ['Upsert contacts', 'Create companies', 'Upsert products', 'Upsert deals', 'Upsert line items', 'Associate']
    .flatMap(responses).filter((r) => r.ok === false).length,
  requests: ['Get pipelines', 'Upsert contacts', 'Search companies', 'Create companies', 'Search products', 'Upsert products',
    'Upsert deals', 'Search line items', 'Upsert line items', 'Associate', 'Find tickets', 'Create tickets']
    .flatMap(responses).filter((r) => !r.skipped).length,
} }];
